["import random
import threading

class Team:
    def __init__(self, name):
        self.name = name
        self.goals = 0

    def shoot(self):
        # 50% chance of scoring
        if random.random() < 0.5:
            self.goals += 1
            return True
        else:
            return False

class HockeyGame:
    def __init__(self, team_a, team_b):
        self.team_a = team_a
        self.team_b = team_b
        self.period = 1
        self.minute = 0
        self.stop_simulation = False

    def simulate_period(self):
        for _ in range(20):
            if self.stop_simulation:
                return

            self.minute += 1
            if self.team_a.shoot():
                print(f"{self.team_a.name} scores! ({self.team_a.goals}-{self.team_b.goals})")
            if self.team_b.shoot():
                print(f"{self.team_b.name} scores! ({self.team_a.goals}-{self.team_b.goals})")

            print(f"Period: {self.period}, Minute: {self.minute}, Score: {self.team_a.goals}-{self.team_b.goals}")

        self.period += 1
        self.minute = 0

    def simulate_overtime(self):
        while not self.stop_simulation:
            self.minute += 1
            if self.team_a.shoot():
                print(f"{self.team_a.name} scores in overtime! ({self.team_a.goals}-{self.team_b.goals})")
                return self.team_a
            if self.team_b.shoot():
                print(f"{self.team_b.name} scores in overtime! ({self.team_a.goals}-{self.team_b.goals})")
                return self.team_b

            print(f"Overtime Minute: {self.minute}, Score: {self.team_a.goals}-{self.team_b.goals}")
        return None

def stop_simulation_input(game):
    while not game.stop_simulation:
        user_input = input("Press 'q' to quit: ")
        if user_input.lower() == 'q':
            game.stop_simulation = True

def main():
    team_a = Team("Team A")
    team_b = Team("Team B")

    game = HockeyGame(team_a, team_b)

    # Start a thread to handle user input
    input_thread = threading.Thread(target=stop_simulation_input, args=(game,))
    input_thread.start()

    for _ in range(3):
        if game.stop_simulation:
            break
        game.simulate_period()
        print(f"\nEnd of period {game.period-1}. Score: {team_a.goals}-{team_b.goals}\n")

    if game.stop_simulation:
        print(f"Simulation stopped. Final Score: {team_a.goals}-{team_b.goals}")
        return

    if team_a.goals > team_b.goals:
        print(f"{team_a.name} wins!")
    elif team_b.goals > team_a.goals:
        print(f"{team_b.name} wins!")
    else:
        print("Game is tied. Going into overtime.")
        winner = game.simulate_overtime()
        if winner:
            print(f"{winner.name} wins!")
        else:
            print(f"Simulation stopped during overtime. Current Score: {team_a.goals}-{team_b.goals}")

if __name__ == "__main__":
    main()"]

["def find_path(graph, start, end):
    """
    Finds any valid path between start and end nodes.
    """
    def dfs(current, target, visited):
        if current == target:
            return [current]

        visited.add(current)

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                path = dfs(neighbor, target, visited)
                if path:
                    return [current] + path

        visited.remove(current)
        return None

    return dfs(start, end, set())

def find_all_path(graph, start, end):
    """
    Finds all valid paths between start and end nodes.
    """
    def dfs(current, target, visited, path, all_paths):
        path.append(current)
        visited.add(current)

        if current == target:
            all_paths.append(path.copy())
        else:
            for neighbor in graph.get(current, []):
                if neighbor not in visited:
                    dfs(neighbor, target, visited, path, all_paths)

        path.pop()
        visited.remove(current)

    all_paths = []
    dfs(start, end, set(), [], all_paths)
    return all_paths

def find_shortest_path(graph, start, end):
    """
    Finds the shortest path based on the number of edges between start and end nodes.
    """
    from collections import deque

    queue = deque([(start, [start])])
    visited = set()

    while queue:
        current, path = queue.popleft()

        if current == end:
            return path

        visited.add(current)

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))
                visited.add(neighbor)

    return None"]

