["from datetime import date, datetime

def calculate_age(birthdate: date, unit: str) -> float:
    """
    Calculates the age of a user in the specified units (years, months, days, weeks, hours).
    Handles leap years and variable length of months.
    """
    today = datetime.now().date()
    delta = today - birthdate

    if unit.lower() == 'years':
        age_in_years = delta.days / 365.25  # Considering leap years
        return round(age_in_years, 2)
    elif unit.lower() == 'months':
        age_in_months = delta.days / 30.4375  # Average days in a month considering leap years
        return round(age_in_months, 2)
    elif unit.lower() == 'days':
        return round(delta.days, 2)
    elif unit.lower() == 'weeks':
        age_in_weeks = delta.days / 7
        return round(age_in_weeks, 2)
    elif unit.lower() == 'hours':
        age_in_hours = delta.days * 24
        return round(age_in_hours, 2)
    else:
        raise ValueError("Unsupported unit. Choose from 'years', 'months', 'days', 'weeks', 'hours'.")"]

