def can_return_books(borrowed: List[str], permissible: List[str]) -> bool:
    """
    Determines if the borrowed books can be returned in the permissible order.
    """
    permissible_index = {book: i for i, book in enumerate(permissible)}
    last_index = -1

    for book in borrowed:
        # Check if the current book's permissible index is greater than last_index
        if permissible_index[book] < last_index:
            return False
        last_index = permissible_index[book]

    return True"]

