["class ResizableHashTable:
    def __init__(self, initial_size=8):
        self.size = initial_size
        self.table = [None] * self.size
        self.count = 0

    def hash_function(self, key):
        return key % self.size

    def put(self, key, value):
        pos = self.hash_function(key)
        initial_pos = pos
        collisions = 0

        while self.table[pos] is not None:
            if self.table[pos][0] == key:
                self.table[pos] = (key, value)
                return
            collisions += 1
            pos = (pos + 1) % self.size

        self.table[pos] = (key, value)
        self.count += 1
        self.collisions += collisions

        if self.count / self.size > self.load_factor_threshold:
            self.resize()

    def get(self, key):
        pos = self.hash_function(key)
        while self.table[pos] is not None:
            if self.table[pos][0] == key:
                return self.table[pos][1]
            pos = (pos + 1) % self.size
        return None

    def resize(self):
        old_table = self.table
        self.size *= 2
        self.table = [None] * self.size
        self.count = 0
        for item in old_table:
            if item is not None:
                self.put(item[0], item[1])

class AnalyticalHashTable(ResizableHashTable):
    def __init__(self, initial_size=8, load_factor_threshold=0.75):
        super().__init__(initial_size)
        self.load_factor_threshold = load_factor_threshold
        self.collisions = 0
        self.insert_operations = 0

    def put(self, key, value):
        pos = self.hash_function(key)
        initial_pos = pos
        collisions = 0
        self.insert_operations += 1

        while self.table[pos] is not None:
            if self.table[pos][0] == key:
                self.table[pos] = (key, value)
                return
            collisions += 1
            pos = (pos + 1) % self.size

        self.table[pos] = (key, value)
        self.count += 1
        self.collisions += collisions

        if self.count / self.size > self.load_factor_threshold:
            self.resize()

    def current_load_factor(self):
        return self.count / self.size

    def average_collision_length(self):
        if self.insert_operations == 0:
            return 0
        return self.collisions / self.insert_operations"]

