["import heapq
import sys

def find_shortest_path(n, edges, start, end):
    graph = [[] for _ in range(n + 1)]
    for edge in edges:
        u, v, w = edge
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra(source):
        distances = [sys.maxsize] * (n + 1)
        distances[source] = 0
        priority_queue = [(0, source)]  # (distance, node)
        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))
        return distances

    from_start = dijkstra(start)
    from_end = dijkstra(end)

    direct_path = from_start[end]
    if direct_path == sys.maxsize:
        return -1

    best_path = direct_path
    for i in range(2, n):
        if from_start[i] != sys.maxsize and from_end[i] != sys.maxsize:
            best_path = min(best_path, from_start[i] + from_end[i])

    return best_path

def solve(t, test_cases):
    results = []
    for i in range(t):
        n, m = test_cases[i][0]
        edges = test_cases[i][1:]
        result = find_shortest_path(n, edges, 1, n)
        results.append(result)
    return results"]

