["def can_partition_into_equal_groups(T, test_cases):
    results = []
    for i in range(T):
        N, K = test_cases[i][0]
        W = test_cases[i][1]

        total_weight = sum(W)

        if total_weight % K != 0:
            results.append("NO")
            continue

        target_weight = total_weight // K
        W.sort(reverse=True)

        buckets = [0] * K

        def can_partition(index):
            if index == N:
                return all(bucket == target_weight for bucket in buckets)

            for i in range(K):
                if buckets[i] + W[index] <= target_weight:
                    buckets[i] += W[index]
                    if can_partition(index + 1):
                        return True
                    buckets[i] -= W[index]

                if buckets[i] == 0:
                    break

            return False

        if can_partition(0):
            results.append("YES")
        else:
            results.append("NO")

    return results"]

