    pairs = {')': '(', '}': '{', ']': '['}
    count = 0

    for char in s:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs:
            if stack and stack[-1] == pairs[char]:
                stack.pop()
                count += 1
            else:
                return 0  # invalid sequence, so return 0 immediate

    return count"]

