["def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    def dfs(matrix, visited, height, x, y):
        m, n = len(matrix), len(matrix[0])
        if (x < 0 or x >= m or y < 0 or y >= n or 
            visited[x][y] or matrix[x][y] < height):
            return
        visited[x][y] = True
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            dfs(matrix, visited, matrix[x][y], x+dx, y+dy)

    m, n = len(matrix), len(matrix[0])
    pacific_visited = [[False]*n for _ in range(m)]
    atlantic_visited = [[False]*n for _ in range(m)]

    for i in range(m):
        dfs(matrix, pacific_visited, float('-inf'), i, 0)
        dfs(matrix, atlantic_visited, float('-inf'), i, n-1)

    for j in range(n):
        dfs(matrix, pacific_visited, float('-inf'), 0, j)
        dfs(matrix, atlantic_visited, float('-inf'), m-1, j)

    result = []
    for i in range(m):
        for j in range(n):
            if pacific_visited[i][j] and atlantic_visited[i][j]:
                result.append([i, j])

    return result"]

