["def countReachableCells(grid, waterLevel):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False for _ in range(n)] for _ in range(m)]

    def is_valid(x, y):
        return 0 <= x < m and 0 <= y < n and not visited[x][y] and grid[x][y] > waterLevel

    def dfs(x, y):
        stack = [(x, y)]
        count = 0

        while stack:
            cx, cy = stack.pop()
            if not is_valid(cx, cy):
                continue
            visited[cx][cy] = True
            count += 1
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny):
                    stack.append((nx, ny))

        return count

    reachable_cells = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] > waterLevel and not visited[i][j]:
                reachable_cells += dfs(i, j)

    return reachable_cells"]

