["from typing import List

def longest_arithmetic_subsequence(arr: List[int]) -> int:
    if len(arr) <= 1:
        return len(arr)

    # Dictionary to store lengths of arithmetic subsequences with common differences for each index
    dp = [{} for _ in range(len(arr))]
    max_length = 1

    for i in range(1, len(arr)):
        for j in range(i):
            diff = arr[i] - arr[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length"]

["from typing import List

def combinationSum2(nums: List[int], target: int) -> List[List[int]]:
    def backtrack(start, end, target, path):
        if target == 0:
            results.append(path)
            return
        for i in range(start, end):
            if i > start and nums[i] == nums[i - 1]:
                continue
            if nums[i] > target:
                break
            backtrack(i + 1, end, target - nums[i], path + [nums[i]])

    # Sort the array to handle duplicates and to improve efficiency
    nums.sort()
    results = []
    backtrack(0, len(nums), target, [])
    return results"]

