    n = len(grid)
    m = len(grid[0])
    moves = 0

    for i in range(n - 1):
        for j in range(m - 1):
            if grid[i][j] == 1:
                moves += 1
                grid[i][j] ^= 1
                grid[i+1][j] ^= 1
                grid[i][j+1] ^= 1
                grid[i+1][j+1] ^= 1

    for i in range(n):
        if grid[i][m-1] == 1:
            return -1

    for j in range(m):
