def shortest_path(grid):
    n = len(grid)
    m = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    queue = deque([(0, 0, 0)])  # (row, column, distance)
    grid[0][0] = '#'  # Mark as visited

