["def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])
        return parent[i]

def union(parent, rank, x, y):
    root_x = find(parent, x)
    root_y = find(parent, y)

    if root_x != root_y:
        if rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        elif rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            rank[root_x] += 1

def kruskal(n, roads):
    parent = []
    rank = []
    result = 0
    edges_included = 0

    for node in range(n):
        parent.append(node)
        rank.append(0)

    roads = sorted(roads, key=lambda x: x[2])

    for road in roads:
        u, v, w = road
        root_u = find(parent, u - 1)
        root_v = find(parent, v - 1)

        if root_u != root_v:
            result += w
            edges_included += 1
            union(parent, rank, root_u, root_v)

        if edges_included == n - 1:
            return result

    return -1

def min_cost_to_connect_cities(n, m, roads):
    if n == 0 or m == 0:
        return -1
    return kruskal(n, roads)

# Example
n = 4
m = 5
roads = [
    (1, 2, 3),
    (2, 3, 1),
    (3, 4, 4),
    (2, 4, 2),
    (1, 4, 5)
]
print(min_cost_to_connect_cities(n, m, roads))  # Output: 6"]

