["def sieve_of_eratosthenes(max_num):
    """
    Helper function to generate a list of primes up to max_num using the Sieve of Eratosthenes.
    """
    is_prime = [True] * (max_num + 1)
    is_prime[0], is_prime[1] = False, False

    for start in range(2, int(max_num ** 0.5) + 1):
        if is_prime[start]:
            for multiple in range(start * start, max_num + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def count_primes_in_interval(L, R):
    """
    Returns the number of prime numbers in the interval [L, R] (both inclusive).
    """
    if L < 1 or R < 1 or L > R or R > 10**6:
        raise ValueError("Inputs should be in range 1 ≤ L ≤ R ≤ 10^6")

    primes = sieve_of_eratosthenes(R)
    count = 0
    for prime in primes:
        if L <= prime <= R:
            count += 1
    return count"]

