["def unique_paths(grid):
    """
    Returns the number of unique paths from the top-left to the bottom-right corner steping only into empty cells ('.').
    """
    n = len(grid)
    if grid[0][0] == '#' or grid[n-1][n-1] == '#':
        return 0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1  # Starting point

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]"]

