["def manage_stock(datasets):
    results = []

    for dataset in datasets:
        transactions = dataset["transactions"]
        queries = dataset["queries"]

        stock_changes = {}

        for trans in transactions:
            t, i, v, a = trans
            if i not in stock_changes:
                stock_changes[i] = [0] * 1440
            if a == 1:
                stock_changes[i][t] += v
            else:
                stock_changes[i][t] -= v

        # Create prefix sum for each item to easily calculate stock changes over time ranges
        prefix_sum = {}
        for i in stock_changes:
            prefix_sum[i] = [0] * 1440
            prefix_sum[i][0] = stock_changes[i][0]
            for t in range(1, 1440):
                prefix_sum[i][t] = prefix_sum[i][t-1] + stock_changes[i][t]

        for query in queries:
            ts, te, i = query
            if i not in prefix_sum:
                results.append(0)
            else:
                if ts == 0:
                    results.append(prefix_sum[i][te])
                else:
                    results.append(prefix_sum[i][te] - prefix_sum[i][ts-1])

    return results

def process_input(input_data):
    lines = input_data.split("\n")
    datasets = []
    idx = 0

    while idx < len(lines):
        line = lines[idx]
        if line == "0 0":
            break
        n, t = map(int, line.split())

        transactions = []
        for _ in range(t):
            idx += 1
            transactions.append(list(map(int, lines[idx].split())))

        idx += 1
        q = int(lines[idx])

        queries = []
        for _ in range(q):
            idx += 1
            queries.append(list(map(int, lines[idx].split())))

        datasets.append({
            "transactions": transactions,
            "queries": queries
        })

        idx += 1

    return datasets

def warehouse_stock_management(input_data):
    datasets = process_input(input_data)
    return manage_stock(datasets)"]

