def tree_diameter(edges):
    if not edges:
        return 0

    def bfs(start_node):
        queue = deque([start_node])
        distances = {start_node: 0}
        farthest_node = start_node

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in distances:
                    queue.append(neighbor)
                    distances[neighbor] = distances[node] + 1
                    if distances[neighbor] > distances[farthest_node]:
                        farthest_node = neighbor

        return farthest_node, distances[farthest_node]

    # Create the graph from the edges
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Start BFS from an arbitrary node (node 1)
    start_node = edges[0][0]
    farthest_node, _ = bfs(start_node)

    # Perform BFS again from the farthest node found
    other_end, diameter = bfs(farthest_node)

    return diameter"]

