["def num_unique_paths(R, C, grid):
    # If start or end is blocked, return "Impossible"
    if grid[0][0] == '#' or grid[R-1][C-1] == '#':
        return "Impossible"

    dp = [[0 for _ in range(C)] for _ in range(R)]
    dp[0][0] = 1

    for i in range(R):
        for j in range(C):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[R-1][C-1] if dp[R-1][C-1] != 0 else "Impossible"


def parse_input(input_str):
    lines = input_str.split('\n')
    index = 0
    results = []

    while index < len(lines):
        R, C = map(int, lines[index].split())
        if R == 0 and C == 0:
            break
        index += 1
        grid = []
        for _ in range(R):
            grid.append(lines[index])
            index += 1
        result = num_unique_paths(R, C, grid)
        results.append(result)

    return results"]

