["import random

def is_prime(n: int, k: int) -> bool:
    """
    Determine if a number n is "probably prime" using the Rabin-Miller primality test with k iterations.

    :param n: Positive integer to be tested for primality.
    :param k: Number of iterations for accuracy.
    :return: False if n is definitely composite, True if n is probably prime.
    """
    # Handle edge cases
    if n <= 1:
        return False
    if n <= 3:
        return True if n > 1 else False
    if n % 2 == 0:
        return False

    # Write n-1 as d*2^r where d is odd
    def decompose(n):
        r, d = 0, n - 1
        while d % 2 == 0:
            r += 1
            d //= 2
        return r, d

    r, d = decompose(n)

    # Perform k tests
    def miller_rabin_test(a, r, d, n):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return True
        return False

    for _ in range(k):
        a = random.randint(2, n - 2)
        if not miller_rabin_test(a, r, d, n):
            return False

    return True"]

