def find_kth_smallest_element(tree, k):
    """
    Traverses the B-tree in-order and finds the k-th smallest element.
    """
    def inorder_traversal(node, result):
        if node is not None:
            for i in range(len(node.keys) + 1):
                if i < len(node.children):
                    inorder_traversal(node.children[i], result)
                if i < len(node.keys):
                    result.append(node.keys[i])

    result = []
    inorder_traversal(tree.root, result)
