["from collections import deque

def shortest_subarray_with_sum_at_least_k(arr, k):
    n = len(arr)
    prefix_sums = [0] * (n + 1)

    for i in range(n):
        prefix_sums[i + 1] = prefix_sums[i] + arr[i]

    result = float('inf')
    mono_queue = deque()

    for i in range(n + 1):
        while mono_queue and prefix_sums[i] - prefix_sums[mono_queue[0]] >= k:
            result = min(result, i - mono_queue.popleft())

        while mono_queue and prefix_sums[i] <= prefix_sums[mono_queue[-1]]:
            mono_queue.pop()

        mono_queue.append(i)

    return result if result != float('inf') else -1"]

