["from collections import defaultdict, deque

def find_cycle(n, m, edges):
    def dfs(v):
        nonlocal cycle
        visited[v] = 1
        stack.append(v)

        for neighbor in adj_list[v]:
            if visited[neighbor] == 0:
                if dfs(neighbor):
                    return True
            elif visited[neighbor] == 1:
                # Cycle detected
                cycle = []
                stack_pos = len(stack) - 1
                while stack[stack_pos] != neighbor:
                    cycle.append(stack[stack_pos])
                    stack_pos -= 1
                cycle.append(neighbor)
                cycle.reverse()
                cycle.append(neighbor)
                return True

        visited[v] = 2
        stack.pop()
        return False

    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    visited = [0] * (n + 1)
    stack = []
    cycle = []

    for i in range(1, n + 1):
        if visited[i] == 0:
            if dfs(i):
                return ("YES", cycle)

    return ("NO",)

def process_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    edges = []
    for i in range(m):
        u = int(data[2 + 2 * i])
        v = int(data[3 + 2 * i])
        edges.append((u, v))

    result = find_cycle(n, m, edges)
    if result[0] == "YES":
        print(result[0])
        print(" ".join(map(str, result[1])))
    else:
        print(result[0])"]

