class Player:
    def __init__(self, name):
        self.name = name
        self.position = 0

class Board:
    def __init__(self):
        self.shortcuts = {10: 20, 30: 20, 50: 20, 70: 20, 90: 20}
        self.players = []
        self.final_space = 100

    def roll_die(self):
        return random.randint(1, 6)

    def move_player(self, player, num_spaces):
        player.position += num_spaces
        if player.position > self.final_space:
            player.position = self.final_space

    def check_for_win(self, player):
        return player.position >= self.final_space

    def apply_shortcut(self, player):
        if player.position in self.shortcuts:
            player.position += self.shortcuts[player.position]
            if player.position > self.final_space:
                player.position = self.final_space

    def check_for_collision(self, player1, player2):
        if player1.position == player2.position:
            player2.position = 0

def play_game(player1, player2):
    board = Board()
    current_player_idx = 0
    players = [player1, player2]

    while True:
        current_player = players[current_player_idx]
        spaces_to_move = board.roll_die()
        board.move_player(current_player, spaces_to_move)

        if board.check_for_win(current_player):
            return current_player.name

        board.apply_shortcut(current_player)
        board.check_for_collision(player1, player2 if current_player == player1 else player1)

        current_player_idx = (current_player_idx + 1) % 2"]

["import heapq

def trapRainWater(mat):
    if not mat or not mat[0]:
        return 0

    n = len(mat)
    m = len(mat[0])
    heap = []
    visited = [[False] * m for _ in range(n)]

    # Push all the boundary cells into the heap
    for i in range(n):
        for j in range(m):
            if i == 0 or j == 0 or i == n-1 or j == m-1:
                heapq.heappush(heap, (mat[i][j], i, j))
                visited[i][j] = True

    # To store the directions for 4-side exploration (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    water_trapped = 0
    while heap:
        height, x, y = heapq.heappop(heap)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - mat[nx][ny])
                heapq.heappush(heap, (max(height, mat[nx][ny]), nx, ny))

    return water_trapped"]

["class HashTable:
    def __init__(self):
        self.capacity = 4
        self.size = 0
        self.table = [None] * self.capacity
        self.deleted = None

    def hash(self, key):
        return hash(key) % self.capacity

    def put(self, key, value):
        if self.size / self.capacity >= 0.7:
            self.__resize(2 * self.capacity)

        index = self.hash(key)
        original_index = index

        while self.table[index] is not None and self.table[index][0] != key:
            index = (index + 1) % self.capacity
            if index == original_index:
                raise Exception("Hash table is full")

        if self.table[index] is None:
            self.size += 1

        self.table[index] = (key, value)

    def get(self, key):
        index = self.hash(key)
        original_index = index

        while self.table[index] is not None:
            if self.table[index][0] == key:
                return self.table[index][1]
            index = (index + 1) % self.capacity
            if index == original_index:
                break

        return None

    def del_(self, key):
        index = self.hash(key)
        original_index = index

        while self.table[index] is not None:
            if self.table[index][0] == key:
                self.deleted = self.table[index]
                self.table[index] = None
                self.size -= 1
                self.__rehash(index)
                if self.size / self.capacity < 1/3:
                    self.__resize(self.capacity // 2)
                return
            index = (index + 1) % self.capacity
            if index == original_index:
                break

    def undel(self, key):
        if self.deleted and self.deleted[0] == key:
            self.put(*self.deleted)
            self.deleted = None

    def __resize(self, new_size):
        old_table = self.table
        self.capacity = new_size
        self.size = 0
        self.table = [None] * self.capacity

        for item in old_table:
            if item is not None:
                self.put(item[0], item[1])

    def __rehash(self, start_index):
        index = (start_index + 1) % self.capacity
        while self.table[index] is not None:
            key, value = self.table[index]
            self.table[index] = None
            self.size -= 1
            self.put(key, value)
            index = (index + 1) % self.capacity"]

["def enhanced_cycle_sort(arr):
    """
    Function to sort an array using the cycle sort algorithm modified
    to handle negative integer values as well.
    This sort is in-place and has a time complexity of O(N^2) in the worst case.
    """
    writes = 0

    for cycleStart in range(0, len(arr) - 1):
        item = arr[cycleStart]

        pos = cycleStart
        for i in range(cycleStart + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        if pos == cycleStart:
            continue

        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        while pos != cycleStart:
            pos = cycleStart
            for i in range(cycleStart + 1, len(arr)):
                if arr[i] < item:
                    pos += 1
            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr"]

