["class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree_from_level_order(level_order):
    if not level_order:
        return None
    root = TreeNode(level_order[0])
    queue = [root]
    i = 1
    while queue and i < len(level_order):
        current = queue.pop(0)
        if i < len(level_order) and level_order[i] != -1:
            current.left = TreeNode(level_order[i])
            queue.append(current.left)
        i += 1
        if i < len(level_order) and level_order[i] != -1:
            current.right = TreeNode(level_order[i])
            queue.append(current.right)
        i += 1
    return root

def tree_sum(root):
    if not root:
        return 0
    return root.val + tree_sum(root.left) + tree_sum(root.right)

def tree_height(root):
    if not root:
        return 0
    return max(tree_height(root.left), tree_height(root.right)) + 1

def tree_max_value(root):
    if not root:
        return float('-inf')
    return max(root.val, tree_max_value(root.left), tree_max_value(root.right))

def process_queries(queries):
    results = []
    for query in queries:
        n, level_order = query
        root = build_tree_from_level_order(level_order)
        sum_of_nodes = tree_sum(root)
        height = tree_height(root)
        max_value = tree_max_value(root)
        results.append((sum_of_nodes, height, max_value))
    return results"]

