        self.bit = [0] * (self.n + 1)
        for i in range(self.n):
            self.update(i, freq[i])

    def update(self, index: int, value: int):
        index += 1
        while index <= self.n:
            self.bit[index] += value
            index += index & -index

    def query(self, index: int) -> int:
        sum = 0
        index += 1
        while index > 0:
            sum += self.bit[index]
            index -= index & -index
        return sum

