["def find_articulation_points(graph: dict[int, list[int]]) -> list[int]:
    """
    Return the sorted list of articulation points [v1, v2, ..., vk]
    """
    def dfs(at, parent, visited, disc, low, time, articulation_points):
        children = 0
        visited[at] = True
        disc[at] = low[at] = time[0]
        time[0] += 1

        for to in graph[at]:
            if not visited[to]:
                children += 1
                dfs(to, at, visited, disc, low, time, articulation_points)
                low[at] = min(low[at], low[to])

                if parent == -1 and children > 1:
                    articulation_points.add(at)
                if parent != -1 and low[to] >= disc[at]:
                    articulation_points.add(at)

            elif to != parent:
                low[at] = min(low[at], disc[to])

    visited = {}
    disc = {}
    low = {}
    articulation_points = set()
    time = [0]

    for vertex in graph:
        visited[vertex] = False
        disc[vertex] = float('inf')
        low[vertex] = float('inf')

    for vertex in graph:
        if not visited[vertex]:
            dfs(vertex, -1, visited, disc, low, time, articulation_points)

    return sorted(list(articulation_points))"]

