["class DirectedGraph:
    def __init__(self, graph):
        """
        Initializes the directed graph.
        :param graph: dict[str, list[str]]
        """
        self.graph = graph

    def detect_cycle(self):
        """
        Detects if there is any cycle in the graph using DFS.
        :return: bool
        """
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {node: WHITE for node in self.graph}

        def dfs(node):
            if color[node] == GRAY:
                return True  # Found cycle
            if color[node] == BLACK:
                return False  # Already processed
            color[node] = GRAY
            for neighbor in self.graph[node]:
                if dfs(neighbor):
                    return True
            color[node] = BLACK
            return False

        for node in self.graph:
            if color[node] == WHITE:
                if dfs(node):
                    return True
        return False

    def remove_cycles(self):
        """
        Remove cycles from the graph by removing the necessary edges.
        """
        def dfs(node, stack, visited):
            if node in stack:
                cycle_start_index = stack.index(node)
                cycle = stack[cycle_start_index:]
                return cycle
            if node not in visited:
                stack.append(node)
                visited.add(node)
                for neighbor in self.graph[node]:
                    cycle = dfs(neighbor, stack, visited)
                    if cycle:
                        return cycle
                stack.pop()
            return None

        while self.detect_cycle():
            visited = set()
            cycle = None
            for node in self.graph:
                if node not in visited:
                    cycle = dfs(node, [], visited)
                    if cycle:
                        break
            if cycle:
                # Remove an edge to break the cycle
                to_remove = cycle[-1]
                for node in cycle:
                    if to_remove in self.graph[node]:
                        self.graph[node].remove(to_remove)
                        break"]

