["def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while (i * i) <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_smallest_odd_prime_index(nums):
    """
    Returns the index of the smallest odd prime number in the given list.
    Also returns the smallest odd prime number found in the list.
    """
    smallest_odd_prime = float('inf')
    smallest_idx = -1
    for idx, num in enumerate(nums):
        if num % 2 != 0 and is_prime(num):
            if num < smallest_odd_prime:
                smallest_odd_prime = num
                smallest_idx = idx
            elif num == smallest_odd_prime:
                smallest_idx = min(smallest_idx, idx)
    return smallest_idx, smallest_odd_prime"]

