["from typing import List, Union

def evaluate_expressions(expressions: List[str]) -> List[Union[float, str]]:
    """
    Evaluates a list of arithmetic expressions.
    Parameters:
    - expressions (List[str]): A list of strings where each string is an arithmetic expression.

    Returns:
    - List[Union[float, str]]: List of evaluation results or "ERROR" for invalid expressions.
    """
    results = []

    for expr in expressions:
        try:
            # Split the expression by identifying the operator position
            if '+' in expr:
                parts = expr.split('+')
                op = '+'
            elif '-' in expr:
                parts = expr.split('-')
                op = '-'
            elif '*' in expr:
                parts = expr.split('*')
                op = '*'
            elif '/' in expr:
                parts = expr.split('/')
                op = '/'
            else:
                results.append("ERROR")
                continue

            # There should be exactly 2 parts
            if len(parts) != 2:
                results.append("ERROR")
                continue

            # Convert parts to integers
            part1 = parts[0].strip()
            part2 = parts[1].strip()

            num1 = int(part1)
            num2 = int(part2)

            # Perform the operation
            if op == '+':
                results.append(num1 + num2)
            elif op == '-':
                results.append(num1 - num2)
            elif op == '*':
                results.append(num1 * num2)
            elif op == '/':
                if num2 == 0:
                    results.append("ERROR")
                else:
                    results.append(num1 / num2)
        except:
            results.append("ERROR")

    return results"]

