["from collections import defaultdict, deque

def longest_path_no_consecutive_same_weight(n, m, edges):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def bfs(start):
        max_length = 0
        visited = set()
        queue = deque([(start, -1, 0)])  # (current vertex, previous weight, path length)

        while queue:
            u, prev_weight, length = queue.popleft()
            max_length = max(max_length, length)

            for v, w in graph[u]:
                if (u, v) not in visited and (v, u) not in visited and w != prev_weight:
                    visited.add((u, v))
                    queue.append((v, w, length + 1))

        return max_length

    longest_path = 0
    for node in range(1, n + 1):
        longest_path = max(longest_path, bfs(node))

    return longest_path"]

