["import html.entities

def custom_escape(s: str, quote: bool = True) -> str:
    """
    Escapes certain characters in a string for HTML.
    """
    escape_map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
    }
    if quote:
        escape_map.update({
            '"': '&quot;',
            "'": '&#x27;',
        })

    return ''.join(escape_map.get(c, c) for c in s)

def custom_unescape(s: str) -> str:
    """
    Unescapes HTML character references to their corresponding Unicode characters.
    """
    for entity, char in html.entities.html5.items():
        s = s.replace(f"&{entity};", char)

    # Use a regular expression to find numeric character references and convert them
    import re
    def numeric_ref_replacer(match):
        num_str = match.group()[2:-1]  # removes leading "&#" and trailing ";"
        return chr(int(num_str[1:], 16)) if num_str[0] in 'xX' else chr(int(num_str))

    s = re.sub(r"&#[xX]?[0-9a-fA-F]+;", numeric_ref_replacer, s)

    return s"]

