["def minPalindromicCuts(s):
    n = len(s)

    # Check if a substring is a palindrome
    def is_palindrome(s, start, end):
        while start < end:
            if s[start] != s[end]:
                return False
            start += 1
            end -= 1
        return True

    # DP table to store minimum cuts
    dp = [0] * n

    for i in range(n):
        if is_palindrome(s, 0, i):
            dp[i] = 0
        else:
            min_cuts = float('inf')
            for j in range(i):
                if is_palindrome(s, j + 1, i):
                    min_cuts = min(min_cuts, dp[j] + 1)
            dp[i] = min_cuts

    return dp[-1]"]

