["import numpy as np

class Node:
    def __init__(self, point, axis, left=None, right=None):
        self.point = point
        self.axis = axis
        self.left = left
        self.right = right
        self.bbox = None

    def __str__(self):
        return str(self.point)

def build_kdtree(points, depth=0):
    if len(points) == 0:
        return None
    k = len(points[0])
    axis = depth % k  # Select axis based on depth
    points = sorted(points, key=lambda p: p[axis])
    median_index = len(points) // 2
    node = Node(points[median_index], axis)
    node.left = build_kdtree(points[:median_index], depth + 1)
    node.right = build_kdtree(points[median_index + 1:], depth + 1)
    return node

def bbox_intersect(node, point, dist):
    if node is None:
        return True
    bounding_box = None
    if node.bbox is None:
        node.bbox = np.array([
            [min([p[i] for p in [node.point] + ([c.point for c in [node.left, node.right] if c is not None])]), 
             max([p[i] for p in [node.point] + ([c.point for c in [node.left, node.right] if c is not None])])]
            for i in range(len(node.point))
        ])
        bounding_box = node.bbox
    else:
        bounding_box = node.bbox

    for axis in range(len(point)):
        if bounding_box[axis, 0] > point[axis] + dist or \
           bounding_box[axis, 1] < point[axis] - dist:
            return False
    return True

def nearest_neighbor(node, point, best=None, dist=float('inf'), depth=0):
    if node is None:
        return best, dist

    k = len(point)
    axis = depth % k
    current_dist = np.linalg.norm(np.array(point) - np.array(node.point))

    if current_dist < dist:
        best = node.point
        dist = current_dist

    next_branch = None
    opposite_branch = None

    if point[axis] < node.point[axis]:
        next_branch = node.left
        opposite_branch = node.right
    else:
        next_branch = node.right
        opposite_branch = node.left

    best, dist = nearest_neighbor(next_branch, point, best, dist, depth + 1)

    if bbox_intersect(opposite_branch, point, dist):
        best, dist = nearest_neighbor(opposite_branch, point, best, dist, depth + 1)

    return best, dist

def repeated_nn_query(kd_tree, points_to_query):
    results = []
    for p in points_to_query:
        result, _ = nearest_neighbor(kd_tree, p)
        results.append(result)
    return results"]

