["import re

def read_values_intervals(file_name):
    all_values = []
    interval_pattern = re.compile(r'[\[\(\{](-?\d+(\.\d+)?),\s*(-?\d+(\.\d+)?)[]\)\}]')

    with open(file_name, 'r') as file:
        lines = file.readlines()

        for line in lines:
            line = line.strip()
            if interval_pattern.match(line):
                match = interval_pattern.match(line)
                lower = float(match.group(1))
                upper = float(match.group(3))
                all_values.extend([lower, upper])
            else:
                try:
                    value = float(line)
                    all_values.append(value)
                except ValueError:
                    continue

    return all_values"]

