def can_be_seated_next_to(seating, pref_dict):
    """
    Returns True if in the given seating arrangement no one is seated next to someone they don't want to be seated next to.
    """
    for i in range(len(seating)):
        a = seating[i]
        b = seating[(i + 1) % len(seating)]
        if b in pref_dict.get(a, set()):
            return False
    return True

def arrange_party(n, m, restrictions):
    """
    Returns a valid arrangement of the guests or -1 if it is impossible.
    """
    # Create a dictionary to store the restrictions
    pref_dict = {i: set() for i in range(1, n + 1)}
    for a, b in restrictions:
        pref_dict[a].add(b)
        pref_dict[b].add(a)

    # Check permutations of seating arrangements
    for seating in permutations(range(1, n + 1)):
        if can_be_seated_next_to(seating, pref_dict):
            return seating

    return -1"]

["def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Given a list of integers, return a new list containing only the prime numbers.
    """
    return [num for num in numbers if is_prime(num)]"]

