["def minimizeMaxGroupTime(times, k):
    def is_valid_partition(max_time):
        # Try to partition the array under the assumption that no group's time exceeds max_time
        current_sum = 0
        groups_count = 1

        for time in times:
            if current_sum + time > max_time:
                groups_count += 1
                current_sum = time
                if groups_count > k:
                    return False
            else:
                current_sum += time

        return True

    left, right = max(times), sum(times)

    while left < right:
        mid = left + (right - left) // 2

        if is_valid_partition(mid):
            right = mid
        else:
            left = mid + 1

    return left"]

