    vowels = 'aeiou'
    consonants_first_third = 'bcdfg'
    consonants_second_third = 'hjklm'
    consonants_third_third = 'npqr'
    consonants_fourth_third = 'stvwxyz'

    baskets = {
        'vowels': [],
        'consonants_first_third': [],
        'consonants_second_third': [],
        'consonants_third_third': [],
        'consonants_fourth_third': []
    }

    for letter in ordered_list:
        if letter in vowels:
            baskets['vowels'].append(letter)
        elif letter in consonants_first_third:
            baskets['consonants_first_third'].append(letter)
        elif letter in consonants_second_third:
            baskets['consonants_second_third'].append(letter)
        elif letter in consonants_third_third:
            baskets['consonants_third_third'].append(letter)
        elif letter in consonants_fourth_third:
