["from typing import List, Tuple
from collections import deque

def findShortestPath(grid: List[List[int]]) -> int:
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    m, n = len(grid), len(grid[0])

    if m == 1 and n == 1:
        return 1

    def bfs(allow_obstacle_removal: bool) -> int:
        queue = deque([(0, 0, allow_obstacle_removal, 1)])
        visited = set((0, 0, allow_obstacle_removal))

        while queue:
            x, y, can_remove, d = queue.popleft()

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < m and 0 <= ny < n:
                    if nx == m - 1 and ny == n - 1:
                        return d + 1

                    if (nx, ny, can_remove) not in visited:
                        if grid[nx][ny] == 0:
                            queue.append((nx, ny, can_remove, d + 1))
                            visited.add((nx, ny, can_remove))
                        elif grid[nx][ny] == 1 and can_remove:
                            queue.append((nx, ny, False, d + 1))
                            visited.add((nx, ny, False))

        return -1

    return bfs(True)"]

