["def pacific_atlantic(matrix):
    if not matrix:
        return []

    def dfs(matrix, visited, i, j):
        visited[i][j] = True
        for di, dj in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            ni, nj = i + di, j + dj
            if 0 <= ni < len(matrix) and 0 <= nj < len(matrix[0]) and not visited[ni][nj] and matrix[ni][nj] >= matrix[i][j]:
                dfs(matrix, visited, ni, nj)

    m, n = len(matrix), len(matrix[0])
    p_visited = [[False] * n for _ in range(m)]
    a_visited = [[False] * n for _ in range(m)]

    for i in range(m):
        dfs(matrix, p_visited, i, 0)
        dfs(matrix, a_visited, i, n - 1)

    for j in range(n):
        dfs(matrix, p_visited, 0, j)
        dfs(matrix, a_visited, m - 1, j)

    result = []
    for i in range(m):
        for j in range(n):
            if p_visited[i][j] and a_visited[i][j]:
                result.append([i, j])

    return result"]

