["def num_distinct_paths(grid):
    """
    Returns the number of distinct paths to reach the bottom-right corner from the top-left corner
    in a grid with obstacles.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize a DP table with the same dimensions as grid
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Start point

    # Fill the DP table
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]"]

