["def find_longest_combined_word(n, words):
    word_set = set(words)
    longest_word = ""

    for i in range(n):
        for j in range(n):
            combined_word = words[i] + words[j]
            if combined_word in word_set:
                if len(combined_word) > len(longest_word):
                    longest_word = combined_word
                elif len(combined_word) == len(longest_word) and combined_word < longest_word:
                    longest_word = combined_word

