    def suggest(self, word, max_distance):
        return [w for w in self.dictionary if self.levenshtein_distance(word, w) <= max_distance]

    @staticmethod
    def levenshtein_distance(s1, s2):
        if len(s1) < len(s2):
            return SpellChecker.levenshtein_distance(s2, s1)

        if len(s2) == 0:
            return len(s1)

        previous_row = range(len(s2) + 1)
        for i, c1 in enumerate(s1):
            current_row = [i + 1]
            for j, c2 in enumerate(s2):
                insertions = previous_row[j + 1] + 1
                deletions = current_row[j] + 1
                substitutions = previous_row[j] + (c1 != c2)
                current_row.append(min(insertions, deletions, substitutions))
            previous_row = current_row

        return previous_row[-1]"]

["def can_become_palindrome(s):
    """
    Returns 'YES' if the string s can become a palindrome by removing at most one character, otherwise 'NO'.
    """
    def is_palindrome_range(chars, i, j):
        return all(chars[k] == chars[j - k + i] for k in range(i, j))

    n = len(s)
    l, r = 0, n - 1

    while l < r:
        if s[l] != s[r]:
            if is_palindrome_range(s, l + 1, r) or is_palindrome_range(s, l, r - 1):
                return "YES"
            else:
                return "NO"
        l += 1
        r -= 1

    return "YES"

def process_queries(queries):
    """
    Process a list of string queries and returns a list of results for each query.
    """
    results = []
    for s in queries:
        results.append(can_become_palindrome(s))
    return results"]

