["def shortest_distance(words, word1, word2):
    """
    Returns the shortest distance between two words in the given list of words.

    :param words: List of words (list of strings)
    :param word1: The first word (string)
    :param word2: The second word (string)

    :return: The shortest distance between `word1` and `word2` (integer)
    """
    index1, index2 = -1, -1
    min_distance = float('inf')
    same_word = word1 == word2

    for i, word in enumerate(words):
        if word == word1:
            if same_word:
                if index1 != -1:
                    min_distance = min(min_distance, i - index1)
                index1 = i
            else:
                index1 = i

            if index2 != -1:
                min_distance = min(min_distance, abs(index1 - index2))

        elif word == word2:
            index2 = i

            if index1 != -1:
                min_distance = min(min_distance, abs(index1 - index2))

    return min_distance"]

