["def find_longest_path(graph, start, end):
    def dfs(node, end, path, visited):
        if node == end:
            return path[:]
        visited.add(node)
        longest_path = None
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                current_path = dfs(neighbor, end, path + [neighbor], visited)
                if current_path is not None:
                    if longest_path is None or len(current_path) > len(longest_path):
                        longest_path = current_path
        visited.remove(node)
        return longest_path

    return dfs(start, end, [start], set())"]

["class GraphUndirected:
    def __init__(self):
        # Store the graph as an adjacency list
        self.adj_list = {}

    def add_edge(self, node1, node2):
        if node1 not in self.adj_list:
            self.adj_list[node1] = []
        if node2 not in self.adj_list:
            self.adj_list[node2] = []

        self.adj_list[node1].append(node2)
        self.adj_list[node2].append(node1)

def has_cycle(graph: GraphUndirected):
    visited = set()

    def dfs(v, parent):
        visited.add(v)
        for neighbor in graph.adj_list.get(v, []):
            if neighbor not in visited:
                if dfs(neighbor, v):
                    return True
            elif neighbor != parent:
                return True
        return False

    for node in graph.adj_list:
        if node not in visited:
            if dfs(node, None):
                return True
    return False"]

