["from typing import Tuple, Optional
import random
import sympy

def generate_key(k: int, seed: Optional[int] = None) -> Tuple[int, int, int]:
    if seed is not None:
        random.seed(seed)

    # Ensure k is at least 16 bits
    if k < 16:
        raise ValueError("Key size must be at least 16 bits")

    # Generate two distinct k//2 bit prime numbers p and q
    bit_length = k // 2
    p = sympy.randprime(2**(bit_length-1), 2**bit_length)
    q = sympy.randprime(2**(bit_length-1), 2**bit_length)

    while p == q:
        q = sympy.randprime(2**(bit_length-1), 2**bit_length)

    n = p * q
    phi = (p - 1) * (q - 1)

    # Choose e such that 1 < e < phi and gcd(e, phi) == 1
    e = 65537  # Commonly used prime number for e

    if sympy.gcd(e, phi) != 1:
        e = sympy.nextprime(e)

    # Compute the modular inverse of e modulo phi to get d
    d = pow(e, -1, phi)

    return (n, e, d)

def encrypt(data: int, e: int, n: int) -> int:
    return pow(data, e, n)

def decrypt(data: int, d: int, n: int) -> int:
    return pow(data, d, n)"]

["import heapq
import sys

def dijkstra(adj, src, dest, n):
    dist = [sys.maxsize] * (n + 1)
    dist[src] = 0
    pq = [(0, src)] # (distance, node)

    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > dist[u]: # Check for outdated entry on priority queue
            continue

        for v, weight in adj[u]:
            distance = current_dist + weight

            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    return dist[dest] if dist[dest] != sys.maxsize else -1

def solve_attraction(t, cases):
    results = []
    for case in cases:
        n, m, q, passages, queries = case
        adj = [[] for _ in range(n + 1)]
        for u, v, w in passages:
            adj[u].append((v, w))

        for start, end in queries:
            results.append(dijkstra(adj, start, end, n))
    return results"]

