        self.tasks = []

    def add_task(self, start, end):
        """
        Adds a task to the scheduler.
        """
        if (start, end) not in self.tasks:
            self.tasks.append((start, end))

    def remove_task(self, start, end):
        """
        Removes a task from the scheduler.
        """
        if (start, end) in self.tasks:
            self.tasks.remove((start, end))

    def max_non_overlapping_tasks(self):
        """
        Returns the maximum number of non-overlapping tasks.
        """
        if not self.tasks:
            return 0

        # Sort tasks by their end time
        sorted_tasks = sorted(self.tasks, key=lambda x: x[1])
        count = 0
        last_end_time = float('-inf')

        for task in sorted_tasks:
            if task[0] >= last_end_time:
                count += 1
                last_end_time = task[1]

        return count"]

