        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def starts_with(self, prefix: str) -> List[str]:
        def dfs(node, path, results):
            if node.is_end_of_word:
                results.append(path)
            for char, next_node in node.children.items():
                dfs(next_node, path + char, results)

        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]

        results = []
        dfs(node, prefix, results)
        return results"]

["def evaluate_expression(expression: str) -> int:
    """
    Evaluate the given mathematical expression string and return the resulting integer.
    The division should result in integer division.
    """
    def compute(operators, operands):
        right = operands.pop()
        left = operands.pop()
        operator = operators.pop()

        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(int(left / right))

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    operators = []
    operands = []
    i = 0

    while i < len(expression):
        if expression[i].isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            operands.append(num)
            i -= 1
        elif expression[i] in precedence:
            while (operators and operators[-1] in precedence and
                   precedence[operators[-1]] >= precedence[expression[i]]):
                compute(operators, operands)
            operators.append(expression[i])
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while operators[-1] != '(':
                compute(operators, operands)
            operators.pop()
        i += 1

    while operators:
        compute(operators, operands)

    return operands[0]"]

