["from typing import Sequence, List, Dict, Tuple

def enhanced_knuth_morris_pratt(text: Sequence[str], pattern: Sequence[str]) -> Tuple[List[int], Dict[int, int]]:
    """
    Enhanced Knuth-Morris-Pratt string matching algorithm.

    Args:
        text: Text to search within as a string
        pattern: Pattern to search for as a string

    Returns:
        A tuple (match_indices, match_lengths) where:
        - match_indices: List of starting indices where the pattern matches in the text.
        - match_lengths: A dictionary with keys as the matched lengths and values as the count of occurrences of these lengths.

    Example:
        >>> enhanced_knuth_morris_pratt('hello there hero!', 'he')
        ([0, 7, 12], {2: 3})

        >>> enhanced_knuth_morris_pratt('aabbaabbaabb', 'aa')
        ([0, 4, 8], {2: 3})
    """
    if not text or not pattern:
        return [], {}

    def build_lps(pattern: Sequence[str]) -> List[int]:
        """Build the longest prefix-suffix (LPS) array."""
        lps = [0] * len(pattern)
        length = 0
        i = 1
        while i < len(pattern):
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    lps = build_lps(pattern)

    match_indices = []
    match_lengths = {}
    i = 0  # index for text
    j = 0  # index for pattern
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1

        if j == len(pattern):
            match_indices.append(i - j)
            match_length = len(pattern)
            if match_length in match_lengths:
                match_lengths[match_length] += 1
            else:
                match_lengths[match_length] = 1
            j = lps[j - 1]
        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return match_indices, match_lengths"]

