    def __init__(self, s):
        self.s = list(s)

    def distinct_letters_in_substring(self, l, r):
        return len(set(self.s[l-1:r]))

    def replace_character(self, p, c):
        self.s[p-1] = c

    def process_queries(self, queries):
        results = []
        for query in queries:
            parts = query.split()
            if parts[0] == "1":
                l, r = int(parts[1]), int(parts[2])
                results.append(self.distinct_letters_in_substring(l, r))
            elif parts[0] == "2":
                p, c = int(parts[1]), parts[2]
                self.replace_character(p, c)
        return results

def solve(s, queries):
    solution = Solution(s)
    results = solution.process_queries(queries)
    return results"]

