["def findIndices(arr, target):
    """
    Returns a tuple with the leftmost and rightmost indices of the target element in the sorted array.
    If the target element is not found, returns (-1, -1).
    """
    def findLeftmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left if left < len(arr) and arr[left] == target else -1

    def findRightmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] > target:
                right = mid - 1
            else:
                left = mid + 1
        return right if right >= 0 and arr[right] == target else -1

    left_index = findLeftmost()
    right_index = findRightmost()
    return (left_index, right_index)"]

