["def count_paths(n, m, grid):
    MOD = 10**9 + 7

    dp = [[0] * m for _ in range(n)]
    if grid[0][0] == '#':
        return -1
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[n-1][m-1] if dp[n-1][m-1] > 0 else -1"]

["class TreeNode:
    def __init__(self, key):
        self.val = key
        self.left = None
        self.right = None

def deleteNode(root, key):
    if not root:
        return root

    if key < root.val:
        root.left = deleteNode(root.left, key)
    elif key > root.val:
        root.right = deleteNode(root.right, key)
    else:
        if not root.left:
            return root.right
        elif not root.right:
            return root.left

        temp = minValueNode(root.right)
        root.val = temp.val
        root.right = deleteNode(root.right, temp.val)

    return root

def minValueNode(node):
    current = node
    while current.left:
        current = current.left
    return current

def inorderTraversal(root):
    result = []
    if root:
        result = inorderTraversal(root.left)
        result.append(root.val)
        result = result + inorderTraversal(root.right)
    return result"]

