class CustomSortedList:
    def __init__(self, key_function=None):
        self.key_function = key_function
        self._list = []

    def insert(self, value):
        key = self.key_function(value) if self.key_function else value
        bisect.insort(self._list, (key, value))

    def find_le(self, value):
        key = self.key_function(value) if self.key_function else value
        idx = bisect.bisect_right(self._list, (key, value)) - 1
        if idx >= 0:
            return self._list[idx][1]
        return None

    def find_ge(self, value):
        key = self.key_function(value) if self.key_function else value
        idx = bisect.bisect_left(self._list, (key, value))
        if idx < len(self._list):
            return self._list[idx][1]
        return None"]

