["def numIslands(grid):
    if not grid:
        return 0

    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return
        grid[i][j] = '0'
        dfs(grid, i + 1, j)
        dfs(grid, i - 1, j)
        dfs(grid, i, j + 1)
        dfs(grid, i, j - 1)

    num_islands = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                num_islands += 1
                dfs(grid, i, j)

    return num_islands"]

["from typing import List

def search_insert(array, val):
    low = 0
    high = len(array) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if val > array[mid]:
            low = mid + 1
        else:
            high = mid - 1
    return low

def insertion_sort(array: List[int]) -> List[int]:
    for i in range(1, len(array)):
        key = array[i]
        # Find the index where key should be inserted in the sorted sublist array[0:i]
        insert_index = search_insert(array[:i], key)
        # Insert key at the found index and shift the rest
        array = array[:insert_index] + [key] + array[insert_index:i] + array[i+1:]
    return array"]

