["class ToDoItem:
    def __init__(self, title, description, due_date=None):
        self.title = title
        self.description = description
        self.due_date = due_date
        self.completed = False

class ToDoManager:
    def __init__(self):
        self.items = {}

    def add(self, title, description, due_date=None):
        item = ToDoItem(title, description, due_date)
        self.items[title] = item

    def complete(self, title):
        if title in self.items:
            self.items[title].completed = True

    def list_items(self, option="all"):
        filtered_items = self.items.values()
        if option == "completed":
            filtered_items = filter(lambda item: item.completed, self.items.values())
        elif option == "uncompleted":
            filtered_items = filter(lambda item: not item.completed, self.items.values())

        result = []
        for item in filtered_items:
            due_date = item.due_date if item.due_date else "No due date"
            status = "Completed" if item.completed else "Uncompleted"
            result.append(f"Title: {item.title}, Description: {item.description}, Due Date: {due_date}, Status: {status}")
        return result

def process_input(commands):
    manager = ToDoManager()
    result = []

    for command in commands:
        parts = command.split(" ", 1)
        cmd = parts[0]
        if cmd == "EXIT":
            break
        elif cmd == "ADD":
            parts = command.split('"')
            title = parts[1]
            description = parts[3]
            due_date = parts[4].strip() if len(parts) > 4 else None
            manager.add(title, description, due_date)
        elif cmd == "COMPLETE":
            title = command.split('"')[1]
            manager.complete(title)
        elif cmd == "LIST":
            option = command.split(" ")[1] if len(command.split(" ")) > 1 else "all"
            result.append("\n".join(manager.list_items(option)))

    if result:
        print("\n".join(result))

