from decimal import Decimal

def rational_operations(operations: list) -> float:
    """
    Performs a series of operations using the fractions.Fraction class.

    Args:
    operations (list): A list of tuples indicating operations and their arguments.

    Returns:
    float: Result of the operations as a float or tuple if 'as_ratio' is the final operation.
    """
    result = None

    for operation in operations:
        op = operation[0]

        if op == "add":
            if result is None:
                result = operation[1]
            else:
                result += operation[1]

        elif op == "subtract":
            if result is None:
                result = operation[1]
            else:
                result -= operation[1]

        elif op == "multiply":
            if result is None:
                result = operation[1]
            else:
                result *= operation[1]

        elif op == "divide":
            if result is None:
                result = operation[1]
            else:
                result /= operation[1]

        elif op == "limit_denominator":
            max_denominator = operation[1] if len(operation) > 1 else 1000000
            result = result.limit_denominator(max_denominator)

        elif op == "as_ratio":
            return result.numerator, result.denominator

        elif op == "from_float":
            result = Fraction.from_float(operation[1])

        elif op == "from_decimal":
            result = Fraction(operation[1])

    return float(result)"]

["def longest_unique_word(sequence):
    """
    Finds the longest unique word in a sequence of words.
    """
    words = sequence.split()
    word_count = {}

    # Count the frequency of each word
    for word in words:
        word_count[word] = word_count.get(word, 0) + 1

    # Find the longest unique word
    longest_word = ""
    for word in words:
        if word_count[word] == 1:
            if len(word) > len(longest_word):
                longest_word = word

    return longest_word"]

