["def validate_expression(expression: str) -> bool:
    """
    Validates if the given expression containing digits, basic arithmetic operators, and parentheses is valid.
    Returns True if the expression is valid, and False otherwise.
    """
    stack = []
    valid_chars = set('0123456789+-*/()')
    operators = set('+-*/')
    last_char = None

    for char in expression:
        if char not in valid_chars:
            return False

        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

        if char in operators:
            if last_char in operators or last_char is None:
                return False

        last_char = char

    if stack:
        return False
    if last_char in operators:
        return False

    return True"]

["# TreeNode class definition
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(level_order):
    """
    Helper function to build a tree from level order input.
    """
    if not level_order:
        return None

    from collections import deque
    it = iter(level_order)
    root = TreeNode(next(it))
    queue = deque([root])

    while True:
        try:
            node = queue.popleft()
            left_val = next(it)
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
            right_val = next(it)
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
        except StopIteration:
            break

    return root

def is_valid_bst(root):
    """
    Function to determine if a binary tree is a valid BST
    """
    def validate(node, low=float('-inf'), high=float('inf')):
        if not node:
            return True
        if node.val <= low or node.val >= high:
            return False
        return (validate(node.left, low, node.val) and validate(node.right, node.val, high))

    return validate(root)"]

