["import heapq
from collections import defaultdict

def max_spell_strength(n, m, t, bridges, wizard_islands):
    def dijkstra(source):
        distances = {i: float('inf') for i in range(1, n + 1)}
        distances[source] = 0
        pq = [(0, source)]

        while pq:
            current_distance, current_island = heapq.heappop(pq)

            if current_distance > distances[current_island]:
                continue

            for neighbor, weight in graph[current_island]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))

        return distances

    graph = defaultdict(list)

    for a, b, s in bridges:
        graph[a].append((b, s))
        graph[b].append((a, s))

    max_strength = -1

    for wi in wizard_islands:
        distances = dijkstra(wi)
        for other_wi in wizard_islands:
            if other_wi != wi and distances[other_wi] < float('inf'):
                max_strength = max(max_strength, 2 * min(graph[wi][0][1] for nei, _ in graph[wi]))

    return max_strength

