["def tree_print(tree, indent=0):
    """
    Prints the hierarchical structure of a dictionary representing a tree.

    :param tree: dict, hierarchical structure of categories and subcategories
    :param indent: int, current indentation level
    """
    for key, value in tree.items():
        print(' ' * indent + str(key))
        if isinstance(value, dict):
            tree_print(value, indent + 2)
        else:
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, dict):
