["def maximalRectangle(matrix):
    if not matrix or not matrix[0]:
        return 0

    max_area = 0
    n = len(matrix)
    m = len(matrix[0])
    heights = [0] * (m + 1)

    for row in matrix:
        for i in range(m):
            if row[i] == '.':
                heights[i] += 1
            else:
                heights[i] = 0

        stack = [-1]
        for j in range(m + 1):
            while heights[j] < heights[stack[-1]]:
                h = heights[stack.pop()]
                w = j - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(j)

    return max_area

def largest_empty_rectangle(garden):
    return maximalRectangle(garden)

# Example usage:
