["from collections import defaultdict, deque

def find_min_distance(n, paths):
    # Create a graph adjacency list
    graph = defaultdict(list)
    for u, v, d in paths:
        graph[u].append((v, d))

    # Kahn's algorithm for topological sorting
    in_degree = [0] * n
    for u in graph:
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = deque([i for i in range(n) if in_degree[i] == 0])
    topo_order = []

    while queue:
        node = queue.popleft()
        topo_order.append(node)
        for neighbor, _ in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Initialize distances with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0  # distance to the start node is 0

    # Relax edges in topological order
    for u in topo_order:
        for v, d in graph[u]:
            if dist[u] != INF and dist[u] + d < dist[v]:
                dist[v] = dist[u] + d

    # The distance to the last node
    return dist[n-1]


# Wrapper function to parse the given input
def minimal_marathon_distance(n, path_info):
    return find_min_distance(n, path_info)"]

