["def max_subarray_sum_no_zero(n, arr):
    """
    Returns the maximum possible sum of a subarray that does not include zero.
    """
    max_sum = -float('inf')
    current_sum = 0

    for num in arr:
        if num == 0:
            current_sum = 0
        else:
            current_sum += num
            if current_sum > max_sum:
                max_sum = current_sum
            if current_sum < 0:
                current_sum = 0

    return max_sum"]

