["class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_deepest_node(root: TreeNode) -> int:
    if not root:
        return None

    queue = [(root, 0)]  # (node, depth)
    deepest_node = root
    max_depth = 0

    while queue:
        node, depth = queue.pop(0)

        if depth > max_depth:
            max_depth = depth
            deepest_node = node

        if node.left:
            queue.append((node.left, depth + 1))
        if node.right:
            queue.append((node.right, depth + 1))

    return deepest_node.val"]

