["from typing import List
import fnmatch

def filter_files(filenames: List[str], commands: List[str]) -> List[str]:
    included_files = set()

    for command in commands:
        parts = command.split()
        action = parts[0]
        pattern = parts[1] if len(parts) > 1 else ""

        if action == "include":
            included_files.update(fnmatch.filter(filenames, pattern))

        elif action == "exclude":
            for file in fnmatch.filter(filenames, pattern):
                included_files.discard(file)

        elif action == "recursive-include":
            directory = parts[1]
            pattern = parts[2]
            for file in filenames:
                if file.startswith(directory) and fnmatch.fnmatch(file[len(directory)+1:], pattern):
                    included_files.add(file)

        elif action == "recursive-exclude":
            directory = parts[1]
            pattern = parts[2]
            for file in filenames:
                if file.startswith(directory) and fnmatch.fnmatch(file[len(directory)+1:], pattern):
                    included_files.discard(file)

        elif action == "global-include":
            included_files.update(fnmatch.filter(filenames, pattern))

        elif action == "global-exclude":
            for file in fnmatch.filter(filenames, pattern):
                included_files.discard(file)

        elif action == "prune":
            directory = pattern
            for file in filenames:
                if file.startswith(directory):
                    included_files.discard(file)

        elif action == "graft":
            directory = pattern
            for file in filenames:
                if file.startswith(directory):
                    included_files.add(file)

    return sorted(included_files)"]

