["def min_palindromic_cuts(s):
    """
    Returns the minimum number of cuts needed to partition the string s into palindromic substrings.
    """
    n = len(s)
    if n == 0:
        return 0

    dp = [0] * n
    pal = [[False] * n for _ in range(n)]

    for i in range(n):
        min_cut = i
        for j in range(i + 1):
            if s[i] == s[j] and (i - j < 2 or pal[j + 1][i - 1]):
                pal[j][i] = True
                if j == 0:
                    min_cut = 0
                else:
                    min_cut = min(min_cut, dp[j - 1] + 1)
        dp[i] = min_cut

    return dp[n - 1]

def process_cases(T, cases):
    results = []
    for case in cases:
        results.append(min_palindromic_cuts(case))
    return results"]

