["def is_one_edit_away(word1, word2):
    """
    Check if word1 and word2 are one edit away.
    """
    len1, len2 = len(word1), len(word2)
    if abs(len1 - len2) > 1:
        return False

    i = j = alterations = 0
    while i < len1 and j < len2:
        if word1[i] != word2[j]:
            if alterations == 1:
                return False
            alterations += 1
            if len1 > len2:
                i += 1
            elif len1 < len2:
                j += 1
            else:
                i += 1
                j += 1
        else:
            i += 1
            j += 1

    if i < len1 or j < len2:
        alterations += 1

    return alterations == 1

def find_one_edit_words(word, dictionary):
    """
    Finds all words in a given dictionary that are one edit away from the word.
    """
    return [dict_word for dict_word in dictionary if is_one_edit_away(word, dict_word)]"]

