["def longest_ski_path(grid):
    if not grid:
        return 0

    M, N = len(grid), len(grid[0])
    dp = [[-1 for _ in range(N)] for _ in range(M)]

    def dfs(r, c):
        if dp[r][c] != -1:
            return dp[r][c]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        max_length = 1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < M and 0 <= nc < N and grid[nr][nc] < grid[r][c]:
                max_length = max(max_length, 1 + dfs(nr, nc))

        dp[r][c] = max_length
        return dp[r][c]

    longest_path = 0
    for i in range(M):
        for j in range(N):
            longest_path = max(longest_path, dfs(i, j))

    return longest_path"]

