["import heapq

def dijkstra(graph, start, n):
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]  # (distance, node)

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    return dist

def find_capital_planet(n, m, tunnels):
    graph = [[] for _ in range(n)]
    for u, v, w in tunnels:
        graph[u - 1].append((v - 1, w))
        graph[v - 1].append((u - 1, w))

    min_max_distance = float('inf')
    for i in range(n):
        dist = dijkstra(graph, i, n)
        max_dist = max(dist)
        if max_dist < min_max_distance:
            min_max_distance = max_dist

    return min_max_distance"]

["import heapq
from collections import defaultdict
from sys import maxsize as inf

def max_interest_trip(n, m, interest_values, roads, trips):
    # Build the graph
    graph = defaultdict(list)
    for a, b, d in roads:
        graph[a].append((b, d))
        graph[b].append((a, d))

    # Function to get the shortest path and maximum interest value along the path
    def find_max_interest(start, end):
        pq = [(0, start)]
        distances = {i: inf for i in range(1, n+1)}
        max_interest = {i: 0 for i in range(1, n+1)}
        distances[start] = 0
        max_interest[start] = interest_values[start-1]

        while pq:
            current_dist, u = heapq.heappop(pq)
            if u == end:
                return max_interest[u]

            for v, weight in graph[u]:
                if distances[v] > current_dist + weight:
                    distances[v] = current_dist + weight
                    max_interest[v] = max(max_interest[u], interest_values[v-1])
                    heapq.heappush(pq, (distances[v], v))

                elif distances[v] == current_dist + weight:
                    if max_interest[v] < max(max_interest[u], interest_values[v-1]):
                        max_interest[v] = max(max_interest[u], interest_values[v-1])

        return max_interest[end]

    result = []
    for start, end in trips:
        result.append(find_max_interest(start, end))

    return result

# Example usage:
n, m = 5, 3
interest_values = [5, 3, 6, 8, 7]
roads = [(1, 2, 4), (2, 3, 1), (3, 4, 2), (4, 5, 3)]
trips = [(1, 5), (2, 4), (3, 5)]

print(max_interest_trip(n, m, interest_values, roads, trips)) # [8, 8, 8]"]

["from itertools import combinations

def can_fulfill_requirements(matrix, requirements, selected_stores):
    item_count = [0] * len(requirements)

    for store in selected_stores:
        for j in range(len(requirements)):
            item_count[j] += matrix[store][j]

    for i in range(len(requirements)):
        if item_count[i] < requirements[i]:
            return False
    return True

def min_stores(matrix, requirements):
    n = len(matrix)
    min_store_count = float('inf')

    for r in range(1, n + 1):
        for selected_stores in combinations(range(n), r):
            if can_fulfill_requirements(matrix, requirements, selected_stores):
                min_store_count = min(min_store_count, r)
                break

    return min_store_count if min_store_count != float('inf') else -1"]

["def find_pairs(n, arr):
    sum_pairs = {}

    for i in range(n):
        for j in range(i + 1, n):
            pair_sum = arr[i] + arr[j]

            # If we've already seen this sum
            if pair_sum in sum_pairs:
                (a, b) = sum_pairs[pair_sum]
                # Ensure the pairs are disjoint
                if a != arr[i] and a != arr[j] and b != arr[i] and b != arr[j]:
                    return [a, b, arr[i], arr[j]]
            else:
                sum_pairs[pair_sum] = (arr[i], arr[j])

    return []

