["class UnionFind:
    def __init__(self, size):
        self.root = list(range(size))
        self.rank = [1] * size

    def find(self, u):
        if u != self.root[u]:
            self.root[u] = self.find(self.root[u])
        return self.root[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.root[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.root[root_u] = root_v
            else:
                self.root[root_v] = root_u
                self.rank[root_u] += 1

def minimum_travel_cost(T, test_cases):
    results = []
    for case in test_cases:
        N, M, edges = case
        uf = UnionFind(N)
        edges.sort(key=lambda x: x[2])
        mst_cost = 0
        edges_used = 0

        for u, v, w in edges:
            if uf.find(u - 1) != uf.find(v - 1):
                uf.union(u - 1, v - 1)
                mst_cost += w
                edges_used += 1
                if edges_used == N - 1:
                    break

        if edges_used != N - 1:
            results.append("impossible")
        else:
            results.append(str(mst_cost))
    return results

def process_input(input_string):
    data = input_string.strip().split('\n')
    T = int(data[0])
    idx = 1
    test_cases = []
    for _ in range(T):
        N, M = map(int, data[idx].split())
        edges = [tuple(map(int, data[idx + i + 1].split())) for i in range(M)]
        test_cases.append((N, M, edges))
        idx += M + 1
    return T, test_cases

def process_output(results):
    return '\n'.join(results)

def main(input_string):
    T, test_cases = process_input(input_string)
    results = minimum_travel_cost(T, test_cases)
    return process_output(results)"]

