["import sys

def factorial(n):
    """
    Returns the factorial of a given number n.

    :param n: integer, the number to calculate the factorial for.
    :return: integer, factorial of n.
    :raises ValueError: if n is negative or not an integer.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    sys.setrecursionlimit(1000)  # Ensures large input like 100! doesn't cause stack overflow

    def recurse(num):
        if num == 0 or num == 1:
            return 1
        return num * recurse(num - 1)

    return recurse(n)"]

["def is_valid_palindrome(s):
    """
    This function checks if a given string can be a palindrome
    by removing at most one character.
    """
    def is_palindrome_range(s, left, right):
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return is_palindrome_range(s, left + 1, right) or is_palindrome_range(s, left, right - 1)
        left += 1
        right -= 1

    return True

def check_palindromes(test_cases):
    """
    This function takes a list of strings and returns a list of "YES" or "NO" 
    depending on whether the string can be a palindrome by removing at most one character.
    """
    results = []
    for s in test_cases:
        if is_valid_palindrome(s):
            results.append("YES")
        else:
            results.append("NO")
    return results"]

["def encode_string(S, K):
    """
    Encode the given string S by shifting each letter by K positions in the alphabet.
    """
    encoded_chars = []
    for char in S:
        if 'a' <= char <= 'z':
            new_char = chr(((ord(char) - ord('a') + K) % 26) + ord('a'))
        elif 'A' <= char <= 'Z':
            new_char = chr(((ord(char) - ord('A') + K) % 26) + ord('A'))
        else:
            new_char = char  # Non-alphabetic characters remain unchanged
        encoded_chars.append(new_char)

    return ''.join(encoded_chars)

def process_cases(test_cases):
    results = []
    for s, k in test_cases:
        results.append(encode_string(s, k))
    return results"]

