["def longest_increasing_path(n, m, grid):
    def dfs(x, y):
        if dp[x][y]:
            return dp[x][y]
        max_len = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and ord(grid[nx][ny]) == ord(grid[x][y]) + 1:
                max_len = max(max_len, 1 + dfs(nx, ny))
        dp[x][y] = max_len
        return max_len

    if not grid or not grid[0]:
        return 0

    dp = [[0] * m for _ in range(n)]
    max_path_len = 0

    for i in range(n):
        for j in range(m):
            max_path_len = max(max_path_len, dfs(i, j))

    return max_path_len"]

["from collections import deque

class TreeNode:
    def __init__(self, val: int = 0, left: 'TreeNode' = None, right: 'TreeNode' = None):
        self.val = val
        self.left = left
        self.right = right

def deepest_leaves_sum(root: TreeNode) -> int:
    if not root:
        return 0

    queue = deque([root])
    while queue:
        level_sum = 0
        level_length = len(queue)
        for _ in range(level_length):
            node = queue.popleft()
            level_sum += node.val  # Sum the values at the current level
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

    return level_sum  # level_sum will be the sum of the deepest leaves after the last iteration"]

