["from typing import List

def ternary_search(arr: List[int], target: int) -> int:
    """
    Perform a ternary search to find the index of `target` in `arr`.

    Returns the index of the `target` if found, otherwise returns -1.
    """
    def search(low, high):
        if low > high:
            return -1

        third = (high - low) // 3
        mid1 = low + third
        mid2 = high - third

        if arr[mid1] == target:
            return mid1
        if arr[mid2] == target:
            return mid2

        if target < arr[mid1]:
            return search(low, mid1 - 1)
        elif target > arr[mid2]:
            return search(mid2 + 1, high)
        else:
            return search(mid1 + 1, mid2 - 1)

    return search(0, len(arr) - 1)"]

