["from typing import List, Dict

def find_task_order(graph: Dict[int, List[int]]) -> List[int]:
    """
    Perform topological sorting on a given directed acyclic graph (DAG)
    represented as an adjacency list.
    """
    visited = set()
    temp = set()
    result = []

    def visit(node: int):
        if node in temp:
            raise ValueError("cycle")
        if node not in visited:
            temp.add(node)
            for neighbor in graph.get(node, []):
                visit(neighbor)
            temp.remove(node)
            visited.add(node)
            result.append(node)

    for node in graph:
        if node not in visited:
            visit(node)

    return result[::-1]"]

