["from collections import defaultdict, deque

class FreqStack:
    def __init__(self):
        self.freq = defaultdict(int)
        self.group = defaultdict(deque)
        self.maxfreq = 0

    def push(self, val: int) -> None:
        f = self.freq[val] + 1
        self.freq[val] = f
        if f > self.maxfreq:
            self.maxfreq = f
        self.group[f].append(val)

    def pop(self) -> int:
        val = self.group[self.maxfreq].pop()
        self.freq[val] -= 1
        if not self.group[self.maxfreq]:
            self.maxfreq -= 1
        return val"]

["def can_be_strictly_increasing_by_one_swap(n, arr):
    # Check if the array is already strictly increasing
    if arr == sorted(arr) and len(arr) == len(set(arr)):
        return "YES"

    for i in range(n - 1):
        for j in range(i + 1, n):
            # swap arr[i] and arr[j]
            arr[i], arr[j] = arr[j], arr[i]
            if arr == sorted(arr) and len(arr) == len(set(arr)):
                return "YES"
            # undo the swap
            arr[i], arr[j] = arr[j], arr[i]

    return "NO"

def process_test_cases(t, test_cases):
    results = []
    for i in range(t):
        n, arr = test_cases[i]
        results.append(can_be_strictly_increasing_by_one_swap(n, arr))
    return results"]

