["import operator
import re

def evaluate_expression(expression):
    def parse_expression(expression):
        tokens = re.findall(r'\d+\.?\d*|[\+\-\*/\(\)]', expression)
        return shunting_yard(tokens)

    def shunting_yard(tokens):
        out_queue = []
        op_stack = []
        ops = {'+': (1, operator.add), '-': (1, operator.sub), '*': (2, operator.mul), '/': (2, operator.truediv)}

        for token in tokens:
            if re.match(r'\d', token):
                out_queue.append(float(token))  # Convert numbers to float for eval
            elif token in ops:
                while (op_stack and op_stack[-1] in ops and
                       ops[token][0] <= ops[op_stack[-1]][0]):
                    out_queue.append(op_stack.pop())
                op_stack.append(token)
            elif token == '(':
                op_stack.append(token)
            elif token == ')':
                while op_stack and op_stack[-1] != '(':
                    out_queue.append(op_stack.pop())
                op_stack.pop()  # Pop the '('

        while op_stack:
            out_queue.append(op_stack.pop())

        return out_queue

    def evaluate_rpn(rpn_expression):
        stack = []
        ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}

        for token in rpn_expression:
            if isinstance(token, float):
                stack.append(token)
            elif token in ops:
                b, a = stack.pop(), stack.pop()
                if token == '/' and b == 0:
                    raise ZeroDivisionError('Division by zero')
                stack.append(ops[token](a, b))

        return stack[0]

