["import xdrlib

class XDRSerializer:

    def serialize(self, data: dict) -> bytes:
        packer = xdrlib.Packer()

        if not isinstance(data, dict):
            raise ValueError("Input data must be a dictionary.")

        # Serialize the dictionary
        packer.pack_int(len(data))  # first, pack the number of items

        for key, value in data.items():
            if not isinstance(key, str):
                raise ValueError("Dictionary keys must be strings.")

            # Pack the key
            packer.pack_string(key.encode('utf-8'))

            # Pack the value
            if isinstance(value, int):
                packer.pack_int(1)  # type identifier for int
                packer.pack_int(value)
            elif isinstance(value, float):
                packer.pack_int(2)  # type identifier for float
                packer.pack_double(value)
            elif isinstance(value, str):
                packer.pack_int(3)  # type identifier for string
                packer.pack_string(value.encode('utf-8'))
            elif isinstance(value, list) and all(isinstance(i, int) for i in value):
                packer.pack_int(4)  # type identifier for list of ints
                packer.pack_int(len(value))
                for item in value:
                    packer.pack_int(item)
            else:
                raise ValueError(f"Unsupported data type: {type(value)}")

        return packer.get_buffer()

    def deserialize(self, xdr_data: bytes) -> dict:
        unpacker = xdrlib.Unpacker(xdr_data)

        # Deserialize the dictionary
        num_items = unpacker.unpack_int()
        result = {}

        for _ in range(num_items):
            key = unpacker.unpack_string().decode('utf-8')
            value_type = unpacker.unpack_int()

            if value_type == 1:
                value = unpacker.unpack_int()
            elif value_type == 2:
                value = unpacker.unpack_double()
            elif value_type == 3:
                value = unpacker.unpack_string().decode('utf-8')
            elif value_type == 4:
                list_length = unpacker.unpack_int()
                value = [unpacker.unpack_int() for _ in range(list_length)]
            else:
                raise ValueError(f"Unsupported data type identifier: {value_type}")

            result[key] = value

        return result"]

