["import threading
import time
import random

class BoundedBuffer:
    def __init__(self, size):
        self.size = size
        self.buffer = []
        self.lock = threading.Condition()

    def put(self, item):
        with self.lock:
            while len(self.buffer) >= self.size:
                self.lock.wait()
            self.buffer.append(item)
            self.lock.notify_all()

    def get(self):
        with self.lock:
            while not self.buffer:
                self.lock.wait()
            item = self.buffer.pop(0)
            self.lock.notify_all()
            return item

class Producer(threading.Thread):
    def __init__(self, buffer, num_items):
        threading.Thread.__init__(self)
        self.buffer = buffer
        self.num_items = num_items

    def run(self):
        for _ in range(self.num_items):
            item = random.randint(0, 100)
            self.buffer.put(item)
            print(f'Produced {item}')
            time.sleep(random.uniform(0.1, 0.5))

class Consumer(threading.Thread):
    def __init__(self, buffer, num_items):
        threading.Thread.__init__(self)
        self.buffer = buffer
        self.num_items = num_items

    def run(self):
        for _ in range(self.num_items):
            item = self.buffer.get()
            print(f'Consumed {item}')
            time.sleep(random.uniform(0.1, 0.5))

if __name__ == "__main__":
    buffer_size = 5
    num_producers = 3
    num_consumers = 3
    total_items = 30

    buffer = BoundedBuffer(buffer_size)
    producers = [Producer(buffer, total_items // num_producers) for _ in range(num_producers)]
    consumers = [Consumer(buffer, total_items // num_consumers) for _ in range(num_consumers)]

    for p in producers:
        p.start()
    for c in consumers:
        c.start()

    for p in producers:
        p.join()
    for c in consumers:
        c.join()

    print("All items have been produced and consumed.")"]

["class CustomMinHeap:
    def __init__(self):
        self.heap = []

    def insert(self, element: int) -> None:
        self.heap.append(element)
        self._heapify_up(len(self.heap) - 1)

    def extract_min(self) -> int:
        if not self.heap:
            raise IndexError("Heap is empty")
        if len(self.heap) == 1:
            return self.heap.pop()
        min_element = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._heapify_down(0)
        return min_element

    def get_min(self) -> int:
        if not self.heap:
            raise IndexError("Heap is empty")
        return self.heap[0]

    def decrease_key(self, index: int, new_value: int) -> None:
        if index < 0 or index >= len(self.heap):
            raise IndexError("Index out of bound")
        if new_value > self.heap[index]:
            raise ValueError("New value is greater than the current value")
        self.heap[index] = new_value
        self._heapify_up(index)

    def _heapify_up(self, index):
        parent_index = (index - 1) // 2
        if parent_index >= 0 and self.heap[parent_index] > self.heap[index]:
            self.heap[parent_index], self.heap[index] = self.heap[index], self.heap[parent_index]
            self._heapify_up(parent_index)

    def _heapify_down(self, index):
        smallest = index
        left_child = 2 * index + 1
        right_child = 2 * index + 2
        if left_child < len(self.heap) and self.heap[left_child] < self.heap[smallest]:
            smallest = left_child
        if right_child < len(self.heap) and self.heap[right_child] < self.heap[smallest]:
            smallest = right_child
        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self._heapify_down(smallest)"]

