    def __init__(self):
        self.adj_list = {}

    def add_vertex(self, vertex):
        if vertex not in self.adj_list:
            self.adj_list[vertex] = []

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.adj_list and vertex2 in self.adj_list:
            self.adj_list[vertex1].append(vertex2)
            self.adj_list[vertex2].append(vertex1)

    def are_connected(self, vertex1, vertex2):
        if vertex1 not in self.adj_list or vertex2 not in self.adj_list:
            return False

        visited = set()
        stack = [vertex1]

        while stack:
            current = stack.pop()
            if current == vertex2:
                return True
            if current not in visited:
                visited.add(current)
                stack.extend([neighbor for neighbor in self.adj_list[current] if neighbor not in visited])

        return False"]

["class FileSystem:
    def __init__(self):
        self.root = {}

    def mkdir(self, path: str) -> None:
        dirs = path.strip('/').split('/')
        current = self.root

        for dir in dirs:
            if dir not in current:
                current[dir] = {}
            current = current[dir]

    def addFile(self, path: str, content: str) -> None:
        dirs = path.strip('/').split('/')
        file_name = dirs.pop()
        current = self.root

        for dir in dirs:
            if dir not in current:
                current[dir] = {}
            current = current[dir]

        if file_name not in current:
            current[file_name] = ""

        current[file_name] += content

    def ls(self, path: str) -> list:
        if path == "/":
            return sorted(self.root.keys())

        dirs = path.strip('/').split('/')
        current = self.root

        for dir in dirs:
            current = current[dir]

        if isinstance(current, str):
            return [dirs[-1]]

        return sorted(current.keys())

    def readFile(self, path: str) -> str:
        dirs = path.strip('/').split('/')
        file_name = dirs.pop()
        current = self.root

        for dir in dirs:
            current = current[dir]

        return current[file_name]"]

