        self.left = left
        self.right = right

def kd_tree_nearest(points: list[tuple[int, int]], target: tuple[int, int]) -> tuple[int, int]:
    """
    Find the nearest neighbor to the target point using KD-Tree.
    """
    if not points:
        return None

    def build_kd_tree(points, depth=0):
        if not points:
            return None

        k = len(points[0])  # assumes all points have the same dimension
        axis = depth % k

        points.sort(key=lambda x: x[axis])
        median = len(points) // 2

        return KDTreeNode(
            point=points[median],
            left=build_kd_tree(points[:median], depth + 1),
            right=build_kd_tree(points[median + 1:], depth + 1)
        )

    def kd_tree_nearest_rec(node, target, depth=0, best_node=None, best_dist=float('inf')):
        if node is None:
            return best_node, best_dist

        k = len(target)
        axis = depth % k
        point = node.point

        d = math.dist(point, target)
        if d < best_dist:
            best_dist = d
            best_node = point

        diff = target[axis] - point[axis]

        if diff <= 0:
            best_node, best_dist = kd_tree_nearest_rec(node.left, target, depth + 1, best_node, best_dist)
            if abs(diff) < best_dist:
