                best_node, best_dist = kd_tree_nearest_rec(node.left, target, depth + 1, best_node, best_dist)

        return best_node, best_dist

    kd_tree_root = build_kd_tree(points)
    nearest_point, _ = kd_tree_nearest_rec(kd_tree_root, target)

    return nearest_point

