["from collections import defaultdict, deque

def is_bipartite(graph, f):
    color = [-1] * (f + 1)  # Color -1 indicates unvisited nodes

    for i in range(1, f + 1):
        if color[i] == -1:  # Not yet visited node
            queue = deque([i])
            color[i] = 0  # Start coloring this component with color 0

            while queue:
                u = queue.popleft()

                for v in graph[u]:
                    if color[v] == -1:
                        # Color with opposite color of current node
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        # Found same color neighbor in a supposed bipartite graph
                        return False, []

    return True, color

def assign_teams(t, f, dependencies):
    graph = defaultdict(list)

    for a, b in dependencies:
        graph[a].append(b)
        graph[b].append(a)

    possible, color = is_bipartite(graph, f)
    if possible:
        assignment = [color[i] + 1 for i in range(1, f + 1)]
        return "YES", assignment
    else:
        return "NO", []

# Example Usage (wrapped in a function for demonstration)
def map_functionalities_to_teams(test_cases):
    results = []
    for t, f, dependencies in test_cases:
        result, assignment = assign_teams(t, f, dependencies)
        if result == "YES":
            results.append(f"YES\n{' '.join(map(str, assignment))}")
        else:
            results.append("NO")
    return results"]

