["def findLongestEqualSubstring(S):
    """
    Returns the length of the longest substring containing an equal number of '2's and '3's.
    """
    n = len(S)
    balance = 0
    first_occurrence = {0: -1}
    max_length = 0

    for i in range(n):
        if S[i] == '2':
            balance += 1
        elif S[i] == '3':
            balance -= 1

        if balance in first_occurrence:
            max_length = max(max_length, i - first_occurrence[balance])
        else:
            first_occurrence[balance] = i

    return max_length"]

