["def increasing_triplet(nums):
    """
    Determines whether there exists a triplet (i, j, k) such that i < j < k and nums[i] < nums[j] < nums[k].
    """
    if len(nums) < 3:
        return False

    first = second = float('inf')
    for num in nums:
        if num <= first:
            first = num  # update first to be the smallest so far
        elif num <= second:
            second = num  # update second to the second smallest so far
        else:
            return True  # if we find a number greater than both first and second, we found our triplet

    return False"]

