["class IntervalTreeNode:
    def __init__(self, start, end):
        self.start = start
        self.end = end
        self.max_end = end
        self.left = None
        self.right = None

class IntervalTree:
    def __init__(self):
        self.root = None

    def add_reservation(self, start, end):
        if start >= end:
            return self.root
        self.root = self._insert(self.root, start, end)
        return self.root

    def _insert(self, node, start, end):
        if not node:
            return IntervalTreeNode(start, end)
        if start < node.start:
            node.left = self._insert(node.left, start, end)
        else:
            node.right = self._insert(node.right, start, end)
        node.max_end = max(node.max_end, end)
        return node

    def remove_reservation(self, start, end):
        if start >= end:
            return self.root
        self.root = self._delete(self.root, start, end)
        return self.root

    def _delete(self, node, start, end):
        if not node:
            return None

        if start < node.start:
            node.left = self._delete(node.left, start, end)
        elif start > node.start:
            node.right = self._delete(node.right, start, end)
        elif node.end == end:
            if not node.left:
                return node.right
            if not node.right:
                return node.left
            min_larger_node = self._get_min(node.right)
            node.start, node.end = min_larger_node.start, min_larger_node.end
            node.right = self._delete(node.right, min_larger_node.start, min_larger_node.end)
        node.max_end = max(node.end, self._get_max_end(node.left), self._get_max_end(node.right))
        return node

    def _get_min(self, node):
        while node.left:
            node = node.left
        return node

    def _get_max_end(self, node):
        return node.max_end if node else 0

    def check_overlap(self, start, end):
        return self._check_overlap(self.root, start, end)

    def _check_overlap(self, node, start, end):
        if not node:
            return False
        if node.start < end and start < node.end:
            return True
        if node.left and node.left.max_end > start:
            return self._check_overlap(node.left, start, end)
        return self._check_overlap(node.right, start, end)

    def get_sorted_reservations(self):
        results = []
        self._in_order_traversal(self.root, results)
        return results

    def _in_order_traversal(self, node, results):
        if not node:
            return
        self._in_order_traversal(node.left, results)
        results.append((node.start, node.end))
        self._in_order_traversal(node.right, results)"]

["def polycarp_can_sort(t, test_cases):
    results = []
    for test_case in test_cases:
        n, k, arr = test_case
        if k == n:
            results.append("YES")
            continue

        sorted_arr = sorted(arr)
        can_sort = True

        for i in range(n - k + 1):
            if arr[i] > arr[i + k - 1]:
                can_sort = False
                break

        if can_sort:
            results.append("YES")
        else:
            results.append("NO")

    return results"]

