class PersistentDict:
    def __init__(self, file_path: str):
        self.file_path = file_path

    def add(self, key: str, value: any) -> None:
        with shelve.open(self.file_path) as db:
            db[key] = value

    def get(self, key: str) -> any:
        with shelve.open(self.file_path) as db:
            if key not in db:
                raise KeyError(f"Key '{key}' not found")
            return db[key]

    def update(self, key: str, value: any) -> None:
        with shelve.open(self.file_path) as db:
            if key not in db:
                raise KeyError(f"Key '{key}' not found")
            db[key] = value

    def remove(self, key: str) -> None:
        with shelve.open(self.file_path) as db:
            if key not in db:
                raise KeyError(f"Key '{key}' not found")
            del db[key]

    def list_keys(self) -> list:
        with shelve.open(self.file_path) as db:
            return list(db.keys())"]

["def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
            elif p[j - 1] == '?' or s[i - 1] == p[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return dp[m][n]"]

["class ShoppingCart:
    def __init__(self):
        self.items = {}

    def add_item(self, name, price, quantity):
        if name in self.items:
            self.items[name]["quantity"] += quantity
        else:
            self.items[name] = {"price": price, "quantity": quantity}

    def remove_item(self, name, quantity):
        if name in self.items:
            if self.items[name]["quantity"] <= quantity:
                del self.items[name]
            else:
                self.items[name]["quantity"] -= quantity

    def get_total(self):
        total = sum(item["price"] * item["quantity"] for item in self.items.values())
        return total

    def get_items(self):
        return [(name, item["price"], item["quantity"]) for name, item in self.items.items()]"]

["import math
from typing import List, Tuple

class Circle:
    def __init__(self, x: float = 0.0, y: float = 0.0, r: float = 0.0):
        self.x = x
        self.y = y
        self.r = r

def dist(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    return math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)

def is_in_circle(circle: Circle, point: Tuple[float, float]) -> bool:
    return dist((circle.x, circle.y), point) <= circle.r + 1e-9

def make_circle_two_points(a: Tuple[float, float], b: Tuple[float, float]) -> Circle:
    cx = (a[0] + b[0]) / 2
    cy = (a[1] + b[1]) / 2
    r = dist(a, b) / 2
    return Circle(cx, cy, r)

def make_circle_three_points(a: Tuple[float, float], b: Tuple[float, float], c: Tuple[float, float]) -> Circle:
    A = b[0] - a[0]
    B = b[1] - a[1]
    C = c[0] - a[0]
    D = c[1] - a[1]
    E = A * (a[0] + b[0]) + B * (a[1] + b[1])
    F = C * (a[0] + c[0]) + D * (a[1] + c[1])
    G = 2 * (A * (c[1] - b[1]) - B * (c[0] - b[0]))
    if G == 0:
        return Circle()
    cx = (D * E - B * F) / G
    cy = (A * F - C * E) / G
    r = dist((cx, cy), a)
    return Circle(cx, cy, r)

def find_smallest_enclosing_circle(points: List[Tuple[int, int]]) -> Circle:
    def welzl_recursive(points: List[Tuple[int, int]], boundary: List[Tuple[int, int]], n: int) -> Circle:
        if n == 0 or len(boundary) == 3:
            if len(boundary) == 0:
                return Circle()
            elif len(boundary) == 1:
                return Circle(boundary[0][0], boundary[0][1], 0)
            elif len(boundary) == 2:
                return make_circle_two_points(boundary[0], boundary[1])
            elif len(boundary) == 3:
                return make_circle_three_points(boundary[0], boundary[1], boundary[2])

        p = points[n-1]
        circle = welzl_recursive(points, boundary, n-1)
        if is_in_circle(circle, p):
            return circle

        return welzl_recursive(points, boundary + [p], n-1)

    points_copy = points[:]
    return welzl_recursive(points_copy, [], len(points_copy))

def smallest_enclosing_circle(n: int, points: List[Tuple[int, int]]) -> Tuple[float, float, float]:
    circle = find_smallest_enclosing_circle(points)
    return (circle.x, circle.y, circle.r)"]

