["def process_operations(operations, log_file):
    class InvalidOperationTypeError(Exception):
        pass

    def evaluate_operation(operation, operation_type):
        try:
            parts = operation.split(' ')
            if len(parts) != 3:
                raise ValueError("Invalid format")

            left_operand, operator, right_operand = parts
            left_operand = float(left_operand)
            right_operand = float(right_operand)

            if operation_type == 'addition' and operator == '+':
                return left_operand + right_operand
            elif operation_type == 'subtraction' and operator == '-':
                return left_operand - right_operand
            elif operation_type == 'multiplication' and operator == '*':
                return left_operand * right_operand
            elif operation_type == 'division' and operator == '/':
                if right_operand == 0:
                    raise ZeroDivisionError
                return left_operand / right_operand
            else:
                raise InvalidOperationTypeError(f"Invalid operation type: {operation_type}")
        except ValueError:
            raise ValueError("Invalid mathematical expression")

    with open(log_file, 'w') as file:
        if not operations:
            file.write("No operations provided\n")
            return

        for operation, operation_type in operations:
            try:
                result = evaluate_operation(operation, operation_type)
                file.write(f"Operation: {operation}, Result: {result}\n")
            except ZeroDivisionError:
                file.write(f"Operation: {operation}, Result: division by zero error\n")
            except InvalidOperationTypeError as e:
                file.write(f"Operation: {operation}, Result: {str(e)}\n")
            except ValueError as e:
                file.write(f"Operation: {operation}, Result: invalid mathematical expression\n")
            except Exception as e:
                file.write(f"Operation: {operation}, Result: unexpected error: {str(e)}\n")"]

