["def evaluate_expression(expression: str) -> int:
    def helper(tokens):
        num_stack = []
        op_stack = []

        def precedence(op):
            if op in ('+', '-'):
                return 1
            if op in ('*', '/'):
                return 2
            return 0

        def apply_operator(op_stack, num_stack):
            right = num_stack.pop()
            left = num_stack.pop()
            op = op_stack.pop()
            if op == '+':
                num_stack.append(left + right)
            elif op == '-':
                num_stack.append(left - right)
            elif op == '*':
                num_stack.append(left * right)
            elif op == '/':
                num_stack.append(int(left / right))  # Ensure integer division

        i = 0
        while i < len(tokens):
            if tokens[i].isdigit():
                num = 0
                while i < len(tokens) and tokens[i].isdigit():
                    num = num * 10 + int(tokens[i])
                    i += 1
                num_stack.append(num)
                i -= 1
            elif tokens[i] == '(':
                op_stack.append(tokens[i])
            elif tokens[i] == ')':
                while op_stack and op_stack[-1] != '(':
                    apply_operator(op_stack, num_stack)
                op_stack.pop()  # Pop the opening '('
            elif tokens[i] in "+-*/":
                while (op_stack and precedence(op_stack[-1]) >= precedence(tokens[i])):
                    apply_operator(op_stack, num_stack)
                op_stack.append(tokens[i])
            i += 1

        while op_stack:
            apply_operator(op_stack, num_stack)

        return num_stack[0]

    return helper(list(expression))"]

