["class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        # Initialize the tree with the root node having value 1
        self.root = TreeNode(1)
        self.nodes = {1: self.root}

    def addNode(self, parent, child, direction):
        """
        Adds a new node with value `child` as a left or right child of the node with value `parent`.
        The direction is specified by the string `direction`, which can be either "left" or "right".
        It is guaranteed that parent already exists and child does not exist in the tree.
        """
        if parent in self.nodes:
            parent_node = self.nodes[parent]
            new_node = TreeNode(child)
            if direction == "left":
                parent_node.left = new_node
            elif direction == "right":
                parent_node.right = new_node
            self.nodes[child] = new_node

    def getPath(self, node):
        """
        Returns a list of node values representing the path from the root to the node with value `node`.
        If the node does not exist, return an empty list.
        """
        def dfs(current, target, path):
            if not current:
                return False
            path.append(current.value)
            if current.value == target:
                return True
            # Recurse on left and right
            if dfs(current.left, target, path) or dfs(current.right, target, path):
                return True
            path.pop()
            return False

        path = []
        if dfs(self.root, node, path):
            return path
        return []"]

