class SensorMovingAverage:
    def __init__(self, size: int):
        self.size = size
        self.window = deque()
        self.sum = 0

    def add_reading(self, val: int) -> float:
        if len(self.window) == self.size:
            self.sum -= self.window.popleft()

        self.window.append(val)
        self.sum += val

        return self.sum / len(self.window)"]

