["import pandas as pd
import numpy as np

def optimize_memory_usage(df: pd.DataFrame) -> pd.DataFrame:
    """
    Optimize the memory usage of a pandas DataFrame by modifying its column data types.

    Parameters:
    df (pd.DataFrame): The input DataFrame.

    Returns:
    pd.DataFrame: A DataFrame with optimized memory usage.
    """
    optimized_df = df.copy()

    for col in optimized_df.columns:
        col_type = optimized_df[col].dtypes

        if col_type == 'object':
            # Convert object columns to category if relatively few unique values
            if len(optimized_df[col].unique()) / len(optimized_df[col]) < 0.5:
                optimized_df[col] = optimized_df[col].astype('category')

        elif col_type == 'int64':
            # Convert int64 columns to smaller int types if possible
            if optimized_df[col].min() >= np.iinfo(np.int8).min and optimized_df[col].max() <= np.iinfo(np.int8).max:
                optimized_df[col] = optimized_df[col].astype('int8')
            elif optimized_df[col].min() >= np.iinfo(np.int16).min and optimized_df[col].max() <= np.iinfo(np.int16).max:
                optimized_df[col] = optimized_df[col].astype('int16')
            elif optimized_df[col].min() >= np.iinfo(np.int32).min and optimized_df[col].max() <= np.iinfo(np.int32).max:
                optimized_df[col] = optimized_df[col].astype('int32')

        elif col_type == 'float64':
            # Convert float64 columns to float32 if possible
            optimized_df[col] = optimized_df[col].astype('float32')

        elif col_type == 'int64' and optimized_df[col].hasnans:
            # Convert integer columns with NaNs to nullable integer types
            optimized_df[col] = optimized_df[col].astype(pd.Int64Dtype())

    return optimized_df"]

