["import re

def is_palindrome_iterative(s):
    """
    Check if a string is a palindrome using the iterative approach.
    Ignores case and non-alphanumeric characters.
    Returns True if the string is a palindrome, False otherwise.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    s = re.sub(r'[^a-zA-Z0-9]', '', s).lower()
    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return False
        left += 1
        right -= 1
    return True

def is_palindrome_recursive(s):
    """
    Check if a string is a palindrome using the recursive approach.
    Ignores case and non-alphanumeric characters.
    Returns True if the string is a palindrome, False otherwise.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    s = re.sub(r'[^a-zA-Z0-9]', '', s).lower()

    def helper_sub(s, left, right):
        if left >= right:
            return True
        if s[left] != s[right]:
            return False
        return helper_sub(s, left + 1, right - 1)

    return helper_sub(s, 0, len(s) - 1)"]

