["from typing import List, Dict, Union
import ipaddress

def summarize_ip_info(ip_addresses: List[str]) -> Dict[str, Union[str, int]]:
    ipv4_count = 0
    ipv6_count = 0
    network_dict = {}

    for ip in ip_addresses:
        ip_obj = ipaddress.ip_address(ip)
        if ip_obj.version == 4:
            ipv4_count += 1
            network = ipaddress.IPv4Network(ip + "/24", strict=False)
        else:
            ipv6_count += 1
            network = ipaddress.IPv6Network(ip + "/96", strict=False)

        network_str = str(network)
        if network_str in network_dict:
            network_dict[network_str] += 1
        else:
            network_dict[network_str] = 1

    # Find the largest network
    largest_network = max(network_dict, key=network_dict.get)

    return {
        "total_ipv4": ipv4_count,
        "total_ipv6": ipv6_count,
        "networks": list(network_dict.keys()),
        "largest_network": largest_network
    }"]

["def can_be_strictly_increasing(n, sequence):
    """
    Determines if the sequence can be made strictly increasing by at most one swap.
    """
    def is_increasing(seq):
        return all(seq[i] < seq[i+1] for i in range(len(seq) - 1))

    if is_increasing(sequence):
        return "YES"

    # Check for candidates to swap
    for i in range(n):
        for j in range(i + 1, n):
            # Swap elements at indices i and j
            sequence[i], sequence[j] = sequence[j], sequence[i]
            if is_increasing(sequence):
                return "YES"
            # Swap them back
            sequence[i], sequence[j] = sequence[j], sequence[i]

    return "NO""]

