["import heapq

def find_min_max_cost(N, M, roads):
    def dijkstra_max_edge_cost(graph, N):
        max_edge_cost = [float('inf')] * (N + 1)
        max_edge_cost[1] = 0
        priority_queue = [(0, 1)]

        while priority_queue:
            max_cost, node = heapq.heappop(priority_queue)

            for neighbor, cost in graph[node]:
                new_max_cost = max(max_cost, cost)
                if new_max_cost < max_edge_cost[neighbor]:
                    max_edge_cost[neighbor] = new_max_cost
                    heapq.heappush(priority_queue, (new_max_cost, neighbor))

        return max_edge_cost[N]

    graph = {i: [] for i in range(1, N+1)}
    for u, v, cost in roads:
        graph[u].append((v, cost))
        graph[v].append((u, cost))

    return dijkstra_max_edge_cost(graph, N)"]

