    def __init__(self):
        self.flights = {}

    def book(self, flight_id, seat_number):
        if flight_id not in self.flights:
            self.flights[flight_id] = set()
        if seat_number not in self.flights[flight_id]:
            self.flights[flight_id].add(seat_number)
            return "SUCCESS"
        return "FAIL"

    def cancel(self, flight_id, seat_number):
        if flight_id in self.flights and seat_number in self.flights[flight_id]:
            self.flights[flight_id].remove(seat_number)
            return "SUCCESS"
        return "FAIL"

