["def minimum_review_groups(n, devs_bugs):
    """
    Returns the minimum number of review groups.
    """
    sets_of_bugs = [set(dev_bugs) for dev_bugs in devs_bugs]
    visited = [False] * n

    def can_review(dev_a, dev_b):
        """ Returns True if developer A can review developer B """
        return sets_of_bugs[dev_b].issubset(sets_of_bugs[dev_a])

    def dfs(dev, group):
        """ Depth-First Search to mark all developers in the same group """
        stack = [dev]
        while stack:
            current_dev = stack.pop()
            if not visited[current_dev]:
                visited[current_dev] = True
                for next_dev in range(n):
                    if not visited[next_dev] and can_review(current_dev, next_dev):
                        stack.append(next_dev)
                    if not visited[next_dev] and can_review(next_dev, current_dev):
                        stack.append(next_dev)

    # Count number of groups
    group_count = 0
    for dev in range(n):
        if not visited[dev]:
            group_count += 1
            dfs(dev, group_count)

    return group_count"]

["def four_sum(arr, num):
    """
    Finds all unique quadruplets in the list `arr` that sum up to `num`.
    """
    arr.sort()
    quadruplets = set()

    for i in range(len(arr) - 3):
        for j in range(i + 1, len(arr) - 2):
            left, right = j + 1, len(arr) - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == num:
                    quadruplets.add((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif total < num:
                    left += 1
                else:
                    right -= 1

    return [list(quad) for quad in sorted(quadruplets)]"]

