from typing import List, Tuple

def find_most_active_user(activities: List[Tuple[int, str]], start: int, end: int) -> str:
    user_activity_count = defaultdict(int)

    for timestamp, user_id in activities:
        if start <= timestamp <= end:
            user_activity_count[user_id] += 1

    most_activities = max(user_activity_count.values(), default=0)
    most_active_users = [user for user, count in user_activity_count.items() if count == most_activities]

