["def caesar_cipher_shift(char, shift):
    """
    Helper function to shift a character by a given number using Caesar Cipher.
    """
    if char.islower():
        return chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
    elif char.isupper():
        return chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
    else:
        return char

def apply_caesar_cipher(s, queries):
    """
    Applies the caesar cipher as per the given queries and finds the k-th character
    after each transformation.
    """
    result = []
    for L, R, k, shift in queries:
        # Substring extraction and shifting
        shifted_substring = ''.join(caesar_cipher_shift(s[i], shift) for i in range(L, R + 1))
        # Find the k-th character (1-indexed)
        result.append(shifted_substring[k - 1])
    return result"]

["def evaluate_expression(s):
    """
    Evaluates a mathematical expression string containing non-negative integers and the operators +, -, *, and /.
    The expression may also contain parentheses to specify the order of operations.
    """

    def operate(op, second, first):
        if op == '+':
            return first + second
        elif op == '-':
            return first - second
        elif op == '*':
            return first * second
        elif op == '/':
            return int(first / second)  # truncate towards zero

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def calculate(tokens):
        num_stack = []
        op_stack = []
        i = 0

        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue
            if tokens[i].isdigit():
                num = 0
                while i < len(tokens) and tokens[i].isdigit():
                    num = num * 10 + int(tokens[i])
                    i += 1
                num_stack.append(num)
                i -= 1
            elif tokens[i] == '(':
                op_stack.append(tokens[i])
            elif tokens[i] == ')':
                while op_stack and op_stack[-1] != '(':
                    num_stack.append(operate(op_stack.pop(), num_stack.pop(), num_stack.pop()))
                op_stack.pop()
            else:
                while op_stack and precedence(op_stack[-1]) >= precedence(tokens[i]):
                    num_stack.append(operate(op_stack.pop(), num_stack.pop(), num_stack.pop()))
                op_stack.append(tokens[i])
            i += 1

        while op_stack:
            num_stack.append(operate(op_stack.pop(), num_stack.pop(), num_stack.pop()))

        return num_stack[0]

    return calculate(list(s))"]

