import torch.nn as nn
import torch.fx

def replace_relu_with_leaky_relu(model: nn.Module, negative_slope: float = 0.01) -> nn.Module:
    class ReplaceReLUTracer(torch.fx.Tracer):
        def is_leaf_module(self, m: torch.nn.Module, qualname: str):
            # Consider all modules as leaf modules except `ReLU`
            if isinstance(m, nn.ReLU):
                return False
            return super().is_leaf_module(m, qualname)

    tracer = ReplaceReLUTracer()
    graph = tracer.trace(model)

    # Modify graph to replace ReLU with LeakyReLU
    for node in graph.nodes:
        if node.op == 'call_module' and isinstance(tracer.root.get_submodule(node.target), nn.ReLU):
            # Create a new LeakyReLU module and swap it in
            new_module_name = f"{node.target}_leakyrelu"
            leaky_relu = nn.LeakyReLU(negative_slope=negative_slope)
            tracer.root.add_module(new_module_name, leaky_relu)
            node.target = new_module_name

    # Recompile and return the new graph module
    new_graph_module = torch.fx.GraphModule(tracer.root, graph)
    return new_graph_module"]

["def longestSubstring(s, k):
    """
    Returns the length of the longest substring where every character appears at least `k` times.
    """
    def longest_substring_helper(s, k, start, end):
        if end - start < k:
            return 0

        count = [0] * 26

        for i in range(start, end):
            count[ord(s[i]) - ord('a')] += 1

        for mid in range(start, end):
            if count[ord(s[mid]) - ord('a')] >= k:
                continue

            next_mid = mid + 1
            while next_mid < end and count[ord(s[next_mid]) - ord('a')] < k:
                next_mid += 1

            return max(longest_substring_helper(s, k, start, mid),
                       longest_substring_helper(s, k, next_mid, end))

        return end - start

    return longest_substring_helper(s, k, 0, len(s))"]

