    """
    Returns starting indices of all occurrences of pattern p in string s.
    """
    def kmp_pattern(p):
        """Preprocesses the pattern to create the 'longest prefix-suffix' (LPS) array for KMP algorithm."""
        lps = [0] * len(p)
        j = 0
        for i in range(1, len(p)):
            while (j > 0 and p[i] != p[j]):
                j = lps[j - 1]
            if p[i] == p[j]:
                j += 1
                lps[i] = j
        return lps

    lps = kmp_pattern(p)
    indices = []

    i = 0
    j = 0
    while i < len(s):
        if p[j] == s[i]:
            i += 1
            j += 1
        if j == len(p):
