["def infix_to_postfix(expression):
    """
    Converts an infix expression to postfix notation.

    Args:
    expression (str): A string containing a mathematical expression in infix notation.

    Returns:
    str: A string containing the expression in postfix notation.
    """
    precedence = {'+':1, '-':1, '*':2, '/':2}
    def is_operator(c):
        return c in precedence

    def precedence_of(c):
        return precedence[c]

    def infix_to_postfix_conversion(expression):
        output = []
        stack = []

        for char in expression.split():
            if char.isdigit():
                output.append(char)
            elif is_operator(char):
                while (stack and stack[-1] != '(' and
                      precedence_of(stack[-1]) >= precedence_of(char)):
                    output.append(stack.pop())
                stack.append(char)
            elif char == '(':
                stack.append(char)
            elif char == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                stack.pop()  # pop '(' from stack

        while stack:
            output.append(stack.pop())

        return ' '.join(output)

    return infix_to_postfix_conversion(expression)"]

