["def canComplete(tasks, T, maxTime):
    current_slot_time = 0
    slots_used = 1

    for task in tasks:
        if current_slot_time + task <= maxTime:
            current_slot_time += task
        else:
            slots_used += 1
            current_slot_time = task

            if slots_used > T:
                return False

    return True

def minRequiredMaxTime(tasks, T):
    left, right = max(tasks), sum(tasks)

    while left < right:
        mid = (left + right) // 2

        if canComplete(tasks, T, mid):
            right = mid
        else:
            left = mid + 1

    return left"]

