["def manage_festival(n, m, paths):
    """
    Determine if each added path maintains a tree structure
    """
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            elif rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                rank[root_u] += 1
            return True
        return False

    result = []
    for u, v in paths:
        if union(u, v):
            result.append("YES")
        else:
            result.append("NO")

    return result"]

["from typing import Union

def calculate_side(opposite: Union[float, str], adjacent: Union[float, str], hypotenuse: Union[float, str]) -> float:
    # Validation: only one side can be '?'
    sides = [opposite, adjacent, hypotenuse]
    if sides.count('?') != 1:
        raise ValueError("Exactly one side must be unknown.")

    # Function to parse side or raise ValueError if side is invalid
    def parse_side(side):
        if isinstance(side, (int, float)) and side > 0:
            return float(side)
        raise ValueError("Sides must be positive numbers or '?' to denote the unknown side.")

    # Parse the sides
    known_sides = [parse_side(side) if side != '?' else None for side in sides]

    # Calculate unknown side using Pythagorean theorem
    if opposite == '?':
        adjacent, hypotenuse = known_sides[1], known_sides[2]
        return (hypotenuse**2 - adjacent**2) ** 0.5
    elif adjacent == '?':
        opposite, hypotenuse = known_sides[0], known_sides[2]
        return (hypotenuse**2 - opposite**2) ** 0.5
    elif hypotenuse == '?':
        opposite, adjacent = known_sides[0], known_sides[1]
        return (opposite**2 + adjacent**2) ** 0.5
    else:
        raise ValueError("Invalid input: All sides are known.")"]

