["from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_target(root, target):
    if not root:
        return None
    if root.val == target:
        return root
    left_search = find_target(root.left, target)
    if left_search:
        return left_search
    return find_target(root.right, target)

def k_distance_nodes_dfs(node, k, result, visited):
    if not node or node in visited:
        return
    visited.add(node)
    if k == 0:
        result.append(node.val)
        return
    k_distance_nodes_dfs(node.left, k-1, result, visited)
    k_distance_nodes_dfs(node.right, k-1, result, visited)

def k_distance_nodes_upwards(node, target, k, result, visited):
    if not node or node in visited:
        return -1
    if node.val == target:
        k_distance_nodes_dfs(node, k, result, visited)
        return 0

    dl = k_distance_nodes_upwards(node.left, target, k, result, visited)
    if dl != -1:
        if dl + 1 == k:
            result.append(node.val)
        else:
            k_distance_nodes_dfs(node.right, k - dl - 2, result, visited)
        return 1 + dl

    dr = k_distance_nodes_upwards(node.right, target, k, result, visited)
    if dr != -1:
        if dr + 1 == k:
            result.append(node.val)
        else:
            k_distance_nodes_dfs(node.left, k - dr - 2, result, visited)
        return 1 + dr

    return -1

def k_distance_nodes(root: TreeNode, target: int, k: int) -> List[int]:
    target_node = find_target(root, target)
    if not target_node:
        return []
    result = []
    visited = set()
    k_distance_nodes_upwards(root, target, k, result, visited)
    return sorted(result)"]

