["def word_puzzle_score(grid, words):
    def can_form_word(word):
        from collections import Counter

        word_counter = Counter(word)
        grid_counter = Counter()

        for row in grid:
            grid_counter.update(row)

        for letter, count in word_counter.items():
            if grid_counter[letter] < count:
                return False
        return True

    def word_score(word):
        length = len(word)
        if length == 2:
            return 1
        elif length == 3:
            return 2
        elif length >= 4:
            return 3
        return 0

    total_score = 0
    for word in words:
        if can_form_word(word):
            total_score += word_score(word)

    return total_score"]

