            text = mmap_file.read().decode('utf-8', errors='ignore')
            if regex:
                for match in re.finditer(keyword, text):
                    print(text[match.start():].split('\n', 1)[0])
            elif case_sensitive:
                for i in range(len(text)):
                    if text.startswith(keyword, i):
                        print(text[i:].split('\n', 1)[0])
            else:
                for i in range(len(text)):
                    if text.lower().startswith(keyword.lower(), i):
                        print(text[i:].split('\n', 1)[0])
            mmap_file.close()
    except FileNotFoundError:
        print(f"{filename} not found.")
    except UnicodeDecodeError:
        print(f"{filename} is not a text file.")
    except OSError:
        print(f"Failed to memory map {filename}.")
