        return all(s[k] == s[j - k + i] for k in range(i, j))

    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            if is_palindrome_range(l + 1, r) or is_palindrome_range(l, r - 1):
                return "YES"
            else:
                return "NO"
        l, r = l + 1, r - 1
    return "YES""]

["def can_reach_all_dfs(graph, start):
    """
    Determines if all nodes in the graph are reachable from the start node using DFS.
    """
    def dfs(node, visited):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor, visited)

    visited = set()
    dfs(start, visited)

    return len(visited) == len(graph)

def can_reach_all_bfs(graph, start):
    """
    Determines if all nodes in the graph are reachable from the start node using BFS.
    """
    from collections import deque

    visited = set()
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    queue.append(neighbor)

    return len(visited) == len(graph)"]

