["def calculate_average_response_time(file_path: str) -> float:
    total_time = 0
    count = 0

    try:
        with open(file_path, 'r') as file:
            for line in file:
                if "Request processed in" in line:
                    parts = line.split()
                    time_part = parts[-1]  # e.g., "150ms"
                    response_time = int(time_part[:-2])  # Convert "150ms" to 150
                    total_time += response_time
                    count += 1

        if count == 0:
            return 0.00

        average = total_time / count
        return round(average, 2)

    except FileNotFoundError:
        raise FileNotFoundError(f"The file at path {file_path} does not exist.")
    except Exception as e:
