["def split_array(nums, k):
    def can_split(max_sum):
        current_sum = 0
        subarray_count = 1
        for num in nums:
            if current_sum + num > max_sum:
                current_sum = num
                subarray_count += 1
                if subarray_count > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left"]

