["def can_convert(s, t):
    """
    Determine if string s can be converted into string t by replacing each character in s with another character.
    Each character in s should map to the same character in t and no two characters in s should map to the same character in t.
    """
    if len(s) != len(t):
        return False

    s_to_t_mapping = {}
    t_to_s_mapping = {}

    for sc, tc in zip(s, t):
        if sc in s_to_t_mapping:
            if s_to_t_mapping[sc] != tc:
                return False
        else:
            s_to_t_mapping[sc] = tc

        if tc in t_to_s_mapping:
            if t_to_s_mapping[tc] != sc:
                return False
        else:
            t_to_s_mapping[tc] = sc

    return True"]

