["def max_square_size(n, m, grid):
    if n == 0 or m == 0:
        return 0

    max_side = 0
    dp = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                if dp[i][j] > max_side:
                    max_side = dp[i][j]

    return max_side"]

