["from typing import Any, List, Optional


class Node:
    def __init__(self, value: int):
        self.value = value
        self.left: Optional[Node] = None
        self.right: Optional[Node] = None


class FullBinaryTree:
    def __init__(self):
        self.root: Optional[Node] = None
        self.queue: List[Node] = []

    def add_node(self, value: int) -> None:
        new_node = Node(value)
        if not self.root:
            self.root = new_node
            self.queue.append(new_node)
        else:
            while self.queue:
                parent = self.queue[0]
                if not parent.left:
                    parent.left = new_node
                    self.queue.append(new_node)
                    break
                elif not parent.right:
                    parent.right = new_node
                    self.queue.append(new_node)
                    self.queue.pop(0)
                    break

    def is_full_binary_tree(self) -> bool:
        if not self.root:
            return True
        queue = [self.root]
        while queue:
            node = queue.pop(0)
            if node.left and node.right:
                queue.append(node.left)
                queue.append(node.right)
            elif not node.left and not node.right:
                continue
            else:
                return False
        return True

    def get_depth(self) -> int:
        def depth(node: Optional[Node]) -> int:
            if not node:
                return 0
            left_depth = depth(node.left)
            right_depth = depth(node.right)
            return max(left_depth, right_depth) + 1

        return depth(self.root)

    def traversal(self, order: str) -> List[int]:
        result = []
        if order == "inorder":
            self._inorder_traversal(self.root, result)
        elif order == "preorder":
            self._preorder_traversal(self.root, result)
        elif order == "postorder":
            self._postorder_traversal(self.root, result)
        elif order == "levelorder":
            self._levelorder_traversal(self.root, result)
        return result

    def _inorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.value)
            self._inorder_traversal(node.right, result)

    def _preorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            result.append(node.value)
            self._preorder_traversal(node.left, result)
            self._preorder_traversal(node.right, result)

    def _postorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            self._postorder_traversal(node.left, result)
            self._postorder_traversal(node.right, result)
            result.append(node.value)

    def _levelorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if not node:
            return
        queue = [node]
        while queue:
            current = queue.pop(0)
            result.append(current.value)
            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)"]

