["def prime_sequence_count(n):
    """
    Returns the number of prime numbers that are less than or equal to n.
    """
    if n < 2:
        return 0

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False

    p = 2
    while p * p <= n:
        if sieve[p]:
            for i in range(p * p, n + 1, p):
                sieve[i] = False
        p += 1

    return sum(sieve)

def process_queries(t, queries):
    results = []
    for n in queries:
        results.append(prime_sequence_count(n))
    return results"]

["from typing import List

def enhanced_interpolation_search(array: List[int], search_key: int) -> int:
    def is_sorted(arr: List[int]) -> bool:
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

    # Return -1 if array is empty or not sorted
    if not array or not is_sorted(array):
        return -1

    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        # Handle division by zero case here
        if array[low] == array[high]:
            if array[low] == search_key:
                return low
            break

        # Interpolation formula
        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        # Ensure pos is within bounds
        if pos < 0 or pos >= len(array):
            return -1

        # Check if we found the search_key
        if array[pos] == search_key:
            return pos

        # If search_key is larger, search in the upper part
        if array[pos] < search_key:
            low = pos + 1
        # If search_key is smaller, search in the lower part
        else:
            high = pos - 1

    return -1"]

