["def find_basin(grid):
    assert isinstance(grid, list) and all(isinstance(row, list) for row in grid), "Invalid grid format."
    m, n = len(grid), len(grid[0])

    lowest_basins = []
    lowest_elevation = float('inf')

    for i in range(m):
        for j in range(n):
            current_elevation = grid[i][j]
            neighbors = []
            if i > 0:
                neighbors.append(grid[i-1][j])
            if i < m-1:
                neighbors.append(grid[i+1][j])
            if j > 0:
                neighbors.append(grid[i][j-1])
            if j < n-1:
                neighbors.append(grid[i][j+1])

            if current_elevation <= min(neighbors, default=current_elevation):
                if current_elevation < lowest_elevation:
                    lowest_elevation = current_elevation
                    lowest_basins = [(i, j)]
                elif current_elevation == lowest_elevation:
                    lowest_basins.append((i, j))

    return lowest_basins"]

