["def max_distinct_characters(S):
    """
    Returns the maximum number of different characters that can remain
    in the string S after performing the operation of removing adjacent
    same characters any number of times.
    """
    stack = []

    for char in S:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return len(set(stack))

def solve(T, test_cases):
    results = []
    for S in test_cases:
        results.append(max_distinct_characters(S))
    return results"]

["import datetime
from zoneinfo import ZoneInfo

def get_local_times(utc_dt: datetime.datetime, tz_keys: list[str]) -> dict[str, tuple[datetime.datetime, bool]]:
    result = {}
    for tz_key in tz_keys:
        tz_info = ZoneInfo(tz_key)
        local_dt = utc_dt.astimezone(tz_info)
        is_dst = local_dt.dst() != datetime.timedelta(0)
        result[tz_key] = (local_dt, is_dst)
    return result"]

