["import hashlib
from typing import Tuple

class URLShortener:
    def __init__(self):
        self.url_map = {}
        self.reverse_url_map = {}
        self.access_count = 0

    def shorten_url(self, long_url: str) -> str:
        short_url = self._generate_short_url(long_url)
        self.url_map[short_url] = long_url
        self.reverse_url_map[long_url] = short_url
        return short_url

    def retrieve_long_url(self, short_url: str) -> str:
        self.access_count += 1
        return self.url_map.get(short_url, '')

    def delete_url(self, short_url: str) -> bool:
        if short_url in self.url_map:
            long_url = self.url_map.pop(short_url)
            if long_url:
                self.reverse_url_map.pop(long_url, None)
            return True
        return False

    def get_stats(self) -> Tuple[int, int]:
        return len(self.url_map), self.access_count

    def _generate_short_url(self, long_url: str) -> str:
        hash_object = hashlib.md5(long_url.encode())
        return 'http://short.ly/' + hash_object.hexdigest()[:6]"]

