["def minimum_candies_needed(n, candies):
    if n == 1:
        return 1

    candies_needed = [1] * n

    for i in range(1, n):
        if candies[i] > candies[i - 1]:
            candies_needed[i] = candies_needed[i - 1] + 1

    for i in range(n-2, -1, -1):
        if candies[i] > candies[i + 1]:
            candies_needed[i] = max(candies_needed[i], candies_needed[i + 1] + 1)

    return sum(candies_needed)"]

