["import csv
import os

def process_csv(input_file_path: str, output_file_path: str) -> None:
    """
    Reads a CSV file, modifies its content based on specific conditions, and writes the modified content to a new CSV file.
    """

    if not os.path.exists(input_file_path):
        raise FileNotFoundError(f"The file {input_file_path} does not exist.")

    with open(input_file_path, mode='r', newline='', encoding='utf-8') as infile:
        reader = csv.DictReader(infile)
        fieldnames = reader.fieldnames

        if "name" not in fieldnames:
            raise ValueError("The input CSV must contain a 'name' column.")

        rows = []

        for row in reader:
            if 'name' in row:
                row['name'] = row['name'].upper() if row['name'] else row['name']

            if 'price' in row:
                try:
                    row['price'] = round(float(row['price']) * 1.2, 2) if row['price'] else 0
                except ValueError:
                    row['price'] = 0

            if 'date' in row:
                if row['date']:
                    try:
                        day, month, year = row['date'].split('-')
                        row['date'] = f"{year}-{month.zfill(2)}-{day.zfill(2)}"
                    except ValueError:
                        row['date'] = row['date']

            rows.append(row)

    with open(output_file_path, mode='w', newline='', encoding='utf-8') as outfile:
        writer = csv.DictWriter(outfile, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)"]

