["def max_items(grid):
    m, n = len(grid), len(grid[0])
    visited = [[False for _ in range(n)] for _ in range(m)]
    items_collected = [0, 0, 0]

    def collect_items(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or visited[x][y]:
            return
        item_type = grid[x][y]
        if item_type > 0:
            items_collected[item_type - 1] += 1
            visited[x][y] = True

        collect_items(x + 1, y)
        collect_items(x - 1, y)
        collect_items(x, y + 1)
        collect_items(x, y - 1)

    for i in range(m):
        for j in range(n):
            if not visited[i][j] and grid[i][j] > 0:
                collect_items(i, j)

    return items_collected"]

