["import heapq

def perform_operations(operations):
    """
    Perform a sequence of operations on a list of integers and return the results of find_min operations.

    :param operations: List of tuples, where each tuple represents an operation.
                       Operations are of the form (0, v), (1, v), or (2, None).
    :return: List of integers representing the results of find_min operations.
    """
    heap = []
    min_count = {}
    results = []

    for operation in operations:
        if operation[0] == 0:
            # add operation
            v = operation[1]
            heapq.heappush(heap, v)
            if v in min_count:
                min_count[v] += 1
            else:
                min_count[v] = 1
        elif operation[0] == 1:
            # remove operation
            v = operation[1]
            if v in min_count and min_count[v] > 0:
                min_count[v] -= 1
        elif operation[0] == 2:
            # find_min operation
            while heap and min_count[heap[0]] == 0:
                heapq.heappop(heap)
            if heap:
                results.append(heap[0])

    return results"]

