["def process_operations(n, operations):
    stack = []
    peek_outputs = []

    for operation in operations:
        if operation.startswith("PUSH"):
            _, x = operation.split()
            stack.append(int(x))
        elif operation == "POP":
            if stack:
                stack.pop()
        elif operation == "PEEK":
            if stack:
                peek_outputs.append(str(stack[-1]))
            else:
                peek_outputs.append("EMPTY")

    final_stack = "EMPTY" if not stack else " ".join(map(str, stack))
    return peek_outputs, final_stack"]

