["from typing import List

def find_n_sum_combinations(n: int, nums: List[int], target: int) -> List[List[int]]:
    def k_sum(nums, target, k, path):
        if not nums:
            return

        # Base case for 2-sum problem
        if k == 2:
            left, right = 0, len(nums) - 1
            while left < right:
                curr_sum = nums[left] + nums[right]
                if curr_sum == target:
                    result.append(path + [nums[left], nums[right]])
                    left += 1
                    right -= 1
                    while left < right and nums[left] == nums[left - 1]:
                        left += 1
                    while left < right and nums[right] == nums[right + 1]:
                        right -= 1
                elif curr_sum < target:
                    left += 1
                else:
                    right -= 1
        else:
            for i in range(len(nums) - k + 1):
                if i == 0 or nums[i - 1] != nums[i]:
                    k_sum(nums[i + 1:], target - nums[i], k - 1, path + [nums[i]])

    nums.sort()
    result = []
    k_sum(nums, target, n, [])
    return result"]

