import concurrent.futures

# Put your API key(s) here
GOOGLE_BOOKS_API_KEY = "your_google_books_api_key"
GOODREADS_API_KEY = "your_goodreads_api_key"

GOOGLE_BOOKS_URL_BASE = "https://www.googleapis.com/books/v1/volumes"
GOODREADS_URL_BASE = "https://www.goodreads.com/book/isbn"

def fetch_google_books_data(isbn):
    try:
        response = requests.get(f"{GOOGLE_BOOKS_URL_BASE}?q=isbn:{isbn}&key={GOOGLE_BOOKS_API_KEY}")
        response.raise_for_status()
        data = response.json()
        if 'items' in data and len(data['items']) > 0:
            book_info = data['items'][0]['volumeInfo']
            return {
                'title': book_info.get('title'),
                'authors': book_info.get('authors'),
                'description': book_info.get('description')
            }
        return None
    except Exception as e:
        return {"error": str(e)}

def fetch_goodreads_data(isbn):
    try:
        response = requests.get(f"{GOODREADS_URL_BASE}?format=json&isbn={isbn}&key={GOODREADS_API_KEY}")
        response.raise_for_status()
        data = response.json()
        return {
            'average_rating': data.get('average_rating'),
            'reviews': data.get('reviews')
        }
    except Exception as e:
        return {"error": str(e)}

def get_book_info(isbn: str) -> dict:
    if not isbn:
        return {"error": "Invalid ISBN format"}

    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_google = executor.submit(fetch_google_books_data, isbn)
        future_goodreads = executor.submit(fetch_goodreads_data, isbn)
        google_data = future_google.result()
        goodreads_data = future_goodreads.result()

    result = {
        "GoogleBooks": google_data,
        "Goodreads": goodreads_data
    }

    return result"]

