def find_non_adjacent_sum(arr: List[int]) -> int:
    """
    Finds the maximum sum of elements in the list such that no two elements are adjacent.
    """
    if not arr:
        return 0
    if len(arr) == 1:
        return max(0, arr[0])

    incl = max(0, arr[0])
    excl = 0

    for i in range(1, len(arr)):
        new_excl = max(incl, excl)
        incl = excl + arr[i]
        excl = new_excl

    return max(incl, excl)"]

