["def factorial(n):
    """
    Returns the factorial of a positive integer n.
    If n is not a positive integer, handle cases accordingly.
    """
    if not isinstance(n, int):
        try:
            n = int(n)
        except ValueError:
            return "Input is not a number and cannot be converted to an integer."

    if n < 0:
        return "Factorial is not defined for negative numbers."

    if n == 0:
        return 1

    return n * factorial(n - 1)"]

