["def is_one_sparse(stream):
    """
    Determines if a given stream of tuples represents a 1-sparse recovery.
    The stream consists of tuples containing a non-negative number and a sign ('+' or '-').
    Returns the unique value if the stream is 1-sparse, None otherwise.
    """
    value_counts = {}

    for num, sign in stream:
        if sign == '+':
            value_counts[num] = value_counts.get(num, 0) + 1
        elif sign == '-':
            value_counts[num] = value_counts.get(num, 0) - 1

    unique_number = None
    for num, count in value_counts.items():
        if count > 0:
            if unique_number is None:
                unique_number = num
            else:
                return None

    return unique_number"]

