["def can_be_increasing(arr):
    """
    Determine if the array can be made strictly increasing
    by removing at most one element.
    """
    def is_increasing(arr):
        return all(arr[i] < arr[i+1] for i in range(len(arr) - 1))

    n = len(arr)
    for i in range(n):
        if is_increasing(arr[:i] + arr[i+1:]):
            return "YES"
    return "NO"

def process_test_cases(T, test_cases):
