["from typing import Callable, List, Optional, Union

def enhanced_binary_search(collection: List[int],
                           target: int,
                           comparator: Optional[Callable[[int, int], bool]] = None,
                           find_first: bool = False,
                           find_last: bool = False,
                           return_nearest: bool = False) -> Union[int, None]:
    if not collection:
        return None

    def default_comparator(a, b):
        return a < b

    if comparator is None:
        comparator = default_comparator

    lo, hi = 0, len(collection) - 1
    result = None
    nearest_index = None

    while lo <= hi:
        mid = (lo + hi) // 2

        if collection[mid] == target:
            result = mid
            if find_first:
                hi = mid - 1
            elif find_last:
                lo = mid + 1
            else:
                return mid
        elif comparator(collection[mid], target):
            lo = mid + 1
            nearest_index = mid
        else:
            hi = mid - 1
            if nearest_index is None or (abs(collection[mid] - target) < abs(collection[nearest_index] - target)):
                nearest_index = mid

    if result is not None:
        return result

    if return_nearest and nearest_index is not None:
        return nearest_index

    return None"]

["def next_generation(grid):
    def count_live_neighbors(x, y):
        live_neighbors = 0
        for i in range(x-1, x+2):
            for j in range(y-1, y+2):
                if (i == x and j == y) or i < 0 or j < 0 or i >= len(grid) or j >= len(grid[0]):
                    continue
                live_neighbors += grid[i][j]
        return live_neighbors

    next_gen = []
    for i in range(len(grid)):
        next_row = []
        for j in range(len(grid[0])):
            live_neighbors = count_live_neighbors(i, j)
            if grid[i][j] == 1:
                if live_neighbors < 2 or live_neighbors > 3:
                    next_row.append(0)
                else:
                    next_row.append(1)
            else:
                if live_neighbors == 3:
                    next_row.append(1)
                else:
                    next_row.append(0)
        next_gen.append(next_row)

    return next_gen"]

