["def can_reach_end(grid, start_row, start_col, end_row, end_col):
    def is_valid_move(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

    def dfs(x, y):
        # If we reached the end cell
        if (x, y) == (end_row, end_col):
            return True
        # Mark the cell as visited
        grid[x][y] = -1
        # Explore the four possible directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny) and dfs(nx, ny):
                return True
        return False

    return dfs(start_row, start_col)"]

["def min_operations_to_unique_chars(s):
    """
    This function returns the minimum number of operations needed to make
    all characters in the string unique.
    """
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    operations = 0
    for count in char_count.values():
        if count > 1:
            operations += count - 1

