["from collections import deque, defaultdict

def calculate_likes(N, M, friendships, A, actions):
    friends_graph = defaultdict(set)
    for i in range(N):
        user, *friends = friendships[i]
        friends_graph[user].update(friends)
        for friend in friends:
            friends_graph[friend].add(user)

    shared_posts = set()
    visible_posts = defaultdict(set)

    for action in actions:
        action_type, user_id_str = action.split()
        user_id = int(user_id_str)

        if action_type == "share":
            shared_posts.add(user_id)
            queue = deque([user_id])
            while queue:
                current = queue.popleft()
                for friend in friends_graph[current]:
                    if current not in visible_posts[friend]:
                        visible_posts[friend].add(current)
                        queue.append(friend)

    likes_count = 0

    for action in actions:
        action_type, user_id_str = action.split()
        user_id = int(user_id_str)

        if action_type == "like" and visible_posts[user_id]:
            likes_count += 1

    return likes_count"]

