["def process_queries(N, M, Q, grid, queries):
    def update_grid(grid, r, c, v):
        grid[r-1][c-1] = v

    def sum_subgrid(grid, r1, c1, r2, c2):
        total = 0
        for i in range(r1-1, r2):
            total += sum(grid[i][c1-1:c2])
        return total

    results = []
    for query in queries:
        parts = query.split()
        if parts[0] == 'U':
            r, c, v = map(int, parts[1:])
            update_grid(grid, r, c, v)
        elif parts[0] == 'S':
