["def min_swaps_to_palindrome(s):
    def is_palindrome_possible(s):
        odd_count = sum([1 for c in set(s) if s.count(c) % 2 != 0])
        return odd_count <= 1

    def count_min_swaps(s):
        s = list(s)
        swaps = 0
        left = 0
        right = len(s) - 1
        while left < right:
            if s[left] == s[right]:
                left += 1
                right -= 1
            else:
                k = right
                while k > left and s[k] != s[left]:
                    k -= 1
                if k == left:
                    s[left], s[left + 1] = s[left + 1], s[left]
                    swaps += 1
                else:
                    for j in range(k, right):
                        s[j], s[j + 1] = s[j + 1], s[j]
                        swaps += 1
                    left += 1
                    right -= 1
        return swaps

    if not is_palindrome_possible(s):
        return -1
    return count_min_swaps(s)

def process_test_cases(T, cases):
    results = []
    for s in cases:
        results.append(min_swaps_to_palindrome(s))
    return results"]

