["from fractions import Fraction
from typing import List, Dict

class Monomial:
    def __init__(self, variables: Dict[int, int], coefficient: Fraction):
        self.variables = variables  # Dictionary where key is variable and value is its exponent
        self.coefficient = coefficient

    def __repr__(self):
        return f"{self.coefficient} * " + " * ".join([f"{var}^{exp}" for var, exp in self.variables.items()])

    def derivative(self, var: int):
        if var in self.variables and self.variables[var] > 0:
            new_coeff = self.coefficient * self.variables[var]
            new_vars = self.variables.copy()
            if new_vars[var] == 1:
                del new_vars[var]
            else:
                new_vars[var] -= 1
            return Monomial(new_vars, new_coeff)
        else:
            return None

class Polynomial:
    def __init__(self, monomials: List[Monomial]):
        self.monomials = monomials  # List of Monomial objects

    def __repr__(self):
        return " + ".join([mon.__repr__() for mon in self.monomials])

    def derivative(self, var: int) -> 'Polynomial':
        new_monomials = []
        for monomial in self.monomials:
            derived_monomial = monomial.derivative(var)
            if derived_monomial is not None and derived_monomial.coefficient != 0:
                new_monomials.append(derived_monomial)
        if not new_monomials:
            return Polynomial([Monomial({}, Fraction(0))])
        return Polynomial(new_monomials)"]

