["def exist(grid, word):
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c, i):
        if i == len(word):
            return True

        if r < 0 or r >= rows or c < 0 or c >= cols or word[i] != grid[r][c]:
            return False

        temp = grid[r][c]
        grid[r][c] = "#"

        found = (dfs(r+1, c, i+1) or
                 dfs(r-1, c, i+1) or
                 dfs(r, c+1, i+1) or
                 dfs(r, c-1, i+1))

        grid[r][c] = temp
        return found

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == word[0] and dfs(r, c, 0):
                return True
    return False"]

