["def can_arrange_seating(n, m, dislikes):
    from itertools import permutations

    # Create the adjacency matrix for dislikes
    adj_matrix = [[0]*n for _ in range(n)]
    for a, b in dislikes:
        adj_matrix[a-1][b-1] = 1
        adj_matrix[b-1][a-1] = 1

    def is_valid(arrangement):
        for i in range(n):
            if adj_matrix[arrangement[i]-1][arrangement[(i+1)%n]-1] == 1:
                return False
        return True

    for arrangement in permutations(range(1, n+1)):
