            return "YES"

    return "NO""]

["def edit_distance(word_a: str, word_b: str) -> int:
    m = len(word_a)
    n = len(word_b)

    # Create a table to store results of sub-problems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j    # If word_a is empty, insert all chars of word_b
            elif j == 0:
                dp[i][j] = i    # If word_b is empty, remove all chars of word_a
            elif word_a[i-1] == word_b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],       # Remove
                                   dp[i][j-1],       # Insert
                                   dp[i-1][j-1])     # Replace

    return dp[m][n]"]

