["from collections import ChainMap, defaultdict, Counter, OrderedDict

def parse_logs(logs):
    log_dict = defaultdict(lambda: defaultdict(list))

    for log in logs:
        timestamp, source, event = log.split('|')
        log_dict[source][timestamp].append(event)

    return ChainMap(log_dict)

def event_counter(chain_map):
    event_count = Counter()

    for source, timestamps in chain_map.items():
        for timestamp, events in timestamps.items():
            for event in events:
                event_count[event] += 1

    return event_count

def ordered_events(counter):
    return OrderedDict(counter.most_common())

def display_summary(log_data, sorted_events):
    for source, timestamps in log_data.items():
        print(f"Source: {source}")
        for timestamp, events in sorted(timestamps.items()):
            for event in events:
                print(f"  {timestamp}: {event}")
    print("\nEvent Summary:")
    for event, count in sorted_events.items():
        print(f"  {event}: {count}")"]

