["import shutil
import os
from fnmatch import fnmatch

def sync_and_archive_directory(src_dir, dst_dir, archive_name, ignore_patterns_list=None):
    if not os.path.exists(src_dir):
        raise ValueError(f"Source directory {src_dir} does not exist.")

    if not os.path.exists(dst_dir):
        os.makedirs(dst_dir, exist_ok=True)

    def ignore_patterns(path, names):
        if ignore_patterns_list is None:
            return []
        ignored = []
        for pattern in ignore_patterns_list:
            ignored.extend([name for name in names if fnmatch(name, pattern)])
        return set(ignored)

    # Synchronize source to destination
    for root, dirs, files in os.walk(src_dir, topdown=True):
        rel_path = os.path.relpath(root, src_dir)
        dest_path = os.path.join(dst_dir, rel_path)

        if not os.path.exists(dest_path):
            os.makedirs(dest_path, exist_ok=True)

        for name in files:
            if not ignore_patterns_list or not any(fnmatch(name, pattern) for pattern in ignore_patterns_list):
                src_file = os.path.join(root, name)
                dst_file = os.path.join(dest_path, name)
                shutil.copy2(src_file, dst_file)

    # Archive the destination directory
    shutil.make_archive(archive_name, 'gztar', dst_dir)"]

["class AncientWells:
    def __init__(self, n):
        self.n = n
        self.tree = [[] for _ in range(n + 1)]
        self.water_generators = [False] * (n + 1)
        self.marked_count = 0

    def add_pipe(self, a, b):
        self.tree[a].append(b)
        self.tree[b].append(a)

    def mark_as_water_generator(self, well):
        if not self.water_generators[well]:
            self.water_generators[well] = True
            self.marked_count += 1

    def count_water_generators(self):
        return self.marked_count

def solve(n, pipes, operations):
    wells = AncientWells(n)

    for a, b in pipes:
        wells.add_pipe(a, b)

    result = []
    for c, v in operations:
        if c == 1:
            wells.mark_as_water_generator(v)
        elif c == 3:
            result.append(wells.count_water_generators())

    return result"]

