["def three_sum_zero(arr):
    """
    Function to find all unique triplets in the array which gives the sum of zero.
    """
    arr.sort()
    result = []
    for i in range(len(arr)-2):
        if i > 0 and arr[i] == arr[i-1]:
            continue
        left, right = i+1, len(arr)-1
        while left < right:
            s = arr[i] + arr[left] + arr[right]
            if s == 0:
                result.append([arr[i], arr[left], arr[right]])
                while left < right and arr[left] == arr[left+1]:
                    left += 1
                while left < right and arr[right] == arr[right-1]:
                    right -= 1
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    return result

def find_unique_triplets(test_cases):
    """
    Function to handle multiple test cases and find unique triplets that sum to zero for each case.
    """
    results = []
    for arr in test_cases:
        results.append(three_sum_zero(arr))
    return results"]

