["def bubble_sort(arr, simulation=False):
    """
    Sorts an array of integers in ascending order using the Bubble Sort algorithm.
    """
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
                if simulation:
                    print(f'Iteration {i + 1}.{j + 1}:', arr)
        if not swapped:
            break
    return arr"]

