["class Graph:
    def __init__(self, vertex_count: int):
        self.vertex_count = vertex_count
        self.graph = [[] for _ in range(vertex_count)]

    def add_edge(self, source: int, target: int):
        self.graph[source].append(target)

    def _dfs(self, v, visited, graph):
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                self._dfs(neighbor, visited, graph)

    def _get_transpose(self):
        transpose_graph = [[] for _ in range(self.vertex_count)]
        for v in range(self.vertex_count):
            for neighbor in self.graph[v]:
                transpose_graph[neighbor].append(v)
        return transpose_graph

    def is_strongly_connected(self) -> bool:
        visited = [False] * self.vertex_count

        # Step 1: Perform DFS from the first vertex
        self._dfs(0, visited, self.graph)

        # If any vertex is not visited, return False
        if any(not flag for flag in visited):
            return False

        # Step 2: Create the transpose of the graph
        transpose_graph = self._get_transpose()

        # Reset visited array
        visited = [False] * self.vertex_count

        # Step 3: Perform DFS from the same vertex on the transpose graph
        self._dfs(0, visited, transpose_graph)

        # If any vertex is not visited again, return False
        if any(not flag for flag in visited):
            return False

        return True"]

["import numpy as np
from typing import List, Dict
from sklearn.metrics import pairwise_distances
from sklearn.metrics.pairwise import pairwise_kernels

def compute_metrics(X: np.ndarray, Y: np.ndarray, distance_metrics: List[str], kernel_functions: List[str]) -> Dict:
    results = {
        "distances": {},
        "kernels": {}
    }

    for metric in distance_metrics:
        try:
            distances = pairwise_distances(X, Y, metric=metric)
            results["distances"][metric] = distances
        except ValueError as e:
            raise ValueError(f"Distance metric '{metric}' is not supported. Error: {e}")

    for kernel in kernel_functions:
        try:
            kernels = pairwise_kernels(X, Y, metric=kernel)
            results["kernels"][kernel] = kernels
        except ValueError as e:
            raise ValueError(f"Kernel function '{kernel}' is not supported. Error: {e}")

    return results"]

