["import itertools
import math

def find_shortest_route(points):
    """
    Returns the shortest route to visit all points and return to the starting point.

    Args:
    points (list of tuples): A list where each tuple represents the coordinates (x, y).

    Returns:
    list of tuples: The list of points in the order they should be visited to minimize the total distance.
    """
    if not (2 <= len(points) <= 10):
        raise ValueError("The number of points must be between 2 and 10 inclusive.")

    for point in points:
        if not (isinstance(point, tuple) and len(point) == 2 and all(isinstance(coord, (int, float)) for coord in point)):
            raise ValueError("Each point must be a tuple of two float values.")

    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def total_distance(route):
        return sum(distance(route[i], route[i+1]) for i in range(len(route) - 1)) + distance(route[-1], route[0])

    shortest_route = None
    min_distance = float('inf')

    for perm in itertools.permutations(points[1:]):
        current_route = [points[0]] + list(perm)
        current_distance = total_distance(current_route)
        if current_distance < min_distance:
            shortest_route = current_route
            min_distance = current_distance

    return shortest_route + [points[0]]"]

