["from typing import List

def wiggle_sort(nums: List[int]) -> None:
    """
    Reorders the list nums in-place such that nums[0] < nums[1] > nums[2] < nums[3]...
    """
    for i in range(len(nums) - 1):
        if i % 2 == 0:
            # If index is even, nums[i] should be less than nums[i+1]
            if nums[i] > nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
        else:
            # If index is odd, nums[i] should be greater than nums[i+1]
            if nums[i] < nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]"]

["import asyncio

class FactorialEvent:
    def __init__(self):
        self.subscribers = []

    def register(self, function):
        self.subscribers.append(function)

    async def notify(self, n, result):
        for subscriber in self.subscribers:
            await subscriber(n, result)

class FactorialCalculator:
    def __init__(self):
        self.factorial_event = FactorialEvent()
        self.factorial_event.register(self.print_result)

    async def calculate_factorial(self, n):
        result = 1
        for i in range(2, n + 1):
            result *= i
            await asyncio.sleep(0)  # Event-driven context switch
        await self.factorial_event.notify(n, result)
        return result

    async def print_result(self, n, result):
        print(f"The factorial of {n} is {result}")

async def main(n):
    calculator = FactorialCalculator()
    return await calculator.calculate_factorial(n)

# Main function to run the coroutine
def factorial(n):
    return asyncio.run(main(n))"]

