["def max_sum_sequence(T, cases):
    def max_sequence_sum(sequence):
        n = len(sequence)
        if n == 0:
            return 0
        if n == 1:
            return max(0, sequence[0])

        include = 0
        exclude = 0

        for i in range(n):
            # Current max excluding i
            new_exclude = max(include, exclude)

            # Current max including i
            include = exclude + sequence[i]
            exclude = new_exclude

        return max(include, exclude)

    results = []
    for t in range(T):
        n = cases[t][0]
        sequence = cases[t][1]
        results.append(max_sequence_sum(sequence))

    return results"]

["def largest_unique_submatrix_area(matrix):
    n = len(matrix)
    m = len(matrix[0])

    def is_unique(submatrix):
        seen = set()
        for row in submatrix:
            for val in row:
                if val in seen:
                    return False
                seen.add(val)
        return True

    max_area = 0

    for i in range(n):
        for j in range(m):
            for k in range(i, n):
                for l in range(j, m):
                    submatrix = [matrix[row][j:l+1] for row in range(i, k+1)]
                    if is_unique(submatrix):
                        area = (k - i + 1) * (l - j + 1)
                        max_area = max(max_area, area)

    return max_area

def solution(t, test_cases):
    results = []
    for case in test_cases:
        n, m, matrix = case
        max_area = largest_unique_submatrix_area(matrix)
        results.append(max_area)
    return results"]

["from collections import deque

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def averageValue(root):
    if not root:
        return []

    result = []
    queue = deque([root])

    while queue:
        level_length = len(queue)
        level_sum = 0

        for _ in range(level_length):
            node = queue.popleft()
            level_sum += node.val

            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

        result.append(level_sum // level_length)

    return result"]

