def find_longest_concatenated_word(words: List[str]) -> str:
    def can_form(word, words_set):
        if word in memo:
            return memo[word]

        n = len(word)
        for i in range(1, n):
            prefix = word[:i]
            suffix = word[i:]
            if prefix in words_set:
                if suffix in words_set or can_form(suffix, words_set):
                    memo[word] = True
                    return True

        memo[word] = False
        return False

    words_set = set(words)
    memo = {}
    longest = ""

    for word in words:
        words_set.remove(word)
        if can_form(word, words_set):
            if len(word) > len(longest):
                longest = word
        words_set.add(word)

    return longest"]

