def build_tree(n, edges):
    nodes = [TreeNode(i) for i in range(n + 1)]
    for u, v in edges:
        nodes[u].children.append(nodes[v])
        nodes[v].children.append(nodes[u])
    return nodes

def calculate_subtree_sizes(node, parent):
    count = 1
    for child in node.children:
        if child != parent:
            count += calculate_subtree_sizes(child, node)
    node.subtree_size = count
    return count

def subtree_sizes(n, edges, m, queries):
    nodes = build_tree(n, edges)
    root = nodes[1]
    calculate_subtree_sizes(root, None)

    results = [nodes[query].subtree_size for query in queries]
    return results"]

