["def is_word_in_grid(grid, word):
    rows = len(grid)
    cols = len(grid[0])

    def dfs(x, y, word):
        if not word:
            return True
        if x < 0 or x >= rows or y < 0 or y >= cols or grid[x][y] != word[0]:
            return False

        temp = grid[x][y]
        grid[x][y] = ''
        found = (dfs(x+1, y, word[1:]) or dfs(x-1, y, word[1:]) or
                 dfs(x, y+1, word[1:]) or dfs(x, y-1, word[1:]))
        grid[x][y] = temp  # restore the original value
        return found

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == word[0] and dfs(i, j, word):
                return True
    return False

def find_words_in_grid(grid, words):
    return [is_word_in_grid(grid, word) for word in words]"]

["def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence in the given array.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

