import random
import json

def get_random_wikipedia_page():
    """
    Fetches a random page from Wikipedia, ensures it is not a disambiguation page,
    and gracefully handles errors.
    """
    try:
        response = requests.get('https://en.wikipedia.org/api/rest_v1/page/random/summary', timeout=10)
        response.raise_for_status()  # Raises an HTTPError for bad responses

        data = response.json()

        if 'title' in data and 'extract' in data and 'content_urls' in data:
            # Avoid disambiguation pages
            if 'Disambiguation' not in data['description']:
                return data
            else:
                return get_random_wikipedia_page()  # Retry if it's a disambiguation page
        else:
            raise ValueError('Invalid data received from Wikipedia')

    except (requests.exceptions.RequestException, ValueError) as e:
        return {"error": str(e)}

# Example of using the function
if __name__ == "__main__":
    page = get_random_wikipedia_page()
    print(json.dumps(page, indent=2))"]

