["from decimal import Decimal, getcontext

def calculate_fraction(operation: str, fraction1: str, fraction2: str, precision: int) -> str:
    getcontext().prec = precision + 5  # Set precision slightly higher to handle intermediate steps

    def parse_fraction(fraction):
        numerator, denominator = map(int, fraction.split('/'))
        return Decimal(numerator) / Decimal(denominator)

    try:
        frac1 = parse_fraction(fraction1)
        frac2 = parse_fraction(fraction2)
    except ZeroDivisionError:
        return "Error: Division by zero."
    except Exception:
        return "Error: Invalid input."

    result = None
    try:
        if operation == "add":
            result = frac1 + frac2
        elif operation == "subtract":
            result = frac1 - frac2
        elif operation == "multiply":
            result = frac1 * frac2
        elif operation == "divide":
            result = frac1 / frac2
        else:
            return "Error: Unknown operation."
    except ZeroDivisionError:
        return "Error: Division by zero."

    result = result.quantize(Decimal('1.' + '0' * precision))
    return str(result)"]

