["class ResizableHashTable:
    MIN_SIZE = 8

    def __init__(self):
        self.table = [None] * self.MIN_SIZE
        self.count = 0

    def _hash(self, key):
        return key % len(self.table)

    def _load_factor(self):
        return self.count / len(self.table)

    def _resize(self):
        old_table = self.table
        new_size = len(self.table) * 2
        self.table = [None] * new_size
        self.count = 0

        for entry in old_table:
            if entry is not None:
                key, value = entry
                self.put(key, value)

    def put(self, key, value):
        if self._load_factor() > 2/3:
            self._resize()

        index = self._hash(key)
        while self.table[index] is not None and self.table[index][0] != key:
            index = (index + 1) % len(self.table)

        if self.table[index] is None:
            self.count += 1

        self.table[index] = (key, value)

    def get(self, key):
        index = self._hash(key)
        while self.table[index] is not None:
            k, v = self.table[index]
            if k == key:
                return v
            index = (index + 1) % len(self.table)
        return None

    def del_(self, key):
        index = self._hash(key)
        while self.table[index] is not None:
            k, _ = self.table[index]
            if k == key:
                self.table[index] = None
                self.count -= 1
                next_index = (index + 1) % len(self.table)
                while self.table[next_index] is not None:
                    move_key, move_value = self.table[next_index]
                    self.table[next_index] = None
                    self.count -= 1
                    self.put(move_key, move_value)
                    next_index = (next_index + 1) % len(self.table)
                return
            index = (index + 1) % len(self.table)

    def __len__(self):
        return self.count"]

