["from typing import List

def enhanced_insertion_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []

    # An optimised insertion sort that also removes duplicates
    n = len(arr)
    sorted_list = []

    for i in range(n):
        # Skip inserting duplicates
        if arr[i] in sorted_list:
            continue

        inserted = False
        for j in range(len(sorted_list)):
            if arr[i] < sorted_list[j]:
                sorted_list.insert(j, arr[i])
                inserted = True
                break
        if not inserted:
            sorted_list.append(arr[i])

    return sorted_list"]

