["def generate_primes_up_to(n):
    """ Generate a list of primes up to n using the Sieve of Eratosthenes """
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n+1, start):
                sieve[multiple] = False
    return [num for num, is_prime in enumerate(sieve) if is_prime]

def prime_gaps(t, queries):
    MAX_R = max(query[1] for query in queries)
    primes_up_to_max_r = generate_primes_up_to(MAX_R)

    results = []
    for L, R in queries:
        primes_in_range = [p for p in primes_up_to_max_r if L <= p <= R]
        if len(primes_in_range) < 2:
            results.append(-1)
        else:
            max_gap = max(primes_in_range[i+1] - primes_in_range[i] for i in range(len(primes_in_range) - 1))
            results.append(max_gap)
    return results"]

