["def largest_prime_factor(n):
    if n <= 1:
        return 1
    max_prime = -1
    while n % 2 == 0:
        max_prime = 2
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            max_prime = i
            n //= i
    if n > 2:
        max_prime = n
    return max_prime

def largestPrimeFactors(numbers):
    return [largest_prime_factor(num) for num in numbers]"]

