    def __init__(self, size=64):
        self.size = size
        self.bits = [0] * size

    def GetBit(self, index):
        if 0 <= index < self.size:
            return self.bits[index]
        else:
            raise IndexError("Index out of bounds")

    def SetBit(self, index, value):
        if 0 <= index < self.size:
            self.bits[index] = 1 if value else 0
        else:
            raise IndexError("Index out of bounds")

def GetBitRange(bitvector, start, end):
    """
    Returns the bit values in the range [start, end) (end exclusive).
    """
    if start < 0 or end > bitvector.size or start >= end:
        raise IndexError("Invalid range")
    return bitvector.bits[start:end]

def SetBitRange(bitvector, start, end, values):
    """
    Sets the bit values in the range [start, end) (end exclusive) to 
    the given values list.
    """
    if start < 0 or end > bitvector.size or start >= end or (end - start) != len(values):
        raise IndexError("Invalid range or values length mismatch")
    for i in range(start, end):
        bitvector.SetBit(i, values[i - start])"]

