["class DynamicArray:
    def __init__(self, initial_capacity):
        self.capacity_value = initial_capacity
        self.size_value = 0
        self.array = [None] * self.capacity_value

    def add(self, element):
        if self.size_value >= self.capacity_value:
            self._resize()
        self.array[self.size_value] = element
        self.size_value += 1
        return self

    def size(self):
        return self.size_value

    def capacity(self):
        return self.capacity_value

    def get(self, index):
        if index < 0 or index >= self.size_value:
            raise Exception("INDEX OUT OF BOUNDS")
        return self.array[index]

    def set(self, index, element):
        if index < 0 or index >= self.size_value:
            raise Exception("INDEX OUT OF BOUNDS")
        self.array[index] = element
        return True

    def _resize(self):
        self.capacity_value *= 2
        new_array = [None] * self.capacity_value
        for i in range(self.size_value):
            new_array[i] = self.array[i]
        self.array = new_array"]

["import os
import pty
import select

def execute_command(command: str) -> int:
    def read(fd):
        output = b""
        while True:
            r, _, _ = select.select([fd], [], [], 0.1)
            if fd in r:
                try:
                    data = os.read(fd, 1024)
                    if not data:
                        break
                    output += data
                except OSError:
                    break
        return output.decode()

    pid, fd = pty.fork()

    if pid == 0:  # Child process
        os.execlp("/bin/sh", "sh", "-c", command)
    else:  # Parent process
        output = read(fd)
        print(output)
        _, status = os.waitpid(pid, 0)
        return os.WEXITSTATUS(status)"]

