class TreeNode:
    def __init__(self, x: int):
        self.val = x
        self.left = None
        self.right = None

def create_tree_node(data: List[Tuple[int, Optional[int], Optional[int]]]) -> Optional[TreeNode]:
    if not data:
        return None

    nodes = {val: TreeNode(val) for val, _, _ in data}

    for val, left, right in data:
        if left is not None:
            nodes[val].left = nodes[left]
        if right is not None:
            nodes[val].right = nodes[right]

    return nodes[data[0][0]]

def is_valid_bst(root: Optional[TreeNode]) -> bool:
    def helper(node: Optional[TreeNode], low: float, high: float) -> bool:
        if not node:
            return True
        if not (low < node.val < high):
            return False
        return helper(node.left, low, node.val) and helper(node.right, node.val, high)

    return helper(root, float('-inf'), float('inf'))"]

