["def find_longest_path(graph, start, end):
    def dfs(current_node, end, visited, path):
        visited.add(current_node)
        path.append(current_node)

        if current_node == end:
            # We have reached the destination
            if len(path) > len(dfs.longest_path):
                dfs.longest_path = list(path)
        else:
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    dfs(neighbor, end, visited, path)

        path.pop()
        visited.remove(current_node)

    dfs.longest_path = []

    visited = set()
    path = []

    dfs(start, end, visited, path)
    return dfs.longest_path"]

