["def process_byte_tasks(tasks: list) -> bytes:
    result = b''

    for task in tasks:
        operation, arg1, arg2 = task

        if operation == 'create':
            result = bytes(arg1, 'utf-8')
        elif operation == 'concat':
            result += bytes(arg1, 'utf-8')
        elif operation == 'format':
            # Convert the format and argument to the respective types
            if '%d' in arg1:
                formatted_str = arg1 % int(arg2)
            elif '%s' in arg1:
                formatted_str = arg1 % arg2
            else:
                raise ValueError(f"Unsupported format specifier in {arg1}")
            result += bytes(formatted_str, 'utf-8')
        else:
            raise ValueError(f"Unknown operation {operation}")

    return result"]

