["def zigzag_permutation(permutation):
    """
    Transforms the given permutation into a zigzag sequence.
    """
    n = len(permutation)
    result = permutation[:]
    for i in range(1, n, 2):
        if i < n - 1:
            if result[i] < result[i - 1]:
                result[i], result[i - 1] = result[i - 1], result[i]
            if result[i] < result[i + 1]:
                result[i], result[i + 1] = result[i + 1], result[i]
        else:
            if result[i] < result[i - 1]:
                result[i], result[i - 1] = result[i - 1], result[i]
    return result

def zigzag_sequences(test_cases):
    """
    For each test case, returns the zigzag sequence of the permutation.
    """
    results = []
    for N, perm in test_cases:
        results.append(zigzag_permutation(perm))
    return results"]

