class TelnetClient:
    def __init__(self, host: str, port: int = 23, timeout: int = 10):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.connection = None

        try:
            self.connection = telnetlib.Telnet(self.host, self.port, self.timeout)
        except Exception as e:
            raise ConnectionError(f"Failed to connect to {self.host}:{self.port} - {str(e)}")

    def execute_commands(self, commands: list) -> str:
        if not self.connection:
            raise ConnectionError("No active connection to a Telnet server.")

        responses = []
        try:
            for command in commands:
                self.connection.write(command.encode('ascii') + b"\n")
                time.sleep(1)  # wait to get the response
                response = self.connection.read_very_eager().decode('ascii')
                responses.append(response)
        except EOFError:
            raise ConnectionError("Connection closed unexpectedly by the Telnet server.")

        return "\n".join(responses)

