["def find_min_courses(courseList, prerequisites):
    from collections import defaultdict, deque

    # Map to store each course's prerequisites
    pre_map = defaultdict(set)
    # Map to store each course that is a prerequisite for other courses
    post_map = defaultdict(set)

    for a, b in prerequisites:
        pre_map[a].add(b)
        post_map[b].add(a)

    # Compute the in-degree for each course
    in_degree = {course: 0 for course in courseList}
    for course in pre_map:
        for pre in pre_map[course]:
            in_degree[course] += 1

    # Initialize a queue with courses that have no prerequisites
    queue = deque([course for course in courseList if in_degree[course] == 0])
    completed_courses = 0

    while queue:
        course = queue.popleft()
        completed_courses += 1
        # For each course that the current course is a prerequisite for
        for dependent_course in post_map[course]:
            in_degree[dependent_course] -= 1
            if in_degree[dependent_course] == 0:
                queue.append(dependent_course)

    # Check if all courses are processed
    if completed_courses == len(courseList):
        return completed_courses
    else:
        return -1"]

