class PrimeNumbers(Iterable):
    def __init__(self, n):
        self.n = n

    def __iter__(self):
        if self.n < 2:
            return

        sieve = [True] * (self.n + 1)
        sieve[0] = sieve[1] = False

        for start in range(2, int(self.n ** 0.5) + 1):
            if sieve[start]:
