["class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (2 * self.n)
        for i in range(self.n):
            self.tree[self.n + i] = data[i]
        for i in range(self.n - 1, 0, -1):
            self.tree[i] = max(self.tree[2 * i], self.tree[2 * i + 1])

    def update(self, pos, value):
        pos += self.n
        self.tree[pos] = value
        while pos > 1:
            pos //= 2
            self.tree[pos] = max(self.tree[2 * pos], self.tree[2 * pos + 1])

    def query(self, left, right):
        left += self.n
        right += self.n + 1
        result = float('-inf')
        while left < right:
            if left % 2 == 1:
                result = max(result, self.tree[left])
                left += 1
            if right % 2 == 1:
                right -= 1
                result = max(result, self.tree[right])
            left //= 2
            right //= 2
        return result

def process_operations(n, q, elements, operations):
    seg_tree = SegmentTree(elements)
    results = []

    for operation in operations:
        if operation[0] == "U":
            _, i, v = operation
            seg_tree.update(int(i) - 1, int(v))
        elif operation[0] == "Q":
            _, l, r = operation
            results.append(seg_tree.query(int(l) - 1, int(r) - 1))

    return results"]

["def longest_bitonic_subarray(nums):
    n = len(nums)
    if n == 0:
        return 0

    # Arrays to store the longest increasing and decreasing subarray lengths
    inc = [1] * n
    dec = [1] * n

    # Fill increasing subarray length array
    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            inc[i] = inc[i - 1] + 1

    # Fill decreasing subarray length array
    for j in range(n - 2, -1, -1):
        if nums[j] > nums[j + 1]:
            dec[j] = dec[j + 1] + 1

    # Find the length of the maximum length bitonic subarray
    max_len = 0
    for i in range(n):
        max_len = max(max_len, inc[i] + dec[i] - 1)

    return max_len"]

