["def is_prime(n):
    """ Helper function to check if a number is prime """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_palindrome(n):
    """ Helper function to check if a number is a palindrome """
    return str(n) == str(n)[::-1]

def prime_numbers(start, end, palindrome):
    """
    Generates a list of prime numbers within a given range. If palindrome
    is True, only returns the prime numbers that are palindromes.
    """
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            if palindrome:
                if is_palindrome(num):
                    primes.append(num)
            else:
                primes.append(num)
    return primes"]

