["def can_place_word_horizontally(grid, word, row, col):
    if col + len(word) > len(grid[0]):
        return False
    for i in range(len(word)):
        if grid[row][col + i] == '#' or (grid[row][col + i] != '.' and grid[row][col + i] != word[i]):
            return False
    return True

def can_place_word_vertically(grid, word, row, col):
    if row + len(word) > len(grid):
        return False
    for i in range(len(word)):
        if grid[row + i][col] == '#' or (grid[row + i][col] != '.' and grid[row + i][col] != word[i]):
            return False
    return True

def place_word_horizontally(grid, word, row, col):
    new_grid = [list(row) for row in grid]
    for i in range(len(word)):
        new_grid[row][col + i] = word[i]
    return ["".join(row) for row in new_grid]

def place_word_vertically(grid, word, row, col):
    new_grid = [list(row) for row in grid]
    for i in range(len(word)):
        new_grid[row + i][col] = word[i]
    return ["".join(row) for row in new_grid]

def solve_crossword(n, m, grid, words):
    if not words:
        return 0

    word = words[0]
    for row in range(n):
        for col in range(m):
            if can_place_word_horizontally(grid, word, row, col):
                new_grid = place_word_horizontally(grid, word, row, col)
                result = solve_crossword(n, m, new_grid, words[1:])
                if result != -1:
                    return 1 + result

            if can_place_word_vertically(grid, word, row, col):
                new_grid = place_word_vertically(grid, word, row, col)
                result = solve_crossword(n, m, new_grid, words[1:])
                if result != -1:
                    return 1 + result

    return -1"]

["from collections import deque

class TreeNode:
    def __init__(self, value=0, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def spiralOrder(root):
    if not root:
        return []

    result = []
    current_level = deque([root])
    left_to_right = True

    while current_level:
        level_size = len(current_level)
        level_nodes = []

        for _ in range(level_size):
            if left_to_right:
                node = current_level.popleft()
                level_nodes.append(node.value)
                if node.left:
                    current_level.append(node.left)
                if node.right:
                    current_level.append(node.right)
            else:
                node = current_level.pop()
                level_nodes.append(node.value)
                if node.right:
                    current_level.appendleft(node.right)
                if node.left:
                    current_level.appendleft(node.left)

        result.extend(level_nodes)
        left_to_right = not left_to_right

    return result"]

["import math


def find_parent(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find_parent(parent, parent[i])
        return parent[i]


def union(parent, rank, x, y):
    root_x = find_parent(parent, x)
    root_y = find_parent(parent, y)

    if root_x != root_y:
        if rank[root_x] > rank[root_y]:
            parent[root_y] = root_x
        elif rank[root_x] < rank[root_y]:
            parent[root_x] = root_y
        else:
            parent[root_y] = root_x
            rank[root_x] += 1


def compute_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)


def minimum_spanning_tree_kruskal(n, coordinates):
    edges = []

    for i in range(n):
        for j in range(i + 1, n):
            dist = compute_distance(coordinates[i][0], coordinates[i][1], coordinates[j][0], coordinates[j][1])
            edges.append((dist, i, j))

    edges.sort()

    parent = [i for i in range(n)]
    rank = [0] * n

    mst_weight = 0
    max_weight_edge_in_mst = 0

    for edge in edges:
        dist, u, v = edge
        if find_parent(parent, u) != find_parent(parent, v):
            union(parent, rank, u, v)
            mst_weight += dist
            max_weight_edge_in_mst = max(max_weight_edge_in_mst, dist)

    return max_weight_edge_in_mst


def min_max_distance_to_connect_all_nodes(coords):
    n = len(coords)
    return minimum_spanning_tree_kruskal(n, coords)"]

["def num_decodings(s):
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = int(s[i - 1:i])
        two_digits = int(s[i - 2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i - 1]

        if 10 <= two_digits <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

def decode_messages(t, cases):
    results = []
    for case in cases:
        results.append(num_decodings(case))
    return results"]

