["import urllib.parse

def flatten_dict(d, parent_key=''):
    items = []
    for k, v in sorted(d.items()):
        new_key = f"{parent_key}_{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key).items())
        elif isinstance(v, list):
            for i, item in enumerate(v):
                items.extend(flatten_dict({f"{new_key}_{i}": item}).items())
        else:
            items.append((new_key, v))
    return dict(items)

def dict_to_query_string(d):
    flattened_dict = flatten_dict(d)
    encoded_items = {urllib.parse.quote_plus(str(k)): urllib.parse.quote_plus(str(v)) for k, v in flattened_dict.items()}
    return '&'.join(f"{k}={v}" for k, v in sorted(encoded_items.items()))"]

