def longest_subarray(arr: List[int]) -> List[int]:
    if len(arr) == 1:
        return arr

    max_len = 1
    current_len = 1
    max_start_idx = 0
    current_start_idx = 0

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i - 1]) == 1:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                max_start_idx = current_start_idx
            current_len = 1
            current_start_idx = i

    if current_len > max_len:
        max_len = current_len
        max_start_idx = current_start_idx

