["def check_valid_grid(grid):
    rows, cols = len(grid), len(grid[0])

    # Check rows and columns
    for r in range(rows):
        row_letters = set()
        for c in range(cols):
            if grid[r][c] in row_letters:
                return r, c, grid[r][c]
            row_letters.add(grid[r][c])

    for c in range(cols):
        col_letters = set()
        for r in range(rows):
            if grid[r][c] in col_letters:
                return r, c, grid[r][c]
            col_letters.add(grid[r][c])

    # Check subgrids (3x4)
    subgrid_rows, subgrid_cols = 3, 4
    for start_r in range(0, rows, subgrid_rows):
        for start_c in range(0, cols, subgrid_cols):
            subgrid_letters = set()
            for r in range(start_r, min(start_r + subgrid_rows, rows)):
                for c in range(start_c, min(start_c + subgrid_cols, cols)):
                    if grid[r][c] in subgrid_letters:
                        return r, c, grid[r][c]
                    subgrid_letters.add(grid[r][c])

    return None

def validate_datasets(datasets):
    results = []
    for grid in datasets:
        error = check_valid_grid(grid)
        if error:
            r, c, letter = error
            grid[r][c] = '*' + letter
        results.append(grid)
    return results

def format_output(results):
