["def wrap_open_with_logging(path, mode):
    """
    Wraps the built-in open function to log each file open operation.
    """
    def log_open_operation(path, mode):
        with open('file_operations.log', 'a') as log_file:
            log_file.write(f"OPEN - {path}, mode: {mode}\n")

    file = open(path, mode)
    log_open_operation(path, mode)

    return FileLogger(file, path)


class FileLogger:
    def __init__(self, file, path):
        self.file = file
        self.path = path

    def read(self, size=-1):
        data = self.file.read(size)
        self._log_read_operation(size, len(data))
        return data

    def write(self, data):
        num_bytes_written = self.file.write(data)
        self._log_write_operation(len(data))
        return num_bytes_written

    def close(self):
        self.file.close()

    def _log_read_operation(self, requested_size, read_size):
        with open('file_operations.log', 'a') as log_file:
            log_file.write(f"READ - {self.path}, requested bytes: {requested_size}, read bytes: {read_size}\n")

    def _log_write_operation(self, size):
        with open('file_operations.log', 'a') as log_file:
            log_file.write(f"WRITE - {self.path}, bytes: {size}\n")

    def __getattr__(self, attr):
        return getattr(self.file, attr)"]

["def min_path_cost(grid):
    if grid[0][0] == -1 or grid[-1][-1] == -1:
        return -1

    m, n = len(grid), len(grid[0])
    dp = [[float('inf')] * n for _ in range(m)]

    dp[0][0] = grid[0][0]

    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:
                continue
            if i > 0 and grid[i-1][j] != -1:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0 and grid[i][j-1] != -1:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[-1][-1] if dp[-1][-1] != float('inf') else -1"]

