def one_sparse(array: List[Tuple[int, str]]) -> Optional[int]:
    balance = 0
    unique_counts = {}

    for amount, sign in array:
        if sign == '+':
            balance += amount
            if amount not in unique_counts:
                unique_counts[amount] = 0
            unique_counts[amount] += 1
        elif sign == '-':
            balance -= amount
            if amount not in unique_counts:
                unique_counts[amount] = 0
            unique_counts[amount] -= 1

    # Find the unique non-zero count element
    unique_non_zero_count = None
    for amount, count in unique_counts.items():
        if count != 0:
            if unique_non_zero_count is not None:
                return None
            unique_non_zero_count = amount

    return unique_non_zero_count"]

