def multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    if not A or not B or len(A[0]) != len(B):
        raise ValueError("Invalid input matrices dimensions")

    m, n, p = len(A), len(A[0]), len(B[0])

    # Initialize the result matrix with zeros
    result = [[0] * p for _ in range(m)]

    for i in range(m):
        for k in range(n):
            if A[i][k] != 0:
                for j in range(p):
                    result[i][j] += A[i][k] * B[k][j]

    return result"]

["def atm_withdrawal(balance, amount, prefers_large):
    """
    Simulates an ATM withdrawal process.

    Parameters:
    balance (int): Current account balance.
    amount (int): Amount the user wishes to withdraw.
    prefers_large (bool): Preference for large denominations (True) or small denominations (False).

    Returns:
    tuple: (boolean indicating whether withdrawal is possible, dict of denominations given out)
    """
    if amount > balance:
        return False, {}

    large_denominations = [50, 20]
    small_denominations = [10, 5, 1]

    if prefers_large:
        denominations = large_denominations
    else:
        denominations = small_denominations

    withdrawal = {}
    remaining_amount = amount

    for denom in denominations:
        if remaining_amount >= denom:
            count = remaining_amount // denom
            withdrawal[denom] = count
            remaining_amount -= denom * count

    if remaining_amount == 0:
        return True, withdrawal
    else:
        return False, {}"]

