["def min_weight_path_with_k_edges(n, m, k, edges, a, b):
    # Initialize dp table with infinities
    INF = float('inf')
    dp = [[[INF] * (k + 1) for _ in range(n + 1)] for _ in range(n + 1)]

    # Distance to reach any node from itself with 0 edges is 0
    for i in range(1, n + 1):
        dp[i][i][0] = 0

    # Conversion of edges to adjacency matrix for easier updates
    for u, v, w in edges:
        dp[u][v][1] = w

    # Update dp for paths with j edges
    for j in range(2, k + 1):
        for u in range(1, n + 1):
            for v in range(1, n + 1):
                for p in range(1, n + 1):
                    if dp[u][p][j - 1] != INF and dp[p][v][1] != INF:
                        dp[u][v][j] = min(dp[u][v][j], dp[u][p][j - 1] + dp[p][v][1])

    result = dp[a][b][k]
    return result if result != INF else -1"]

