["class NumArray:
    def __init__(self, nums):
        self.nums = nums
        self.n = len(nums)
        self.st = [0] * (4 * self.n)
        self.build(0, 0, self.n - 1)

    def build(self, node, start, end):
        if start == end:
            self.st[node] = self.nums[start]
        else:
            mid = (start + end) // 2
            left_child = 2 * node + 1
            right_child = 2 * node + 2
            self.build(left_child, start, mid)
            self.build(right_child, mid + 1, end)
            self.st[node] = min(self.st[left_child], self.st[right_child])

    def update(self, idx, value, node=0, start=0, end=None):
        if end is None:
            end = self.n - 1
        if start == end:
            self.nums[idx] = value
            self.st[node] = value
        else:
            mid = (start + end) // 2
            left_child = 2 * node + 1
            right_child = 2 * node + 2
            if start <= idx <= mid:
                self.update(idx, value, left_child, start, mid)
            else:
                self.update(idx, value, right_child, mid + 1, end)
            self.st[node] = min(self.st[left_child], self.st[right_child])

    def query(self, L, R, node=0, start=0, end=None):
        if end is None:
            end = self.n - 1
        if R < start or L > end:
            return float('inf')
        if L <= start and end <= R:
            return self.st[node]
        mid = (start + end) // 2
        left_child = 2 * node + 1
        right_child = 2 * node + 2
        left_query = self.query(L, R, left_child, start, mid)
        right_query = self.query(L, R, right_child, mid + 1, end)
        return min(left_query, right_query)


def perform_operations(N, Q, nums, operations):
    numArray = NumArray(nums)
    results = []
    for op in operations:
        if op[0] == 1:
            numArray.update(op[1], op[2])
        elif op[0] == 2:
            results.append(numArray.query(op[1], op[2]))
    return results"]

