["import itertools

def tsp(n, edges):
    # Initialize adjacency matrix with large values
    inf = float('inf')
    dist = [[inf] * n for _ in range(n)]

    # Fill the adjacency matrix with given edges
    for u, v, w in edges:
        dist[u-1][v-1] = w
        dist[v-1][u-1] = w

    # Use dynamic programming to find the shortest Hamiltonian cycle
    # dp[mask][i] will store the minimum cost to visit the subset represented by mask, ending at node i
    dp = [[inf] * n for _ in range(1 << n)]
    dp[1][0] = 0  # Starting point

    for mask in range(1 << n):
        for i in range(n):
            if mask & (1 << i):
                for j in range(n):
                    if mask & (1 << j) == 0:
                        new_mask = mask | (1 << j)
                        dp[new_mask][j] = min(dp[new_mask][j], dp[mask][i] + dist[i][j])

    # The answer will be the minimum cost to visit all nodes, ending at the start node (0)
    result = inf
    for i in range(1, n):
        result = min(result, dp[(1 << n) - 1][i] + dist[i][0])

    return result if result != inf else -1

def solve_tsp(test_cases):
    results = []
    for n, m, edges in test_cases:
        result = tsp(n, edges)
        results.append(result)
    return results"]

