import os
from http.server import HTTPServer, SimpleHTTPRequestHandler
import threading

def generate_html_docs(module_name, output_dir=None):
    """
    Generate HTML documentation for a given module and optionally save it to output_dir.
    """
    try:
        html_doc = pydoc.HTMLDoc().docroutine(__import__(module_name))
        if output_dir:
            with open(os.path.join(output_dir, f"{module_name}.html"), "w") as f:
                f.write(html_doc)
        return html_doc
    except Exception as e:
        print(f"Error generating documentation for {module_name}: {e}")
        return None

def start_http_server():
    """
    Start an HTTP server to serve the current directory.
    """
    server_address = ('', 0)  # Bind to an available port
    httpd = HTTPServer(server_address, SimpleHTTPRequestHandler)
    print(f"Serving at port {httpd.server_address[1]}")
    httpd.serve_forever()

def search_keyword_in_docs(modules, keyword):
    """
    Search for a keyword in the documentation of provided modules and print the results.
    """
    for module_name in modules:
        try:
            module = __import__(module_name)
            doc = pydoc.render_doc(module)
            if keyword.lower() in doc.lower():
                print(f"Keyword '{keyword}' found in {module_name}")
        except Exception as e:
            print(f"Error searching for keyword in {module_name}: {e}")

def generate_and_serve_docs(modules, output_dir=None, serve=False, keyword=None):
    loaded_modules = []
    if output_dir and not os.path.exists(output_dir):
