["def ternary_search_2d(matrix, target):
    """
    Performs a ternary search on a sorted 2D matrix.

    Args:
    matrix: List[List[int]], a 2D list where each row is sorted, and
            the first element of each row is sorted.
    target: int, the element to search for in the matrix.

    Returns:
    tuple: (row, col) of the target element if found, otherwise (-1, -1).
    """
    def ternary_search_row(row, left, right, target):
        if left <= right:
            divisor = (right - left) // 3
            mid1 = left + divisor
            mid2 = right - divisor

            if row[mid1] == target:
                return mid1
            if row[mid2] == target:
                return mid2

            if target < row[mid1]:
                return ternary_search_row(row, left, mid1 - 1, target)
            elif target > row[mid2]:
                return ternary_search_row(row, mid2 + 1, right, target)
            else:
                return ternary_search_row(row, mid1 + 1, mid2 - 1, target)

        return -1

    for row_index, row in enumerate(matrix):
        col_index = ternary_search_row(row, 0, len(row) - 1, target)
        if col_index != -1:
            return (row_index, col_index)

    return (-1, -1)"]

