    def __init__(self):
        self.methods = {}

    def add_method(self, func, instance):
        import types
        # Creating a method object by binding the function to the instance
        bound_method = types.MethodType(func, instance)
        # Storing the method in the dictionary with the function's name
        self.methods[func.__name__] = bound_method

    def call_method(self, method_name, *args):
        method = self.methods.get(method_name)
        if method is None:
            raise ValueError("Method not found")
        return method(*args)


def example_function(self, x, y):
    return x + y


