["def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def isEmirp(N):
    """
    Returns "YES" if N is an Emirp number, "NO" otherwise.
    """
    if not is_prime(N):
        return "NO"

    reversed_N = int(str(N)[::-1])

    if reversed_N != N and is_prime(reversed_N):
        return "YES"
    return "NO""]

