["def cycle_sort(arr):
    writes = 0

    # Traverse the array to find the cycles to rotate.
    for cycleStart in range(0, len(arr) - 1):
        item = arr[cycleStart]

        # Find the position where we put the element.
        pos = cycleStart
        for i in range(cycleStart + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position.
        if pos == cycleStart:
            continue

        # Otherwise, put the item to the right position.
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle.
        while pos != cycleStart:
            pos = cycleStart
            for i in range(cycleStart + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr"]

