class CompositeHandler(logging.Handler):
    """
    A logging handler that sends log records to a rotating file handler and a socket handler.
    """
    def __init__(self, filename, maxBytes, backupCount, host, port):
        super(CompositeHandler, self).__init__()
        self.file_handler = RotatingFileHandler(filename, maxBytes=maxBytes, backupCount=backupCount)
        self.socket_handler = SocketHandler(host, port)

    def emit(self, record):
        try:
            self.file_handler.emit(record)
        except Exception as e:
            self.handleError(record)

        try:
            self.socket_handler.emit(record)
        except Exception as e:
            self.handleError(record)"]

