["from typing import List

def compute_max_flow(adjacency_matrix: List[List[int]]) -> int:
    def dfs(source, sink, flow, visited):
        if source == sink:
            return flow
        visited[source] = True
        for i, capacity in enumerate(adjacency_matrix[source]):
            if not visited[i] and capacity > 0:
                new_flow = min(flow, capacity)
                result = dfs(i, sink, new_flow, visited)
                if result > 0:
                    adjacency_matrix[source][i] -= result
                    adjacency_matrix[i][source] += result
                    return result
        return 0

    n = len(adjacency_matrix)
    source, sink = 0, n - 1
    max_flow = 0

    while True:
        visited = [False] * n
        flow = dfs(source, sink, float('Inf'), visited)
        if flow == 0:
            break
        max_flow += flow

    return max_flow"]

