["def find_triplet(nums):
    """
    This function takes a list of integers and returns a triplet that sums to zero if such a triplet exists,
    otherwise it returns "NO".
    """
    nums.sort()
    n = len(nums)

    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i+1, n-1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == 0:
                return "YES", sorted([nums[i], nums[left], nums[right]])
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return "NO"

def print_triplet_result(n, nums):
    result = find_triplet(nums)
    if result == "NO":
        print(result)
    else:
        print(result[0])
        print(" ".join(map(str, result[1])))"]

