["import heapq

class MedianFinder:
    def __init__(self):
        # Initializes two heaps:
        # A max heap for the lower half and a min heap for the upper half
        self.max_heap = []  # These are negative values to simulate a max heap
        self.min_heap = []

    def addNum(self, num: int):
        # Adding to max heap (as negative to simulate a max heap)
        heapq.heappush(self.max_heap, -num)

        # Balancing step: Ensures that every element in max_heap is <= every element in min_heap
        if self.max_heap and self.min_heap and (-self.max_heap[0] > self.min_heap[0]):
            heapq.heappush(self.min_heap, -heapq.heappop(self.max_heap))

        # If the heaps are uneven, balance them
        if len(self.max_heap) > len(self.min_heap) + 1:
            heapq.heappush(self.min_heap, -heapq.heappop(self.max_heap))
