class SafeCounter:
    def __init__(self):
        self.counter = 0
        self.lock = _thread.allocate_lock()

    def increment(self):
        with self.lock:
            self.counter += 1

    def get_counter(self):
        with self.lock:
            return self.counter

def worker_thread(counter, increments):
    for _ in range(increments):
        counter.increment()

def main():
