["def max_area_of_agricultural_segment(grid):
    """
    Given a grid of 1s and 0s, calculates the area of the largest subgrid containing only 1s.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    max_area = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = (dp[i][j-1] + 1) if j > 0 else 1
                width = dp[i][j]

                for k in range(i, -1, -1):
                    width = min(width, dp[k][j])
                    if width == 0:
                        break
                    max_area = max(max_area, width * (i - k + 1))

    return max_area"]

