from collections import defaultdict, deque

def longest_special_path(n, vertex_values, edges):
    def bfs(start):
        queue = deque([(start, vertex_values[start - 1])])
        visited = {start}
        parent = [-1] * (n + 1)
        distance = [0] * (n + 1)

        while queue:
            node, current_gcd = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    new_gcd = gcd(current_gcd, vertex_values[neighbor - 1])
                    if new_gcd > 1:
                        visited.add(neighbor)
                        parent[neighbor] = node
                        distance[neighbor] = distance[node] + 1
