["from typing import List

def bitonic_sort(arr: List[int], reverse: bool = False) -> List[int]:
    """
    Sorts an array of integers using the Bitonic Sort algorithm.

    Parameters:
    arr (List[int]): A list of integers which has a length that is a power of two.
    reverse (bool): A boolean indicating whether to sort in descending order (default is ascending order if False).

    Returns:
    List[int]: The sorted list of integers. 
    """
    def bitonic_merge(arr, low, cnt, direction):
        if cnt > 1:
            k = cnt // 2
            for i in range(low, low + k):
                if (arr[i] > arr[i + k]) == direction:
                    arr[i], arr[i + k] = arr[i + k], arr[i]
            bitonic_merge(arr, low, k, direction)
            bitonic_merge(arr, low + k, k, direction)

    def bitonic_sort_recursive(arr, low, cnt, direction):
        if cnt > 1:
            k = cnt // 2
            bitonic_sort_recursive(arr, low, k, True)  # sort in ascending order
            bitonic_sort_recursive(arr, low + k, k, False)  # sort in descending order
            bitonic_merge(arr, low, cnt, direction)

    def is_power_of_two(x):
        return x and (x & (x - 1)) == 0

    if not is_power_of_two(len(arr)):
        raise ValueError("the size of input should be power of two")

    bitonic_sort_recursive(arr, 0, len(arr), not reverse)
    return arr"]

