["class MatrixMultiply:
    def __init__(self, matrix1, matrix2):
        self.matrix1 = matrix1
        self.matrix2 = matrix2

    def validate_dimensions(self):
        if not self.matrix1 or not self.matrix2:
            raise ValueError("One or both matrices are empty")
        if len(self.matrix1[0]) != len(self.matrix2):
            raise ValueError("Incompatible dimensions for matrix multiplication")

    def safe_multiplication(self, num1, num2):
        if num1 == 0 or num2 == 0:
            return 0
        result = num1 * num2
        # Safe guarding against floating-point overflow and underflow
        if result > 1e308:
            return float('inf')
        if result < -1e308:
            return float('-inf')
        return result

    def __matmul__(self, other):
        self.validate_dimensions()
        result = [[0] * len(self.matrix2[0]) for _ in range(len(self.matrix1))]
        for i in range(len(self.matrix1)):
            for j in range(len(self.matrix2[0])):
                for k in range(len(self.matrix2)):
                    result[i][j] += self.safe_multiplication(self.matrix1[i][k], self.matrix2[k][j])
        return result

# Example Usage:
