def find_second_largest(nums: List[int]) -> Optional[int]:
    """
    Find the second largest unique element in the array.
    If there is no such element, return None.
    """
    if len(nums) < 2:
        return None

    first_largest, second_largest = None, None

    for num in nums:
        if first_largest is None or num > first_largest:
            second_largest = first_largest
            first_largest = num
        elif num != first_largest and (second_largest is None or num > second_largest):
            second_largest = num

    return second_largest"]

