["class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class SpellingCorrector:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, query: str) -> bool:
        node = self.root
        for char in query:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def suggest(self, prefix: str) -> list:
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return self._collect_words(node, prefix)

    def _collect_words(self, node, prefix):
        words = []
        if node.is_end_of_word:
            words.append(prefix)
        for char, next_node in node.children.items():
            words.extend(self._collect_words(next_node, prefix + char))
        return sorted(words)"]

["def isMatch(S, P):
    m, n = len(S), len(P)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if P[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if P[j - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif P[j - 1] == '?' or S[i - 1] == P[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]

    return 1 if dp[m][n] else 0"]

["def find_largest_clique(n, friendships):
    def is_clique(clique):
        for i in range(len(clique)):
            for j in range(i+1, len(clique)):
                if (clique[i], clique[j]) not in edges and (clique[j], clique[i]) not in edges:
                    return False
        return True

    def backtrack(start, current_clique):
        nonlocal largest_clique
        if len(current_clique) > len(largest_clique):
            largest_clique = current_clique[:]

        for i in range(start, n):
            current_clique.append(i)
            if is_clique(current_clique):
                backtrack(i + 1, current_clique)
            current_clique.pop()

    edges = set(friendships)
    largest_clique = []
    backtrack(0, [])

    return largest_clique"]

