        Allows a user to borrow a book if it is available.
        """
        if title in self.books and title not in self.borrowed_books:
            self.borrowed_books[title] = user
            return f"{user} has borrowed '{title}'."
        elif title in self.borrowed_books:
            return f"'{title}' is already borrowed by {self.borrowed_books[title]}."
        else:
            return f"'{title}' is not available in the library."

    def return_book(self, title, user):
        """
        Allows a user to return a borrowed book.
        """
        if title in self.borrowed_books and self.borrowed_books[title] == user:
            del self.borrowed_books[title]
            return f"{user} has returned '{title}'."
        else:
            return f"{user} cannot return '{title}' because it is not borrowed by them."

    def available_books(self):
        """
        Returns a list of books that are currently available for borrowing.
        """
        return list(self.books - self.borrowed_books.keys())"]

