["def enhanced_fizzbuzz(n, mappings=None, return_dict=False):
    """
    Generates the FizzBuzz values for a range from 1 to N with custom mappings.

    Arguments:
    n : int : The upper limit of numbers (1 to N) to consider. Must be at least 1.
    mappings : dict : A dictionary where keys are integers and values are strings to replace multiples of the key. Default is {3: "Fizz", 5: "Buzz"}.
    return_dict : bool : If True, the function returns a dictionary mapping each integer to its FizzBuzz value. Otherwise, it returns a list. Default is False.

    Returns:
    List or Dictionary : A list or dictionary with numbers from 1 to N replaced according to the mappings and rules.
    """
    if not isinstance(n, int) or n < 1:
        raise ValueError("The upper limit 'n' must be an integer greater than or equal to 1.")

    if mappings is None:
        mappings = {3: "Fizz", 5: "Buzz"}

    final_mappings = {int(k): str(v) for k, v in mappings.items()}

    result = {}

    for i in range(1, n + 1):
        s = ''
        for k, v in final_mappings.items():
            if i % k == 0:
                s += v
        result[i] = s if s else i

    return result if return_dict else list(result.values())"]

