["from collections import defaultdict, deque

def find_task_ordering(n, tasks):
    graph = defaultdict(list)
    indegree = defaultdict(int)

    for task in tasks:
        parts = task.split()
        current_task = parts[0]
        dependencies = parts[1:]

        if current_task not in indegree:
            indegree[current_task] = 0

        for dependency in dependencies:
            graph[dependency].append(current_task)
            indegree[current_task] += 1

            if dependency not in indegree:
                indegree[dependency] = 0

    queue = deque([task for task in indegree if indegree[task] == 0])

    ordered_tasks = []

    while queue:
        current = queue.popleft()
        ordered_tasks.append(current)

        for neighbor in graph[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(ordered_tasks) != len(indegree):
        return "No valid ordering"

    return ordered_tasks"]

