["import time

class TrafficLight:
    def __init__(self):
        self.states = ["Red", "Green", "Yellow"]
        self.current_state_index = 0

    def get_current_state(self):
        return self.states[self.current_state_index]

    def next_state(self):
        self.current_state_index = (self.current_state_index + 1) % len(self.states)

    def run_cycle(self, duration):
        """
        Runs a single traffic light cycle (Red -> Green -> Yellow -> Red)

        duration: Time (in seconds) each state should last
        """
        for _ in range(len(self.states)):
            print(f"Traffic Light is now {self.get_current_state()}")
            time.sleep(duration)
            self.next_state()

class PedestrianCrossing:
    def __init__(self, traffic_light):
        self.traffic_light = traffic_light
        self.requested = False

    def request_crossing(self):
        self.requested = True

    def handle_request(self):
        if self.requested and self.traffic_light.get_current_state() == "Red":
            print("Pedestrians can now cross.")
            self.requested = False
        else:
            print("Pedestrians cannot cross yet.")

