class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def is_balanced(root: Optional[TreeNode]) -> bool:
    def check_balance(node):
        if not node:
            return 0, True

        left_height, left_balanced = check_balance(node.left)
        right_height, right_balanced = check_balance(node.right)

        if not left_balanced or not right_balanced:
            return 0, False

        if abs(left_height - right_height) > 1:
            return 0, False

        return 1 + max(left_height, right_height), True

    _, balanced = check_balance(root)
    return balanced

# Helper function to build tree from level-order list
def build_tree_from_level_order(data):
    if not data:
        return None
    root = TreeNode(data[0])
    queue = [root]
    i = 1
    while i < len(data):
        current = queue.pop(0)
        if data[i] is not None:
            current.left = TreeNode(data[i])
            queue.append(current.left)
        i += 1
        if i < len(data) and data[i] is not None:
            current.right = TreeNode(data[i])
            queue.append(current.right)
        i += 1
    return root"]

["MOD = 10**9 + 7

def unique_paths(grid):
    """
    Function to calculate the number of unique paths in a grid where some cells may be blocked.
    The function returns the result modulo 10^9 + 7.
    """
    N = len(grid)
    M = len(grid[0])

    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[-1][-1]

