                return 0
            return prefix[i][j]

        return (safe_get(i2, j2) - safe_get(i1 - 1, j2) - safe_get(i2, j1 - 1) + safe_get(i1 - 1, j1 - 1))

    # Step 1: Create prefix sum matrix
    prefix = [[0] * m for _ in range(n)]
