["from datetime import datetime, timedelta
import pytz

class Event:
    def __init__(self, title, event_date, priority):
        self.title = title
        self.event_date = event_date
        self.priority = priority

    def __lt__(self, other):
        if self.event_date == other.event_date:
            return self.priority < other.priority
        return self.event_date < other.event_date

    def __eq__(self, other):
        return (self.title == other.title and
                self.event_date == other.event_date and
                self.priority == other.priority)

class EventManager:
    def __init__(self):
        self.events = []

    def add_event(self, event):
        self.events.append(event)
        self.events.sort()  # Maintain sorted order on each addition

    def upcoming_events(self, days):
        now = datetime.now(pytz.utc)
        end_date = now + timedelta(days=days)
        upcoming = [event for event in self.events if now <= event.event_date <= end_date]
        return [(e.title, e.event_date, e.priority) for e in sorted(upcoming)]

    def list_events(self):
        return [(e.title, e.event_date, e.priority) for e in sorted(self.events)]"]

