["def solve_magic_square(grid):
    """
    Solves the 5x5 magic square puzzle.
    """
    from itertools import permutations

    def is_magic_square(magic_square):
        target = 65
        # Check rows and columns
        for i in range(5):
            if sum(magic_square[i]) != target or sum(magic_square[j][i] for j in range(5)) != target:
                return False
        # Check diagonals
        if sum(magic_square[i][i] for i in range(5)) != target or sum(magic_square[i][4 - i] for i in range(5)) != target:
            return False
        return True

    def fill_square(square, remaining):
        for perm in permutations(remaining):
            idx = 0
            for i in range(5):
                for j in range(5):
                    if square[i][j] == 0:
                        square[i][j] = perm[idx]
                        idx += 1
            if is_magic_square(square):
                return square
            for i in range(5):
                for j in range(5):
                    if square[i][j] in perm:
                        square[i][j] = 0
        return None

    used_numbers = {num for row in grid for num in row if num != 0}
    remaining_numbers = [i for i in range(1, 26) if i not in used_numbers]

    return fill_square([row[:] for row in grid], remaining_numbers)"]

