["import math

class KDTreeNode:
    def __init__(self, point, left=None, right=None):
        self.point = point
        self.left = left
        self.right = right

def kd_tree_insert(root, point, depth=0):
    if root is None:
        return KDTreeNode(point)

    axis = depth % len(point)

    if point[axis] < root.point[axis]:
        root.left = kd_tree_insert(root.left, point, depth + 1)
    else:
        root.right = kd_tree_insert(root.right, point, depth + 1)

    return root


def distance_squared(point1, point2):
    return sum((x - y) ** 2 for x, y in zip(point1, point2))


def kd_tree_nearest(root, point, depth=0, best=None, best_dist=float('inf')):
    if root is None:
        return best

    axis = depth % len(point)

    here_dist = distance_squared(root.point, point)
    if here_dist < best_dist:
        best = root.point
        best_dist = here_dist

    diff = point[axis] - root.point[axis]

    close, away = (root.left, root.right) if diff < 0 else (root.right, root.left)

    best = kd_tree_nearest(close, point, depth + 1, best, best_dist)
    if abs(diff) < best_dist:
        best = kd_tree_nearest(away, point, depth + 1, best, distance_squared(point, best))

    return best


def optimized_nearest_neighbor(x, tSet):
    root = None
    for point in tSet:
        root = kd_tree_insert(root, point)
    nearest_point = kd_tree_nearest(root, x)
    return tSet[nearest_point]"]

