["from typing import List

def can_form_pairs(arr: List[int], x: int, k: int) -> bool:
    count_map = {}
    for num in arr:
        count_map[num] = count_map.get(num, 0) + 1

    pairs = 0

    for num in arr:
        complement = x - num
        if complement in count_map and count_map[num] > 0 and count_map[complement] > 0:
            if num == complement and count_map[num] < 2:
                continue

            # Form a pair
            pairs += 1
            count_map[num] -= 1
            count_map[complement] -= 1

            if pairs >= k:
                return True

    return pairs >= k"]

