# Directions for movement: Up, Down, Left, Right
DIRECTIONS = [(-1, 0), (1, 0), (0, -1), (0, 1)]

def is_valid_move(r, c, R, C, maze, visited):
    return 0 <= r < R and 0 <= c < C and maze[r][c] != '#' and maze[r][c] != 'T' and (r, c) not in visited

def can_escape_maze(maze, R, C):
    start = (0, 0)
    end = (R-1, C-1)

    if maze[start[0]][start[1]] == 'T' or maze[end[0]][end[1]] == 'T':
        return False

    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        r, c = queue.popleft()
        if (r, c) == end:
            return True

        for dr, dc in DIRECTIONS:
            nr, nc = r + dr, c + dc
            if is_valid_move(nr, nc, R, C, maze, visited):
                visited.add((nr, nc))
                queue.append((nr, nc))

    return False

def solve_mazes(test_cases):
    results = []
    for R, C, maze in test_cases:
        if can_escape_maze(maze, R, C):
            results.append("YES")
        else:
            results.append("NO")
    return results"]

