["import json
import atexit

class KeyValueStore:
    def __init__(self, filename):
        """Initialize the key-value store with the content of the file, if it exists."""
        self.filename = filename
        try:
            with open(self.filename, 'r') as file:
                self.store = json.load(file)
        except (FileNotFoundError, json.JSONDecodeError):
            self.store = {}

        atexit.register(self.save)

    def set(self, key, value):
        """Sets the value for the given key."""
        self.store[key] = value

    def get(self, key):
        """Returns the value corresponding to the key, or None if the key does not exist."""
        return self.store.get(key)

    def delete(self, key):
        """Deletes the key-value pair for the given key."""
        if key in self.store:
            del self.store[key]

    def save(self):
        """Saves the current state of the key-value store to the file."""
        with open(self.filename, 'w') as file:
            json.dump(self.store, file)"]

