def can_form_snake(N, pairs):
    graph = defaultdict(list)

    # Create the graph
    for u, v in pairs:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()

    # Perform a BFS/DFS to check if the graph is a single connected component
    def bfs(start):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    bfs(1)
    return len(visited) == N

def snake_parade(T, test_cases):
    results = []
    for i in range(T):
        N, M, pairs = test_cases[i]
        if can_form_snake(N, pairs):
            results.append("YES")
        else:
            results.append("NO")
    return results"]

