    def __init__(self, key, color, left=None, right=None, p=None):
        self.key = key
        self.color = color  # 0 for black, 1 for red
        self.left = left
        self.right = right
        self.p = p


class RBTree:
    def __init__(self):
        self.TNULL = RBNode(0, 0)
        self.root = self.TNULL

    def __search_tree_helper(self, node, key):
        if node == self.TNULL or key == node.key:
            return node

        if key < node.key:
            return self.__search_tree_helper(node.left, key)
        return self.__search_tree_helper(node.right, key)

    def searchTree(self, k):
        return self.__search_tree_helper(self.root, k)

    def __rb_transplant(self, u, v):
        if u.p == None:
            self.root = v
        elif u == u.p.left:
            u.p.left = v
        else:
            u.p.right = v
        v.p = u.p

    def __minimum(self, node):
        while node.left != self.TNULL:
            node = node.left
        return node

    def __delete_node_helper(self, node, key):
        z = self.TNULL
        while node != self.TNULL:
            if node.key == key:
                z = node

            if node.key <= key:
                node = node.right
            else:
                node = node.left

        if z == self.TNULL:
            print("Couldn't find key in the tree")
            return

        y = z
        y_original_color = y.color
        if z.left == self.TNULL:
            x = z.right
            self.__rb_transplant(z, z.right)
        elif z.right == self.TNULL:
            x = z.left
            self.__rb_transplant(z, z.left)
        else:
            y = self.__minimum(z.right)
            y_original_color = y.color
            x = y.right
            if y.p == z:
                x.p = y
            else:
                self.__rb_transplant(y, y.right)
                y.right = z.right
                y.right.p = y

            self.__rb_transplant(z, y)
            y.left = z.left
            y.left.p = y
            y.color = z.color

        if y_original_color == 0:
            self.__fix_delete(x)

    def __fix_delete(self, x):
        while x != self.root and x.color == 0:
            if x == x.p.left:
                s = x.p.right
                if s.color == 1:
                    s.color = 0
                    x.p.color = 1
                    self.__left_rotate(x.p)
                    s = x.p.right

                if s.left.color == 0 and s.right.color == 0:
