["class Matrix:
    def __init__(self, n, matrix):
        self.n = n
        self.matrix = matrix
        self.prefix_sum = self._build_prefix_sum(matrix)

    def _build_prefix_sum(self, matrix):
        """Build the initial prefix sum matrix for fast submatrix sum queries."""
        prefix_sum = [[0] * self.n for _ in range(self.n)]
        for i in range(self.n):
            for j in range(self.n):
                prefix_sum[i][j] = matrix[i][j]
                if i > 0:
                    prefix_sum[i][j] += prefix_sum[i-1][j]
                if j > 0:
                    prefix_sum[i][j] += prefix_sum[i][j-1]
                if i > 0 and j > 0:
                    prefix_sum[i][j] -= prefix_sum[i-1][j-1]
        return prefix_sum

    def update(self, i, j, x):
        """Updates the value at matrix[i][j] to x."""
        old_val = self.matrix[i][j]
        delta = x - old_val
        self.matrix[i][j] = x

        # Update the prefix sum matrix accordingly
        for p in range(i, self.n):
            for q in range(j, self.n):
                self.prefix_sum[p][q] += delta

    def sum_region(self, r1, c1, r2, c2):
        """Returns the sum of the submatrix from (r1, c1) to (r2, c2)."""
        total = self.prefix_sum[r2][c2]
        if r1 > 0:
            total -= self.prefix_sum[r1-1][c2]
        if c1 > 0:
            total -= self.prefix_sum[r2][c1-1]
        if r1 > 0 and c1 > 0:
            total += self.prefix_sum[r1-1][c1-1]
        return total

def process_queries(n, matrix, queries):
    mtx = Matrix(n, matrix)
    results = []
    for query in queries:
        parts = list(map(int, query.split()))
        if parts[0] == 1:
            _, i, j, x = parts
            mtx.update(i, j, x)
        elif parts[0] == 2:
            _, r1, c1, r2, c2 = parts
            results.append(mtx.sum_region(r1, c1, r2, c2))
    return results"]

