["def is_graph_strongly_connected(vertex_count, edges):
    from collections import defaultdict, deque

    def bfs(start, graph):
        visited = [False] * vertex_count
        queue = deque([start])
        while queue:
            vertex = queue.popleft()
            if not visited[vertex]:
                visited[vertex] = True
                for neighbor in graph[vertex]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
        return all(visited)

    # Convert edge list to adjacency list representation
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)
    for src, dest in edges:
        graph[src].append(dest)
        reverse_graph[dest].append(src)

    # Check if all vertices are reachable from vertex 0
    if not bfs(0, graph):
        return False

    # Check if all vertices are reachable to vertex 0 (using the reverse graph)
    if not bfs(0, reverse_graph):
        return False

    return True"]

