["from collections import defaultdict, deque

class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.graph = defaultdict(list)

    def add_edge(self, u, v):
        self.graph[u].append(v)

    def get_adjacency_list(self):
        return dict(self.graph)

    def _dfs(self, v, visited, result):
        visited[v] = True
        result.append(v)
        for neighbor in self.graph[v]:
            if not visited[neighbor]:
                self._dfs(neighbor, visited, result)

    def _fill_order(self, v, visited, stack):
        visited[v] = True
        for neighbor in self.graph[v]:
            if not visited[neighbor]:
                self._fill_order(neighbor, visited, stack)
        stack = stack.append(v)

    def _transpose(self):
        g_t = Graph(self.vertices)
        for i in self.graph:
            for j in self.graph[i]:
                g_t.add_edge(j, i)
        return g_t

    def find_strongly_connected_components(self):
        stack = []
        visited = [False] * self.vertices

        for i in range(self.vertices):
            if not visited[i]:
                self._fill_order(i, visited, stack)

        transposed_graph = self._transpose()

        visited = [False] * self.vertices
        sccs = []

        while stack:
            v = stack.pop()
            if not visited[v]:
                scc = deque()
                transposed_graph._dfs(v, visited, scc)
                sccs.append(sorted(scc))

        return sorted(sccs, key=lambda x: x[0])"]

["class FenwickTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (self.n + 1)
        self.lazy = [0] * (self.n + 1)
        self.original = arr.copy()
        # Initially updating the Fenwick tree with array values
        for i in range(self.n):
            self.update_point(i, arr[i])

    def update_point(self, i, val):
        idx = i + 1
        while idx <= self.n:
            self.tree[idx] += val
            idx += idx & -idx

    def update_range(self, l, r, v):
        self._update_range(l, r, v)

    def _update_range(self, l, r, v):
        self._update(l + 1, v)
        self._update(r + 2, -v)

    def _update(self, idx, val):
        while idx <= self.n:
            self.lazy[idx] += val
            idx += idx & -idx

    def query_point(self, i):
        return self.original[i] + self._query(i + 1)

    def _query(self, idx):
        sum = 0
        while idx > 0:
            sum += self.lazy[idx]
            idx -= idx & -idx
        return sum"]

