    """

    # Check if the input is a string
    if not isinstance(cmd_input, str):
        raise TypeError("Input must be a string.")

    # Split the input into a list of words
    # This will help us to identify the command and its arguments
    command_parts = cmd_input.split()

    # Check if the command is empty
    if len(command_parts) == 0:
        return "No command given."

    # Get the main command
    main_command = command_parts[0].lower()

    # Define available commands and their actions
    available_commands = {
        "hello": lambda: "Hello! How can I assist you?",
        "goodbye": lambda: "Goodbye! Have a nice day!",
        "add": lambda: add_numbers(command_parts),
        "multiply": lambda: multiply_numbers(command_parts)
    }

    # Execute the command if available
    if main_command in available_commands:
        return available_commands[main_command]()
    else:
        return "Unknown command."

def add_numbers(parts):
    """Helper function to add numbers from command parts."""
    try:
