        return "Invalid numbers for addition."

def multiply_numbers(parts):
    """Helper function to multiply numbers from command parts."""
    try:
        result = 1
        for number in map(int, parts[1:]):
            result *= number
        return str(result)
    except ValueError:
        return "Invalid numbers for multiplication.""]

