def advanced_knapsack(items: List[Tuple[int, int]], capacity: int) -> int:
    n = len(items)
    dp = [0] * (capacity + 1)

    for value, weight in items:
        if weight == 0:
            for w in range(capacity + 1):
                dp[w] += value
        else:
            for w in range(capacity, weight - 1, -1):
                dp[w] = max(dp[w], dp[w - weight] + value)

    return max(dp)"]

