["def two_sum(numbers, target):
    """
    Binary Search Method to find the indices of the two numbers that add up to the target.
    """
    def binary_search(numbers, left, right, target):
        while left <= right:
            mid = left + (right - left) // 2
            if numbers[mid] == target:
                return mid
            elif numbers[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    for i in range(len(numbers)):
        complement = target - numbers[i]
        j = binary_search(numbers, i + 1, len(numbers) - 1, complement)
        if j != -1:
            return [i + 1, j + 1]

def two_sum1(numbers, target):
    """
    Hash Table Method to find the indices of the two numbers that add up to the target.
    """
    lookup = {}
    for i, num in enumerate(numbers):
        if target - num in lookup:
            return [lookup[target - num] + 1, i + 1]
        lookup[num] = i

def two_sum2(numbers, target):
    """
    Two Pointers Method to find the indices of the two numbers that add up to the target.
    """
    left, right = 0, len(numbers) - 1

    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
