def authenticate(server_url, username, password):
    auth_url = f"{server_url}/api/3.8/auth/signin"
    payload = {
        "credentials": {
            "name": username,
            "password": password,
            "site": {"contentUrl": ""}
        }
    }
    headers = {'Content-Type': 'application/json'}
    response = requests.post(auth_url, json=payload, headers=headers)
    if response.status_code == 200:
        return response.json()["credentials"]["token"]
    else:
        raise Exception("Authentication failed")

def get_dashboards(token):
    url = f"{server_url}/api/3.8/sites/site-id/workbooks"
    headers = {'X-Tableau-Auth': token}
    response = requests.get(url, headers=headers)
    response_tree = ET.ElementTree(ET.fromstring(response.content))
    dashboards = [wb for wb in response_tree.findall(".//workbook") if wb.get('name').startswith("Executive")]
    return dashboards

def create_view_for_datapoint(dashboard, data_point, token):
    url = f"{server_url}/api/3.8/sites/site-id/views"
    headers = {'X-Tableau-Auth': token, 'Content-Type': 'application/json'}
    payload = {
        "view": {
            "name": f"View for {data_point}",
            "dashboardId": dashboard.get('id'),
            "dataPoint": data_point
        }
    }
    response = requests.post(url, json=payload, headers=headers)
    return response.status_code == 201

def main():
    token = authenticate(server_url, username, password)
    dashboards = get_dashboards(token)
    for dashboard in dashboards:
        for data_point in data_point_names:
