["def find_min_cost_routers(universe, subsets, costs):
    from itertools import combinations

    best_cost = float('inf')
    best_routers = None

    all_routers = list(subsets.keys())

    for i in range(1, len(all_routers) + 1):
        for combo in combinations(all_routers, i):
            combined_coverage = set()
            total_cost = 0
            for router in combo:
                combined_coverage |= subsets[router]
                total_cost += costs[router]
            if combined_coverage >= universe and total_cost < best_cost:
                best_cost = total_cost
                best_routers = set(combo)

    if best_routers is not None:
        return best_routers, best_cost
    else:
        return None, 0"]

