["def minimal_delivery_path(x1, y1, x2, y2, x3, y3, x4, y4):
    """
    Calculates the minimal path for the delivery drone to complete its delivery and
    return to the warehouse while avoiding the no-fly zone.
    """
    def inside_no_fly_zone(px, py):
        """
        Checks if a point (px, py) is inside the no-fly zone.
        """
        return min(x3, x4) <= px <= max(x3, x4) and min(y3, y4) <= py <= max(y3, y4)

    def manhattan_dist(ax, ay, bx, by):
        """
        Calculates the Manhattan distance between points (ax, ay) and (bx, by).
        """
        return abs(ax - bx) + abs(ay - by)

    if not inside_no_fly_zone(x1, y1) and not inside_no_fly_zone(x2, y2):
        # Straight path possible, without intersecting no-fly zone
        return 2 * manhattan_dist(x1, y1, x2, y2)

    # Intermediate points to go around the no-fly zone
    around_path = float('inf')

    for wx, wy in [(x3 - 1, y3 - 1), (x3 - 1, y4 + 1), (x4 + 1, y3 - 1), (x4 + 1, y4 + 1)]:
        if not inside_no_fly_zone(wx, wy):
            temp_dist = manhattan_dist(x1, y1, wx, wy) + manhattan_dist(wx, wy, x2, y2) + manhattan_dist(x2, y2, wx, wy) + manhattan_dist(wx, wy, x1, y1)
            around_path = min(around_path, temp_dist)

    return around_path"]

