["from typing import List

def optimized_interpolation_search(array: List[int], search_key: int) -> int:
    """
    Implements an optimized interpolation search that adapts to non-uniform
    distributions in the sorted array. Returns the index of search_key in 
    the array if found, else returns -1.
    """
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        # Handle uniform distribution based case
        if array[high] == array[low]:
            if array[low] == search_key:
                return low
            else:
                return -1

        # Calculate the position using the interpolation formula
        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        # Ensure pos is within the array bounds
        pos = max(low, min(pos, high))

        # Check if the found position is the search key
        if array[pos] == search_key:
            return pos

        # Adjust the range based on the comparison
        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1"]

["from typing import List

def custom_comb_sort(arr: List[int], shrink: float) -> List[int]:
    """
    Sorts an array using the Comb Sort algorithm with a customizable shrink factor.
    """
    def swap(arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]

    def get_next_gap(gap):
        gap = int(gap / shrink)
        if gap < 1:
            return 1
        return gap

    n = len(arr)
    gap = n
    swapped = True

    while gap > 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                swap(arr, i, i + gap)
                swapped = True

    return arr"]

