    from collections import defaultdict, deque

    def DFS(u, disc, low, parent, time, ap):
        children = 0
        disc[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                DFS(v, disc, low, parent, time, ap)
                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    ap.add(u)
                if parent[u] != -1 and low[v] >= disc[u]:
                    ap.add(u)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    if n == 0:
        return []

    graph = defaultdict(list)
    for u, v in links:
        graph[u].append(v)
        graph[v].append(u)

    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    ap = set()

