["def is_almost_sorted(arr):
    """
    Determines whether the array is almost sorted.
    """
    def can_be_sorted_with_one_change(arr):
        """
        Checks if the array can be made non-decreasing by modifying one element.
        """
        count = 0  # Count of elements to be adjusted
        for i in range(len(arr) - 1):
            if arr[i] > arr[i + 1]:
                count += 1
                if count > 1:
                    return False
                # We try to correct the anomaly by changing arr[i] or arr[i + 1]
                if i > 0 and arr[i - 1] > arr[i + 1]:
                    arr[i + 1] = arr[i]
                else:
                    arr[i] = arr[i + 1]
        return True

    if can_be_sorted_with_one_change(arr[:]):
        return True

    return False"]

