["import heapq

def min_toll_fee(n, m, roads, s, t):
    # Create adjacency list
    graph = {i: [] for i in range(1, n+1)}
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Use Dijkstra's algorithm to find the shortest path from s to t
    pq = [(0, s)]  # (toll fee, town)
    dist = {i: float('inf') for i in range(1, n+1)}
    dist[s] = 0

    while pq:
        current_toll, current_town = heapq.heappop(pq)

        if current_town == t:
            return current_toll

        if current_toll > dist[current_town]:
            continue

        for neighbor, weight in graph[current_town]:
            new_toll = current_toll + weight
            if new_toll < dist[neighbor]:
                dist[neighbor] = new_toll
                heapq.heappush(pq, (new_toll, neighbor))

    return -1 if dist[t] == float('inf') else dist[t]"]

