["class MagicalGarden:
    def __init__(self, N):
        self.flowers = [0] * (N + 1)

    def add_flowers(self, t, k):
        self.flowers[t] += k

    def count_flowers(self, t1, t2):
        return sum(self.flowers[t1:t2+1])

def process_queries(N, queries):
    garden = MagicalGarden(N)
    result = []

    for query in queries:
        parts = list(map(int, query.split()))
        if parts[0] == 1:
            _, t, k = parts
            garden.add_flowers(t, k)
        elif parts[0] == 2:
            _, t1, t2 = parts
            result.append(garden.count_flowers(t1, t2))

    return result"]

["from typing import List, Tuple, DefaultDict
from collections import defaultdict

class GraphUndirected:
    def __init__(self):
        self.graph: DefaultDict[any, List[any]] = defaultdict(list)

    def add_edge(self, u: any, v: any) -> None:
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, node: any, visited: set) -> List[any]:
        stack = [node]
        component = []
        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            component.append(current)
            for neighbor in self.graph[current]:
                if neighbor not in visited:
                    stack.append(neighbor)
        return component

    def find_connected_components(self) -> List[List[any]]:
        visited = set()
        components = []
        for node in self.graph:
            if node not in visited:
                component = self.dfs(node, visited)
                components.append(sorted(component))
        return sorted(components, key=lambda x: x[0])

def compute_connected_components(graph_edges: List[Tuple[any, any]]) -> List[List[any]]:
    graph = GraphUndirected()
    for u, v in graph_edges:
        graph.add_edge(u, v)
    return graph.find_connected_components()"]

["def second_largest(nums: list[int]) -> int:
    if len(nums) < 2:
        raise ValueError("The list must contain at least two unique numbers.")

    first = second = float('-inf')

    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
