["from collections import deque, defaultdict

def find_compile_order(n, m, dependencies):
    indegree = [0] * (n + 1)
    graph = defaultdict(list)

    # Build the graph
    for a, b in dependencies:
        graph[a].append(b)
        indegree[b] += 1

    queue = deque([i for i in range(1, n + 1) if indegree[i] == 0])
    compile_order = []

    while queue:
        current = queue.popleft()
        compile_order.append(current)

        for neighbor in graph[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(compile_order) == n:
        return compile_order
    else:
        return "Impossible""]

["def felic_sequence(n):
    """
    Generate a Felic Sequence of length n or determine if it's impossible.
    """
    if n == 2:
        return "Impossible"

    sequence = []
    if n % 2 == 1:
        for i in range(2, n+1, 2):
            sequence.append(i)
        for i in range(1, n+1, 2):
            sequence.append(i)
    else:
        for i in range(1, n+1, 2):
            sequence.append(i)
        for i in range(2, n+1, 2):
            sequence.append(i)

    return " ".join(map(str, sequence))"]

