["def is_point_in_polygon(polygon, point):
    # Helper function for checking if a point is on a segment
    def on_segment(p, q, r):
        return (min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and
                min(p[1], r[1]) <= q[1] <= max(p[1], r[1]))

    # Helper function to find the orientation of the ordered triplet (p, q, r)
    def orientation(p, q, r):
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if val == 0:
            return 0  # colinear
        return 1 if val > 0 else 2  # clock or counterclock wise

    # Helper function to check if two segments intersect
    def do_intersect(p1, q1, p2, q2):
        o1 = orientation(p1, q1, p2)
        o2 = orientation(p1, q1, q2)
        o3 = orientation(p2, q2, p1)
        o4 = orientation(p2, q2, q1)

        if o1 != o2 and o3 != o4:
            return True

        if o1 == 0 and on_segment(p1, p2, q1):
            return True

        if o2 == 0 and on_segment(p1, q2, q1):
            return True

        if o3 == 0 and on_segment(p2, p1, q2):
            return True

        if o4 == 0 and on_segment(p2, q1, q2):
            return True

        return False

    def is_inside(polygon, p):
        n = len(polygon)
        if n < 3:
            return False

        extreme = (10**10, p[1])
        count = i = 0

        while True:
            next = (i + 1) % n

            if do_intersect(polygon[i], polygon[next], p, extreme):
                if orientation(polygon[i], p, polygon[next]) == 0:
                    return on_segment(polygon[i], p, polygon[next])

                count += 1

            i = next
            if i == 0:
                break

        return count % 2 == 1

    n = len(polygon)
    point_inside = is_inside(polygon, point)

    if not point_inside:
        return "OUTSIDE"

    for i in range(n):
        next = (i + 1) % n
        if on_segment(polygon[i], point, polygon[next]):
            return "ON EDGE"

    return "INSIDE"


def process_polygon_and_points(n, m, vertices, points):
    polygon = [tuple(vertices[i]) for i in range(n)]
    results = []
    for point in points:
        result = is_point_in_polygon(polygon, tuple(point))
        results.append(result)
    return results"]

