from typing import List, Tuple

def enhanced_bogo_sort(arr: List[int]) -> Tuple[List[int], int, List[List[int]]]:
    def is_sorted(li: List[int]) -> bool:
        return all(li[i] <= li[i+1] for i in range(len(li) - 1))

    shuffle_count = 0
    intermediate_states = []

    while not is_sorted(arr):
        intermediate_states.append(arr.copy())
        random.shuffle(arr)
        shuffle_count += 1

    intermediate_states.append(arr.copy())  # Include the final sorted state
    return arr, shuffle_count, intermediate_states"]

["def find_edges_to_remove(n, edges):
    """
    Find the minimum set of edges that, when removed, eliminate all cycles in the directed graph.
    :param n: Number of intersections (nodes)
    :param edges: List of tuples representing directed edges (u, v)
    :return: List of tuples representing the edges to be removed
    """
    from collections import defaultdict
    import heapq

    def tarjan_scc(n, edges):
        index = 0
        indices = [-1] * n
        lowlink = [-1] * n
        on_stack = [False] * n
        stack = []
        sccs = []

        def strongconnect(node):
            nonlocal index
            indices[node] = index
            lowlink[node] = index
            index += 1
            stack.append(node)
            on_stack[node] = True

            for neighbor in adjacency_list[node]:
                if indices[neighbor] == -1:
                    strongconnect(neighbor)
                    lowlink[node] = min(lowlink[node], lowlink[neighbor])
                elif on_stack[neighbor]:
                    lowlink[node] = min(lowlink[node], indices[neighbor])

            if lowlink[node] == indices[node]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    scc.append(w)
                    if w == node:
                        break
                sccs.append(scc)

        adjacency_list = defaultdict(list)
        for u, v in edges:
            adjacency_list[u-1].append(v-1)

        for i in range(n):
            if indices[i] == -1:
                strongconnect(i)

        return sccs

    def find_cycle_edges(scc):
        in_degree = defaultdict(int)
        for u in scc:
            for v in adjacency_list[u]:
                if v in scc:
                    in_degree[v] += 1

        removable_edges = []
        for u in scc:
            for v in adjacency_list[u]:
                if v in scc and in_degree[v] > 0:
                    removable_edges.append((u, v))
                    in_degree[v] -= 1

        removable_edges.sort()
        return removable_edges[0]

    sccs = tarjan_scc(n, edges)
    adjacency_list = defaultdict(list)
    for u, v in edges:
        adjacency_list[u-1].append(v-1)

    remove_edges = []
    for scc in sccs:
        if len(scc) > 1:
            edge = find_cycle_edges(scc)
            remove_edges.append((edge[0] + 1, edge[1] + 1))

    return sorted(remove_edges)"]

