from collections import defaultdict

def floyd_warshall(n, graph):
    dist = [[sys.maxsize] * n for _ in range(n)]

    for i in range(n):
        dist[i][i] = 0

    for u in range(n):
        for v in graph[u]:
            dist[u][v] = 1

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] < sys.maxsize and dist[k][j] < sys.maxsize:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

def minimize_travel_distance(n, m, roads):
    graph = defaultdict(list)

    for u, v in roads:
        graph[u-1].append(v-1)

    dist = floyd_warshall(n, graph)

    min_dist = sys.maxsize
    result = []

    for i in range(n):
        for j in range(n):
            if i != j:
                for k in range(n):
                    if i != k and j != k:
                        if dist[i][j] != sys.maxsize and dist[j][k] != sys.maxsize:
                            total_dist = dist[i][j] + dist[j][k]
                            if total_dist < min_dist:
                                min_dist = total_dist
                                result = [i+1, j+1, k+1]

    return result

def find_minimal_path(n, m, roads):
    minimal_path = minimize_travel_distance(n, m, roads)
    return minimal_path"]

