["def max_popularity_schedule(m, sessions):
    from itertools import product

    def knapsack_01_with_items(W, wt, val, n):
        K = [[0 for x in range(W + 1)] for x in range(n + 1)]
        item_incl = [[[] for x in range(W + 1)] for x in range(n + 1)]

        for i in range(n + 1):
            for w in range(W + 1):
                if i == 0 or w == 0:
                    K[i][w] = 0
                elif wt[i-1] <= w:
                    if val[i-1] + K[i-1][w-wt[i-1]] > K[i-1][w]:
                        K[i][w] = val[i-1] + K[i-1][w-wt[i-1]]
                        item_incl[i][w] = item_incl[i-1][w-wt[i-1]] + [i-1]
                    else:
                        K[i][w] = K[i-1][w]
                        item_incl[i][w] = item_incl[i-1][w]
                else:
                    K[i][w] = K[i-1][w]
                    item_incl[i][w] = item_incl[i-1][w]

        return K[n][W], item_incl[n][W]

    durations = [sessions[i][0] for i in range(len(sessions))]
    scores = [sessions[i][1] for i in range(len(sessions))]

    max_score, items_incl = knapsack_01_with_items(8, durations, scores, len(sessions))

    return len(items_incl), max_score, [i + 1 for i in items_incl]

