["import heapq

def shortest_path(m, n, edges, start, treasure):
    # Create adjacency list for the graph
    graph = {i: [] for i in range(1, m + 1)}
    for u, v, l in edges:
        graph[u].append((v, l))

    # Dijkstra's algorithm to find the shortest path
    heap = [(0, start)]  # (cost, node)
    dist = {i: float('inf') for i in range(1, m + 1)}
    dist[start] = 0

    while heap:
        current_dist, current_node = heapq.heappop(heap)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    shortest_distance = dist[treasure]
    return shortest_distance if shortest_distance != float('inf') else -1

def main(datasets):
    results = []
    for data in datasets:
        m, n = data[0]
        edges = data[1:-1]
        start, treasure = data[-1]
        results.append(shortest_path(m, n, edges, start, treasure))

    return results"]

