["from typing import List

def spiral_order(matrix: List[List[int]]) -> List[int]:
    if not matrix:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right for the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse from top to bottom for the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left for the bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top for the left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result"]

["class CustomList:
    def __init__(self, initial_data=None):
        self._data = []
        if isinstance(initial_data, CustomList):
            self._data.extend(initial_data._data)
        elif isinstance(initial_data, list):
            self._data.extend(initial_data)

    def add(self, element):
        if element in self._data:
            self._data.remove(element)
        self._data.append(element)

    def __iter__(self):
        self._index = 0
        return self

    def __next__(self):
        if self._index < len(self._data):
            result = self._data[self._index]
            self._index += 1
            return result
        else:
            raise StopIteration

    def __getitem__(self, index):
        return self._data[index]

    def __len__(self):
        return len(self._data)

    def __contains__(self, element):
        return element in self._data

    def merge(self, other):
        if isinstance(other, CustomList):
            for el in other._data:
                self.add(el)

    def __del__(self):
        del self._data"]

["def create_dict_from_list(tuple_list):
    """
    Creates a dictionary from a list where keys are tuple items and values are tuple counts.
    Then, appends an additional element to each tuple indicating if the sum of the tuple 
    (excluding the last element) is even or odd.

    Args:
    tuple_list (list of tuples): List of tuples to process.

    Returns:
    dict: Dictionary with tuple items as keys and counts as values.
    """
    tuple_dict = {}

    for t in tuple_list:
        if t in tuple_dict:
            tuple_dict[t] += 1
        else:
            tuple_dict[t] = 1

    # New dictionary holding the modified tuples and their counts
    modified_tuple_dict = {}

    for t, count in tuple_dict.items():
        sum_without_last = sum(t[:-1])
        if sum_without_last % 2 == 0:
            modified_tuple = t + ('even',)
        else:
            modified_tuple = t + ('odd',)
        modified_tuple_dict[modified_tuple] = count

    return modified_tuple_dict"]

