    def is_palindrome(s):
        return s == s[::-1]

    def longest_palindrome_in_string(s):
        n = len(s)
        max_length = 1
        for i in range(n):
            for j in range(i, n):
                sub_str = s[i:j+1]
                if is_palindrome(sub_str):
                    max_length = max(max_length, len(sub_str))
