["from collections import deque, defaultdict

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def findKDistanceNodes(root, target, K):
    if not root:
        return []

    # Build the graph from the tree
    graph = defaultdict(list)
    def build_graph(node, parent):
        if node:
            if parent:
                graph[node].append(parent)
                graph[parent].append(node)
            if node.left:
                build_graph(node.left, node)
            if node.right:
                build_graph(node.right, node)

    # Convert the tree into undirected graph
    build_graph(root, None)

    # BFS from the target node
    queue = deque([(target, 0)])
    visited = {target}
    result = []

    while queue:
        node, dist = queue.popleft()
        if dist == K:
            result.append(node.val)
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return result"]

["import json
from decimal import Decimal
from typing import Any

class Product:
    def __init__(self, product_id: str, name: str, price: Decimal, quantity: int):
        self.product_id = product_id
        self.name = name
        self.price = price
        self.quantity = quantity


def serialize_product(product: Product) -> str:
    def decimal_default(obj: Any):
        if isinstance(obj, Decimal):
            return float(obj)
        raise TypeError("Object of type 'Decimal' is not JSON serializable")

    product_dict = {
        "product_id": product.product_id,
        "name": product.name,
        "price": product.price,
        "quantity": product.quantity
    }
    return json.dumps(product_dict, default=decimal_default, separators=(',', ':'))


def deserialize_product(json_str: str) -> Product:
    def decimal_hook(dct: dict):
        if 'price' in dct:
            dct['price'] = Decimal(str(dct['price']))
        return dct

    product_dict = json.loads(json_str, object_hook=decimal_hook)
    return Product(**product_dict)"]

