def min_rooms_needed(intervals: List[Tuple[int, int]]) -> int:
    times = []
    for interval in intervals:
        times.append((interval[0], 'start'))
        times.append((interval[1], 'end'))

    times.sort()

    max_rooms = 0
    current_rooms = 0

    for time, ttype in times:
        if ttype == 'start':
            current_rooms += 1
            max_rooms = max(max_rooms, current_rooms)
        else:
            current_rooms -= 1

    return max_rooms"]

