["from math import gcd
from itertools import combinations

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve(data):
    index = 0
    results = []

    while index < len(data):
        n = int(data[index].strip())
        if n == 0:
            break

        index += 1
        outposts = []

        for _ in range(n):
            x, y, t = map(int, data[index].strip().split())
            outposts.append((x, y, t))
            index += 1

        # Array to store the time map for each outpost
        signal_map = [set() for _ in range(n)]

        for (i, (x1, y1, t1)), (j, (x2, y2, t2)) in combinations(enumerate(outposts), 2):
            d = abs(x1 - x2) + abs(y1 - y2)
            inter_time = lcm(t1, t2)

            for k in range(d, inter_time + 1, d):
                if k % t1 == 0 and k % t2 == 0:
                    signal_map[i].add(k)
                    signal_map[j].add(k)

        success_count = 0
        for signals in signal_map:
            if len(signals) == 0:
                success_count += 1
            else:
                time_slots_counter = {}
                for time in signals:
                    if time in time_slots_counter:
                        time_slots_counter[time] += 1
                    else:
                        time_slots_counter[time] = 1

                if all(count == 1 for count in time_slots_counter.values()):
                    success_count += 1

        results.append(success_count)

    return results

def main():
    import sys
    data = sys.stdin.read().strip().split("\n")
    results = solve(data)
    for result in results:
        print(result)"]

