import importlib.util
import sys
import os

class CustomFinder(importlib.abc.MetaPathFinder):
    def __init__(self, search_path):
        self._path = search_path

    def find_spec(self, fullname, path, target=None):
        module_name = fullname.split('.')[-1]
        module_path = os.path.join(self._path, f"{module_name}.py")

        if os.path.exists(module_path):
            loader = CustomLoader(module_path)
            return importlib.util.spec_from_file_location(fullname, module_path, loader=loader)
        return None

class CustomLoader(importlib.abc.Loader):
    def __init__(self, module_path):
        self._module_path = module_path

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        with open(self._module_path, 'r') as file:
            code = file.read()
        exec(code, module.__dict__)

def install_custom_importer(search_path):
    sys.meta_path.insert(0, CustomFinder(search_path))"]

["from itertools import combinations

def distinct_subsequences(s):
    """
    Given a string s, return all distinct subsequences that do not contain repeating characters, in lexicographical order.
    """
    def is_unique(subseq):
        return len(subseq) == len(set(subseq))

    unique_subsequences = set()

    for i in range(1, len(s) + 1):
        for comb in combinations(s, i):
            subseq = ''.join(comb)
            if is_unique(subseq):
                unique_subsequences.add(subseq)

    return sorted(unique_subsequences)

