["class EnhancedResizableHashTable:
    def __init__(self, initial_size=8, resize_up_factor=0.67, resize_down_factor=0.25):
        self.size = initial_size
        self.resize_up_factor = resize_up_factor
        self.resize_down_factor = resize_down_factor
        self.count = 0
        self.table = [None] * self.size

    def _hash(self, key):
        return key % self.size

    def _probe(self, key, attempt):
        return (self._hash(key) + attempt ** 2) % self.size

    def _resize(self, grow=True):
        old_table = self.table
        new_size = self.size * 2 if grow else self.size // 2
        self.size = max(new_size, 8)
        self.table = [None] * self.size
        self.count = 0

        for item in old_table:
            if item is not None:
                self.put(*item)

    def put(self, key, value):
        if self.count / self.size >= self.resize_up_factor:
            self._resize(grow=True)

        attempt = 0
        while True:
            index = self._probe(key, attempt)
            if self.table[index] is None or self.table[index][0] == key:
                self.count += (self.table[index] is None)
                self.table[index] = (key, value)
                break
            attempt += 1

    def get(self, key):
        attempt = 0
        while True:
            index = self._probe(key, attempt)
            if self.table[index] is None:
                return None
            if self.table[index][0] == key:
                return self.table[index][1]
            attempt += 1

    def del_(self, key):
        attempt = 0
        while True:
            index = self._probe(key, attempt)
            if self.table[index] is None:
                return
            if self.table[index][0] == key:
                self.table[index] = None
                self.count -= 1
                if self.count / self.size <= self.resize_down_factor:
                    self._resize(grow=False)
                break
            attempt += 1"]

["class KingQuery:
    def __init__(self, n, values, roads):
        self.n = n
        self.values = values
        self.adj = [[] for _ in range(n + 1)]

        for u, v in roads:
            self.adj[u].append(v)
            self.adj[v].append(u)

    def update_value(self, city, value):
        self.values[city - 1] = value

    def query_total_value(self, city):
        total_value = self.values[city - 1]
        for neighbor in self.adj[city]:
            total_value += self.values[neighbor - 1]
        return total_value"]

["def is_match(s: str, p: str) -> bool:
    """
    Returns True if the pattern p matches the entire string s, otherwise returns False.
    """
    memo = {}

    def dp(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(p):
            ans = i == len(s)
        else:
            first_match = i < len(s) and p[j] in {s[i], '.'}

            if j + 1 < len(p) and p[j + 1] == '*':
                ans = dp(i, j + 2) or (first_match and dp(i + 1, j))
            else:
                ans = first_match and dp(i + 1, j + 1)

        memo[(i, j)] = ans
        return ans

    return dp(0, 0)"]

