["import telnetlib

class SimpleTelnetClient:
    def __init__(self, host: str, port: int = 23, timeout: int = 10):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.connection = None

    def connect(self):
        try:
            self.connection = telnetlib.Telnet(self.host, self.port, self.timeout)
        except Exception as e:
            print(f"Failed to connect to {self.host}:{self.port}. Error: {e}")
            raise

    def login(self, username: str, password: str) -> bool:
        if not self.connection:
            print("Not connected to the server.")
            return False
        try:
            self.connection.read_until(b"login: ")
            self.connection.write(username.encode('ascii') + b"\n")
            self.connection.read_until(b"Password: ")
            self.connection.write(password.encode('ascii') + b"\n")
            response = self.connection.read_until(b"$", self.timeout)
            if b"$" in response:
                return True
            else:
                return False
        except Exception as e:
            print(f"Login failed. Error: {e}")
            return False

    def execute_commands(self, commands: list) -> list:
        if not self.connection:
            print("Not connected to the server.")
            return []
        responses = []
        try:
            for command in commands:
                self.connection.write(command.encode('ascii') + b"\n")
                response = self.connection.read_until(b"$", self.timeout).decode('ascii')
                responses.append(response)
            return responses
        except Exception as e:
            print(f"Failed to execute commands. Error: {e}")
            return []

    def disconnect(self):
        if self.connection:
            self.connection.close()
            self.connection = None

