["class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def rangeSumBST(root, low, high):
    """
    Given the root of a binary search tree, return the sum of values of all nodes with value between low and high (inclusive).
    """
    if not root:
        return 0

    total_sum = 0

    if low <= root.val <= high:
        total_sum += root.val

    if low < root.val:
        total_sum += rangeSumBST(root.left, low, high)

    if root.val < high:
        total_sum += rangeSumBST(root.right, low, high)

    return total_sum"]

