["def int_to_base(num, base):
    """
    Convert an integer to a string in the specified base.
    """
    if num == 0:
        return "0"

    is_negative = num < 0
    num = abs(num)
    digits = []

    while num:
        num, remainder = divmod(num, abs(base))
        if remainder < 10:
            digits.append(chr(48 + remainder))  # 48 is ASCII '0'
        else:
            digits.append(chr(55 + remainder))  # 55 + 10 = 65 is ASCII 'A'

    if len(digits) == 0:
        digits.append("0")

    if is_negative:
        if base < 0:
            digits.append('-')
        else:
            digits.append('-')

    return ''.join(reversed(digits))


def base_to_int(str_to_convert, base):
    """
    Convert a string in the specified base to an integer.
    """
    str_to_convert = str_to_convert.strip().upper()
    is_negative = str_to_convert.startswith('-')
    if is_negative:
        str_to_convert = str_to_convert[1:]

    num = 0
    power = 1
    for char in reversed(str_to_convert):
        if '0' <= char <= '9':
            num += (ord(char) - 48) * power  # 48 is ASCII '0'
        elif 'A' <= char <= 'Z':
            num += (ord(char) - 55) * power  # 55 + 10 = 65 is ASCII 'A'

        power *= abs(base)

    return -num if is_negative else num"]

