["import random

def miller_rabin_test(n, k):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    def power_mod(b, e, m):
        res = 1
        b = b % m
        while e > 0:
            if e % 2 == 1:
                res = (res * b) % m
            e = e >> 1
            b = (b * b) % m
        return res

    def is_composite(a, d, n, s):
        x = power_mod(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(s - 1):
            x = (x * x) % n
            if x == n - 1:
                return False
        return True

    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    for _ in range(k):
        a = random.randint(2, n - 2)
        if is_composite(a, d, n, s):
            return False
    return True

def find_primes_in_range(low, high, k):
    primes = []
    for num in range(low, high + 1):
        if miller_rabin_test(num, k):
            primes.append(num)
    return primes"]

