["import os
from typing import List, Dict, Tuple, Optional

def parse_mailcap_files(files: List[str]) -> Dict[str, List[Dict[str, str]]]:
    caps = {}
    for file in files:
        if os.path.exists(file):
            with open(file, 'r') as f:
                for line in f:
                    # Ignore comments and empty lines
                    stripped_line = line.strip()
                    if stripped_line.startswith('#') or not stripped_line:
                        continue

                    # Split MIME type and command/parameters
                    parts = stripped_line.split(';')
                    if len(parts) < 2:
                        continue

                    mimetype = parts[0].strip()
                    command = parts[1].strip()

                    entry = {'view': command}
                    for param in parts[2:]:
                        key_value = param.strip().split('=', 1)
                        if len(key_value) == 2:
                            entry[key_value[0].strip()] = key_value[1].strip()

                    if mimetype not in caps:
                        caps[mimetype] = []
                    caps[mimetype].append(entry)
    return caps

def find_command(caps: Dict[str, List[Dict[str, str]]], MIMEtype: str, key: str = 'view', filename: str = '/dev/null', plist: List[str] = []) -> Tuple[Optional[str], Optional[Dict[str, str]]]:
    valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@+=:,./-_')

    # Validate filename
    if not set(filename).issubset(valid_chars):
        return (None, None)

    # Validate plist
    params = {}
    for item in plist:
        name_value = item.split('=', 1)
        if len(name_value) != 2 or not set(name_value[1]).issubset(valid_chars):
            return (None, None)
        params[name_value[0]] = name_value[1]

    if MIMEtype in caps:
        for entry in caps[MIMEtype]:
            if key in entry:
                command = entry[key]
                # Replace %s in command with filename
                command = command.replace('%s', filename)

                # Replace %{name} with the value from params
                for name, value in params.items():
                    command = command.replace(f'%{{{name}}}', value)

                return (command, entry)

    return (None, None)"]

