["def count_sentences(s: str, dictionary: set) -> int:
    memo = {}

    def dfs(start):
        if start == len(s):
            return 1
        if start in memo:
            return memo[start]

        count = 0
        for end in range(start + 1, len(s) + 1):
            if s[start:end] in dictionary:
                count += dfs(end)

        memo[start] = count
        return count

    return dfs(0)"]

