["from collections import defaultdict, deque

def can_color_trees(n, m, edges):
    def bfs(start):
        queue = deque([start])
        colors[start] = 0
        group1, group2 = set([start+1]), set()

        while queue:
            node = queue.popleft()
            curr_color = colors[node]

            for neighbor in graph[node]:
                if neighbor not in colors:
                    colors[neighbor] = 1 - curr_color
                    if colors[neighbor] == 0:
                        group1.add(neighbor + 1)
                    else:
                        group2.add(neighbor + 1)
                    queue.append(neighbor)
                elif colors[neighbor] == curr_color:
                    return -1, -1

        return group1, group2

    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    colors = {}
    all_group1, all_group2 = set(), set()
    for node in range(n):
        if node not in colors:
            group1, group2 = bfs(node)
            if group1 == -1:
                return -1
            all_group1.update(group1)
            all_group2.update(group2)

    return list(all_group1), list(all_group2)"]

["def largest_square_in_grid(T, test_cases):
    results = []

    for case in test_cases:
        N, grid = case
        max_side_length = 0
        dp = [[0] * N for _ in range(N)]

        for i in range(N):
            for j in range(N):
                if grid[i][j] == '.':
                    if i == 0 or j == 0:
                        dp[i][j] = 1
                    else:
                        dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                    max_side_length = max(max_side_length, dp[i][j])

        results.append(max_side_length)

    return results

