["from itertools import combinations

def find_closest_volume(target, containers):
    n = len(containers)
    closest_volume = 0
    minimal_difference = float('inf')

    for i in range(1, n + 1):
        for combo in combinations(containers, i):
            current_volume = sum(combo)
            current_difference = abs(current_volume - target)

            if (current_difference < minimal_difference) or (current_difference == minimal_difference and current_volume > closest_volume):
                closest_volume = current_volume
                minimal_difference = current_difference

    return closest_volume"]

