["def is_palindrome(x: int) -> bool:
    s = str(x)
    return s == s[::-1]

def find_nearest_palindrome(num: int) -> int:
    if num < 0:
        raise ValueError("Input number must be non-negative")

    if is_palindrome(num):
        return num

    lower_palindrome = num - 1
    upper_palindrome = num + 1

    while not is_palindrome(lower_palindrome):
        lower_palindrome -= 1

    while not is_palindrome(upper_palindrome):
        upper_palindrome += 1

    if num - lower_palindrome <= upper_palindrome - num:
        return lower_palindrome
    else:
        return upper_palindrome"]

