["class Road:
    def __init__(self, heights):
        self.heights = heights

    def increment(self, l, r, v):
        for i in range(l - 1, r):
            self.heights[i] += v

    def query(self, l, r):
        return max(self.heights[l - 1:r])

def process_operations(n, q, heights, operations):
    road = Road(heights)
    results = []
    for operation in operations:
        if operation[0] == 1:
            _, l, r, v = operation
            road.increment(l, r, v)
        elif operation[0] == 2:
            _, l, r = operation
            results.append(road.query(l, r))
    return results"]

