["def process_transactions(start_balance: float | str, transactions: list[tuple[str, float | str]]) -> float:
    try:
        balance = float(start_balance)
    except ValueError:
        return 0.0

    if balance < 0:
        return 0.0

    for transaction in transactions:
        try:
            trans_type, amount = transaction
            amount = float(amount)
        except (ValueError, TypeError):
            return 0.0

        if trans_type == 'deposit':
            balance += amount
        elif trans_type == 'withdraw':
            if balance >= amount:
                balance -= amount
        else:
            return 0.0

    return balance"]

