["def pacific_atlantic(matrix):
    if not matrix:
        return []

    def dfs(matrix, visited, i, j):
        visited[i][j] = True
        for direction in directions:
            x, y = i + direction[0], j + direction[1]
            if 0 <= x < m and 0 <= y < n and not visited[x][y] and matrix[x][y] >= matrix[i][j]:
                dfs(matrix, visited, x, y)

    m, n = len(matrix), len(matrix[0])
    pacific_reachable = [[False] * n for _ in range(m)]
    atlantic_reachable = [[False] * n for _ in range(m)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(m):
        dfs(matrix, pacific_reachable, i, 0)
        dfs(matrix, atlantic_reachable, i, n-1)

    for j in range(n):
        dfs(matrix, pacific_reachable, 0, j)
        dfs(matrix, atlantic_reachable, m-1, j)

    result = []
    for i in range(m):
        for j in range(n):
            if pacific_reachable[i][j] and atlantic_reachable[i][j]:
                result.append([i, j])

    return result"]

