["class ArrayQueue:
    def __init__(self, capacity):
        self.queue = []
        self.capacity = capacity
        self.front = 0
        self.rear = 0

    def is_empty(self):
        return self.front == self.rear

    def is_full(self):
        return self.rear - self.front == self.capacity

    def enqueue(self, item):
        if self.is_full():
            raise OverflowError("Queue is full")
        self.queue.append(item)
        self.rear += 1

    def dequeue(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        item = self.queue[self.front]
        self.front += 1
        if self.front == self.rear:
            self.queue = []
            self.front = 0
            self.rear = 0
        return item

    def peek(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        return self.queue[self.front]

    def get_tasks(self):
        return self.queue[self.front:self.rear]


class LinkedListNode:
    def __init__(self, value=None):
        self.value = value
        self.next = None


class LinkedListQueue:
    def __init__(self, capacity):
        self.front = None
        self.rear = None
        self.capacity = capacity
        self.size = 0

    def is_empty(self):
        return self.size == 0

    def is_full(self):
        return self.size == self.capacity

    def enqueue(self, item):
        if self.is_full():
            raise OverflowError("Queue is full")
        new_node = LinkedListNode(item)
        if self.rear is None:
            self.front = new_node
            self.rear = new_node
        else:
            self.rear.next = new_node
            self.rear = new_node
        self.size += 1

    def dequeue(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        item = self.front.value
        self.front = self.front.next
        if self.front is None:
            self.rear = None
        self.size -= 1
        return item

    def peek(self):
        if self.is_empty():
            raise IndexError("Queue is empty")
        return self.front.value

    def get_tasks(self):
        tasks = []
        current = self.front
        while current:
            tasks.append(current.value)
            current = current.next
        return tasks


class TaskScheduler:
    def __init__(self, queue_type: str, capacity: int = 10):
        if queue_type.lower() == "array":
            self.queue = ArrayQueue(capacity)
        elif queue_type.lower() == "linkedlist":
            self.queue = LinkedListQueue(capacity)
        else:
            raise ValueError("Invalid queue type. Use 'array' or 'linkedlist'.")

    def add_task(self, task_id: int):
        self.queue.enqueue(task_id)

    def process_task(self) -> int:
        return self.queue.dequeue()

    def peek_task(self) -> int:
        return self.queue.peek()

    def task_list(self) -> list:
        return self.queue.get_tasks()"]

["from collections import deque

def navigate_grid(obstacles, objects, sensors, sensor_order):
    start_x, start_y = 10, 1
    goal_x, goal_y = 1, 10
    directions = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    grid_size = 10
    obstacles = set(tuple(pair) for pair in obstacles)

    def is_valid_move(x, y):
        if not (1 <= x <= grid_size and 1 <= y <= grid_size):
            return False
        if (x, y) in obstacles:
            return False
        return True

    def bfs(start, goal):
        queue = deque([(start, [])])
        visited = set()
        visited.add(start)

        while queue:
            (x, y), path = queue.popleft()

            if (x, y) == goal:
                return path

            for direction, (dx, dy) in directions.items():
                nx, ny = x + dx, y + dy
                if is_valid_move(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [direction]))

        return None

    current_position = (start_x, start_y)
    full_path = []

    for sensor_index in sensor_order:
        sensor_position = sensors[sensor_index - 1]
        path_segment = bfs(current_position, sensor_position)
        if path_segment is None:
            return "IMPOSSIBLE"
        full_path.extend(path_segment)
        current_position = sensor_position

    path_to_goal = bfs(current_position, (goal_x, goal_y))
    if path_to_goal is None:
        return "IMPOSSIBLE"

    full_path.extend(path_to_goal)
    return "\n".join(full_path)"]

