["def rearrange_houses(n, k):
    if k == 1:
        return list(range(1, n + 1))

    if n % k != 0:
        return -1

    result = []
    for i in range(n // k):
        for j in range(1, k + 1):
            result.append(i * k + j)

    return result"]

