["def path_exists(N, obstacles):
    from collections import deque

    if (1, 1) in obstacles or (N, N) in obstacles:
        return False

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = set()
    queue = deque([(1, 1)])
    visited.add((1, 1))

    while queue:
        x, y = queue.popleft()

        if (x, y) == (N, N):
            return True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= N and 1 <= ny <= N and (nx, ny) not in obstacles and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return False

def find_paths(test_cases):
    results = []
    for N, P, obstacles in test_cases:
        if path_exists(N, set(obstacles)):
            results.append("YES")
        else:
            results.append("NO")
    return results"]

