["def longest_arithmetic_sequence_length(nums):
    if len(nums) <= 1:
        return len(nums)

    dp = [{} for _ in range(len(nums))]
    max_length = 1

    for i in range(1, len(nums)):
        for j in range(i):
            diff = nums[i] - nums[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length"]

