["def sum_of_depths(tree_edges):
    from collections import defaultdict, deque

    def bfs_sum_depths(n, edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        depth_sum = {i: -1 for i in range(1, n+1)}
        depth_sum[1] = 0

        queue = deque([1])

        while queue:
            node = queue.popleft()
            current_depth = depth_sum[node]
            for neighbor in graph[node]:
                if depth_sum[neighbor] == -1:
                    depth_sum[neighbor] = current_depth + 1
                    queue.append(neighbor)

        return sum(depth_sum.values())

    results = []
    for (n, edges) in tree_edges:
        results.append(bfs_sum_depths(n, edges))

    return results"]

