["import http.client
import urllib.parse

def fetch_url_data(url: str, retries: int = 3, timeout: int = 10) -> tuple:
    parsed_url = urllib.parse.urlparse(url)
    if not parsed_url.scheme or not parsed_url.netloc:
        raise ValueError("Invalid URL")

    def make_request(retries_left: int):
        try:
            conn = http.client.HTTPConnection(parsed_url.netloc, timeout=timeout)
            conn.request('GET', parsed_url.path or "/")
            response = conn.getresponse()
            if 300 <= response.status < 400:
                redirect_url = response.getheader('Location')
                if redirect_url:
                    return fetch_url_data(redirect_url, retries_left, timeout)
            response_body = response.read().decode()
            return response.status, response.reason, response_body
        except (http.client.HTTPException, http.client.ImproperConnectionState) as e:
            if retries_left > 0:
                return make_request(retries_left - 1)
            else:
                raise ValueError("Failed to connect after several retries") from e
        finally:
            conn.close()

    return make_request(retries)"]

