def find_bridges(n, connections):
    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        discovery[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])

                if low[v] > discovery[u]:
                    bridges.append((u, v))
            elif v != parent:
                low[u] = min(low[u], discovery[v])

    graph = defaultdict(list)
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    discovery = [0] * (n + 1)
    low = [0] * (n + 1)
    bridges = []
    time = 0

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)

    return len(bridges)

def min_roads_to_disconnect(n, r, roads):
    return find_bridges(n, roads)"]

