["import socket
import select

def multi_client_server(port: int) -> None:
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind(('0.0.0.0', port))
    server_socket.listen()

    inputs = [server_socket]
    outputs = []

    clients = {}

    try:
        while True:
            readable, writable, exceptional = select.select(inputs, outputs, inputs)

            for s in readable:
                if s is server_socket:
                    client_socket, client_address = server_socket.accept()
                    client_socket.setblocking(0)
                    inputs.append(client_socket)
                    clients[client_socket] = []
                else:
                    data = s.recv(1024)
                    if data:
                        clients[s].append(data)
                        if s not in outputs:
                            outputs.append(s)
                    else:
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        del clients[s]

            for s in writable:
                try:
                    next_msg = clients[s].pop(0)
                except IndexError:
                    outputs.remove(s)
                else:
                    s.send(next_msg)

            for s in exceptional:
                inputs.remove(s)
                if s in outputs:
                    outputs.remove(s)
                s.close()
                del clients[s]
    finally:
        server_socket.close()"]

