        return str(self.queue)

    def rotate_queue(self, positions: int) -> None:
        """Rotate the elements in the queue by the given number of positions."""
        if self.is_empty():
            return

        n = self.size()
        positions = positions % n  # Normalize positions

        if positions > 0:
            for _ in range(positions):
                self.enqueue(self.dequeue())
        else:
            for _ in range(-positions):
                self.queue.insert(0, self.queue.pop())

