["import asyncio

class LineDelimitedProtocol(asyncio.BufferedProtocol):
    def __init__(self):
        self.buffer = bytearray()
        self.transport = None

    def connection_made(self, transport):
        self.transport = transport
        print("Connection made")

    def connection_lost(self, exc):
        print("Connection lost")
        if exc:
            print(f"Connection lost with error: {exc}")

    def get_buffer(self, sizehint):
        extra_space = len(self.buffer) + sizehint
        if extra_space > len(self.buffer):
            self.buffer.extend(b'\0' * (extra_space - len(self.buffer)))
        return memoryview(self.buffer)[len(self.buffer):]

    def buffer_updated(self, nbytes):
        self.buffer = self.buffer[:-nbytes]
        self.buffer.extend(bytes(memoryview(self.buffer)[-nbytes:]))
        while b'\n' in self.buffer:
            line, self.buffer = self.buffer.split(b'\n', 1)
            self.line_received(line + b'\n')

    def eof_received(self):
        print("EOF received")
        if self.buffer:
            self.line_received(self.buffer)
        return None

    def line_received(self, line):
        print("Line received:", line.decode().strip())

async def main():
    loop = asyncio.get_running_loop()
    server = await loop.create_server(
        lambda: LineDelimitedProtocol(),
        '127.0.0.1', 8888)
    async with server:
        await server.serve_forever()

if __name__ == "__main__":
    asyncio.run(main())"]

