["def longest_substring_with_k_repeats(s, k):
    def helper(start, end, k):
        if end - start < k:
            return 0

        count = [0] * 26
        for i in range(start, end):
            count[ord(s[i]) - ord('a')] += 1

        for mid in range(start, end):
            if count[ord(s[mid]) - ord('a')] >= k:
                continue

            mid_next = mid + 1
            while mid_next < end and count[ord(s[mid_next]) - ord('a')] < k:
                mid_next += 1

            return max(helper(start, mid, k), helper(mid_next, end, k))

        return end - start

    return helper(0, len(s), k)"]

