["from collections import defaultdict
import heapq

class FlightManager:
    def __init__(self, n):
        self.n = n
        self.graph = defaultdict(list)

    def addFlight(self, u, v, w):
        self.graph[u].append((v, w))

    def minTravelCosts(self, queries):
        def dijkstra(source):
            min_heap = [(0, source)]
            distances = {i: float('inf') for i in range(self.n)}
            distances[source] = 0

            while min_heap:
                current_distance, u = heapq.heappop(min_heap)

                if current_distance > distances[u]:
                    continue

                for neighbor, weight in self.graph[u]:
                    distance = current_distance + weight

                    if distance < distances[neighbor]:
                        distances[neighbor] = distance
                        heapq.heappush(min_heap, (distance, neighbor))

            return distances

        results = []
        for query in queries:
            src, dest = query
            distances = dijkstra(src)
            results.append(distances[dest] if distances[dest] != float('inf') else -1)

        return results"]

["def card_rank_to_num(card):
    rank = card[0]
    if rank in '23456789':
        return int(rank)
    elif rank == 'T':
        return 10
    elif rank == 'J':
        return 11
    elif rank == 'Q':
        return 12
    elif rank == 'K':
        return 13
    elif rank == 'A':
        return 14

def analyze_hand(hand):
    suits = [card[1] for card in hand]
    ranks = sorted([card_rank_to_num(card) for card in hand])

    is_flush = len(set(suits)) == 1
    is_straight = all(ranks[i] + 1 == ranks[i + 1] for i in range(len(ranks) - 1))

    counts = {rank: ranks.count(rank) for rank in set(ranks)}
    counts_values = sorted(counts.values(), reverse=True)

    if is_flush and is_straight:
        return "Straight Flush"
    elif counts_values == [4, 1]:
        return "Four of a Kind"
    elif counts_values == [3, 2]:
        return "Full House"
    elif is_flush:
        return "Flush"
    elif is_straight:
        return "Straight"
    elif counts_values == [3, 1, 1]:
        return "Three of a Kind"
    elif counts_values == [2, 2, 1]:
        return "Two Pair"
    elif counts_values == [2, 1, 1, 1]:
        return "One Pair"
    else:
        return "High Card"

def best_hand_rank(n, hands):
    results = []
    for hand in hands:
        formatted_hand = hand.split()
        results.append(analyze_hand(formatted_hand))
    return results"]

