["def compress_string(s):
    """
    Compresses the input string using the custom run-length encoding scheme.
    """
    if not s:
        return ""

    compressed = []
    n = len(s)
    count = 1

    for i in range(1, n):
        if s[i] == s[i - 1]:
            count += 1
        else:
            if count == 1:
                compressed.append(s[i - 1])
            else:
                while count > 9:
                    compressed.append(s[i - 1] + '9')
                    count -= 9
                compressed.append(s[i - 1] + str(count))
            count = 1

    # Handling the last sequence
    if count == 1:
        compressed.append(s[-1])
    else:
        while count > 9:
            compressed.append(s[-1] + '9')
            count -= 9
        compressed.append(s[-1] + str(count))

    return ''.join(compressed)"]

