["def manage_tasks(commands):
    tasks = []
    output = []
    priority_order = {"urgent": 1, "high": 2, "medium": 3, "low": 4}

    def sort_by_deadline(task):
        return task["deadline"]

    def sort_by_priority(task):
        return priority_order[task["priority"]]

    for command in commands:
        if command[0] == "add":
            _, task_name, deadline, priority = command
            tasks.append({"name": task_name, "deadline": deadline, "priority": priority})

        elif command[0] == "update":
            _, task_name, new_deadline, new_priority = command
            for task in tasks:
                if task["name"] == task_name:
                    if new_deadline is not None:
                        task["deadline"] = new_deadline
                    if new_priority is not None:
                        task["priority"] = new_priority
                    break

        elif command[0] == "list_deadline":
            sorted_tasks = sorted(tasks, key=sort_by_deadline)
            output.append(sorted_tasks)

        elif command[0] == "list_priority":
            sorted_tasks = sorted(tasks, key=sort_by_priority)
            output.append(sorted_tasks)

    return output"]

