["def min_max_weight(n, weights, k):
    def canDistribute(maxWeight):
        current_bin = 1
        current_weight = 0
        for weight in weights:
            if current_weight + weight > maxWeight:
                current_bin += 1
                current_weight = weight
                if current_bin > k:
                    return False
            else:
                current_weight += weight
        return True

    left, right = max(weights), sum(weights)
    while left < right:
        mid = (left + right) // 2
        if canDistribute(mid):
            right = mid
        else:
            left = mid + 1
    return left"]

