def count_paths(n, m, grid):
    # Initialize a 2D dp array with zeroes
    dp = [[0]*m for _ in range(n)]

    # Base case: start at (0, 0)
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[n-1][m-1]

