["class LehaArray:
    def __init__(self, arr, queries):
        self.arr = arr
        self.queries = queries

    def set_value(self, i, v):
        self.arr[i - 1] = v

    def range_sum(self, i, j):
        return sum(self.arr[i - 1: j])

    def process_queries(self):
