["def can_transform(s):
    """
    Determines if it's possible to transform the string into a string with no adjacent repeating characters by deleting at most one character.
    """
    def is_valid(s):
        for i in range(len(s) - 1):
            if s[i] == s[i + 1]:
                return False
        return True

    if is_valid(s):
        return "YES"

    for i in range(len(s)):
        if is_valid(s[:i] + s[i + 1:]):
            return "YES"

    return "NO"

def solve(T, strings):
    results = []
    for s in strings:
        results.append(can_transform(s))
