def find_max_length_subarray(arr: List[int]) -> int:
    if len(arr) == 0:
        return 0

    count = {}
    max_len = 0

    for num in arr:
        if num not in count:
            count[num] = 1
        else:
            count[num] += 1

        # Check length of subarray with elements num and num+1
        current_len = count[num] + count.get(num + 1, 0)
        max_len = max(max_len, current_len)

        # Check length of subarray with elements num and num-1
        current_len = count[num] + count.get(num - 1, 0)
        max_len = max(max_len, current_len)

    return max_len"]

