["class Stack:
    def __init__(self):
        self.stack = []

    def push(self, x):
        self.stack.append(x)

    def pop(self):
        if self.stack:
            return self.stack.pop()

    def top(self):
        if self.stack:
            return self.stack[-1]

def stack_operations(operations):
    result = []
    stack = Stack()
    for operation in operations:
        parts = operation.split()
        op_type = int(parts[0])
        if op_type == 1:
            x = int(parts[1])
            stack.push(x)
        elif op_type == 2:
            stack.pop()
        elif op_type == 3:
            result.append(stack.top())
    return result"]

