["def min_distance(word1: str, word2: str) -> int:
    """
    Given two words word1 and word2, returns the minimum number of steps required to make
    the two words the same where in each step you can delete one character in either string.
    """
    m, n = len(word1), len(word2)

    # Create a 2D DP array with dimensions (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If word1 is empty, we need to delete all characters of word2
            elif j == 0:
                dp[i][j] = i  # If word2 is empty, we need to delete all characters of word1
            elif word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # If the characters match, no deletions are required
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1  # Choose the best option between deleting from word1 or word2

    return dp[m][n]"]

