["def optimal_game_sequence(sequence):
    n = len(sequence)
    dp = [[0] * n for _ in range(n)]
    sum_sequence = [[0] * n for _ in range(n)]

    for i in range(n):
        sum_sequence[i][i] = sequence[i]
        for j in range(i + 1, n):
            sum_sequence[i][j] = sum_sequence[i][j - 1] + sequence[j]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if i == j:
                dp[i][j] = sequence[i]
            else:
                dp[i][j] = sum_sequence[i][j] - min(dp[i + 1][j], dp[i][j - 1])

    alice_score = dp[0][n - 1]
    bob_score = sum(sequence) - alice_score
    return alice_score, bob_score


def game_results(test_cases):
    results = []
    for test_case in test_cases:
        n, sequence = test_case
        if n > 0:
            results.append(optimal_game_sequence(sequence))
    return results"]

