["from collections import deque

class MultiZigZagIterator:
    def __init__(self, lists):
        self.queue = deque()
        for i, lst in enumerate(lists):
            if lst:
                self.queue.append((i, 0, lst))

    def next(self):
        if not self.has_next():
            return None
        index, elem_index, lst = self.queue.popleft()
        val = lst[elem_index]
        if elem_index + 1 < len(lst):
            self.queue.append((index, elem_index + 1, lst))
        return val

    def has_next(self):
        return bool(self.queue)"]

