["from optparse import OptionParser, OptionGroup
import os
import shutil

def copy_file(src, dest):
    try:
        shutil.copy(src, dest)
        print(f'Copied {src} to {dest}')
    except Exception as e:
        print(f'Error while copying file: {e}')

def move_file(src, dest):
    try:
        shutil.move(src, dest)
        print(f'Moved {src} to {dest}')
    except Exception as e:
        print(f'Error while moving file: {e}')

def delete_file(filepath):
    try:
        os.remove(filepath)
        print(f'Deleted {filepath}')
    except Exception as e:
        print(f'Error while deleting file: {e}')

def list_files(directory):
    try:
        files = os.listdir(directory)
        print(f'Files in {directory}:')
        for file in files:
            print(file)
    except Exception as e:
        print(f'Error while listing files: {e}')

def main():
    usage = "usage: %prog [options] arg"
    parser = OptionParser(usage=usage)

    # Define Option Groups
    file_operations = OptionGroup(parser, "File Operations", "Options to copy, move, or delete files.")
    dir_operations = OptionGroup(parser, "Directory Operations", "Options to list files in a directory.")

    # Add Options to Groups
    file_operations.add_option("-c", "--copy", nargs=2, dest="copy", help="Copy file from SOURCE to DEST")
    file_operations.add_option("-m", "--move", nargs=2, dest="move", help="Move file from SOURCE to DEST")
    file_operations.add_option("-d", "--delete", nargs=1, dest="delete", help="Delete FILE")
    dir_operations.add_option("-l", "--list", nargs=1, dest="list", help="List all files in DIRECTORY [default: current directory]")

    # Add Groups to Parser
    parser.add_option_group(file_operations)
    parser.add_option_group(dir_operations)

    # Parse Arguments
    (options, args) = parser.parse_args()

    # Handle Options
    if options.copy:
        copy_file(options.copy[0], options.copy[1])
    elif options.move:
        move_file(options.move[0], options.move[1])
    elif options.delete:
        delete_file(options.delete)
    elif options.list:
        list_files(options.list[0])
    else:
        list_files(os.getcwd())

if __name__ == "__main__":
    main()"]

["def evaluate_expression(expression: str) -> int:
    def precedence(op: str) -> int:
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def apply_op(a: int, b: int, op: str) -> int:
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b

    def evaluate(tokens: list) -> int:
        # Stack to store integers
        values = []
        # Stack to store operators
        ops = []
        i = 0

        while i < len(tokens):
            if tokens[i] == ' ':
                i += 1
                continue
            elif tokens[i] == '(':
                ops.append(tokens[i])
            elif tokens[i].isdigit():
                val = 0
                while (i < len(tokens) and tokens[i].isdigit()):
                    val = val * 10 + int(tokens[i])
                    i += 1
                values.append(val)
                i -= 1
            elif tokens[i] == ')':
                while len(ops) != 0 and ops[-1] != '(':
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.pop()
            else:
                while (len(ops) != 0 and precedence(ops[-1]) >= precedence(tokens[i])):
                    val2 = values.pop()
                    val1 = values.pop()
                    op = ops.pop()
                    values.append(apply_op(val1, val2, op))
                ops.append(tokens[i])
            i += 1

        while len(ops) != 0:
            val2 = values.pop()
            val1 = values.pop()
            op = ops.pop()
            values.append(apply_op(val1, val2, op))

        return values[-1]

    return evaluate(list(expression))"]

