["import json

def process_employee_data(json_string):
    employees = json.loads(json_string)
    if not employees:
        return {}

    departments = {}

    for emp in employees:
        if not all(k in emp for k in ("name", "age", "department", "salary", "years_of_experience", "is_manager")):
            raise ValueError(f"Missing fields in employee data for {emp.get('name', 'unknown name')}")

        try:
            age = int(emp["age"])
            salary = float(emp["salary"])
            years_of_experience = int(emp["years_of_experience"])
            is_manager = bool(emp["is_manager"])
        except ValueError as e:
            raise TypeError(f"Incorrect field type in employee data for {emp['name']}: {e}")

        dept = emp["department"]
        if dept not in departments:
            departments[dept] = {
                'total_salary': 0.0,
                'total_age': 0,
                'num_employees': 0,
                'num_managers': 0,
                'total_years_of_experience': 0,
                'max_salary': 0.0
            }

        departments[dept]['total_salary'] += salary
        departments[dept]['total_age'] += age
        departments[dept]['num_employees'] += 1
        if is_manager:
            departments[dept]['num_managers'] += 1
        departments[dept]['total_years_of_experience'] += years_of_experience
        if salary > departments[dept]['max_salary']:
            departments[dept]['max_salary'] = salary

    for dept in departments:
        departments[dept]['average_salary'] = departments[dept]['total_salary'] / departments[dept]['num_employees']
        departments[dept]['average_age'] = departments[dept]['total_age'] / departments[dept]['num_employees']
        departments[dept]['average_years_of_experience'] = departments[dept]['total_years_of_experience'] / departments[dept]['num_employees']

        # Remove intermediate data we used for calculation
        del departments[dept]['total_salary']
        del departments[dept]['total_age']
        del departments[dept]['total_years_of_experience']

    return departments"]

