["def hcf_bitwise(x, y):
    """
    Finds the highest common factor (HCF) of two given numbers using only bitwise operators
    with time complexity O(log(min(x, y))).
    """
    if x == 0:
        return y
    if y == 0:
        return x

    shift = 0
    while not ((x | y) & 1):
        x >>= 1
        y >>= 1
        shift += 1

    while not (x & 1):
        x >>= 1

    while y != 0:
        while not (y & 1):
            y >>= 1

        if x > y:
            x, y = y, x

        y = y - x

    return x << shift"]

["import xml.sax

class IncrementalXMLParser(xml.sax.xmlreader.IncrementalParser):
    def __init__(self, element_name: str):
        super().__init__()
        self.element_name = element_name
        self.in_target_element = False
        self.collected_data = []
        self.buffer = ''
        self._content_handler = self.ContentHandler(self)
        self._parser = xml.sax.make_parser()
        self._parser.setContentHandler(self._content_handler)

    class ContentHandler(xml.sax.ContentHandler):
        def __init__(self, parent):
            self.parent = parent

        def startElement(self, name, attrs):
            if name == self.parent.element_name:
                self.parent.in_target_element = True
                self.parent.buffer = ''

        def endElement(self, name):
            if name == self.parent.element_name:
                self.parent.in_target_element = False
                self.parent.collected_data.append(self.parent.buffer)

        def characters(self, content):
            if self.parent.in_target_element:
                self.parent.buffer += content

    def feed(self, data: str):
        self._parser.feed(data)

    def close(self):
        self._parser.close()
        return self.collected_data

    def reset(self):
        self.in_target_element = False
        self.collected_data = []
        self.buffer = ''
        self._parser.reset()
        self._parser.setContentHandler(self._content_handler)"]

