["def is_possible_to_partition(s):
    """
    Returns "YES" if it is possible to rearrange the characters 
    of the string s such that all 'A's are grouped together 
    and all 'B's are grouped together, otherwise returns "NO".
    """
    if s.count('A') == 0 or s.count('B') == 0:
        return "YES"

    found_A = False
    found_B = False

    for char in s:
        if char == 'A':
            if found_B:
                return "NO"
            found_A = True
        else:
            found_B = True

    return "YES"

def solve(test_cases):
    results = []
    for s in test_cases:
        results.append(is_possible_to_partition(s))
    return results"]

