    results = []

    for n, target, array in test_cases:
        prefix_sum = [0] * (n + 1)
        suffix_sum = [0] * (n + 1)
        sums_set = set()

        for i in range(1, n + 1):
            prefix_sum[i] = prefix_sum[i - 1] + array[i - 1]

        for i in range(n - 1, -1, -1):
            suffix_sum[i] = suffix_sum[i + 1] + array[i]
            sums_set.add(suffix_sum[i])

        found = False

        for i in range(1, n):
            if prefix_sum[i] == target and (suffix_sum[i] == target or target in sums_set and prefix_sum[i] != suffix_sum[i]):
                found = True
                break

        if found:
            results.append("YES")
        else:
            results.append("NO")

