["def is_magic_square_possible(n, grid):
    target_sum = n * (n * n + 1) // 2

    def is_valid(x, y, val):
        row_sum = sum(grid[x]) + val - grid[x][y]
        col_sum = sum(grid[i][y] for i in range(n)) + val - grid[x][y]
        diag1_sum = sum(grid[i][i] for i in range(n)) if x == y else target_sum
        diag2_sum = sum(grid[i][n - 1 - i] for i in range(n)) if x == n - 1 - y else target_sum

        if row_sum != target_sum or col_sum != target_sum:
            return False
        if x == y and diag1_sum != target_sum:
            return False
        if x == n - 1 - y and diag2_sum != target_sum:
            return False
        return True

    def solve(index):
        if index == n * n:
            return all(sum(grid[i]) == target_sum for i in range(n)) and \
                   all(sum(grid[i][j] for i in range(n)) == target_sum for j in range(n)) and \
                   sum(grid[i][i] for i in range(n)) == target_sum and \
                   sum(grid[i][n - 1 - i] for i in range(n)) == target_sum

        x, y = divmod(index, n)
        if grid[x][y] != 0:
            return solve(index + 1)

        for val in range(1, n * n + 1):
            if val not in (grid[i][j] for i in range(n) for j in range(n)):
                grid[x][y] = val
                if is_valid(x, y, val):
                    if solve(index + 1):
                        return True
                grid[x][y] = 0
        return False

    if solve(0):
        return "YES"
    return "NO""]

