["def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])
        return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def min_additional_links(N, connections):
    parent = [i for i in range(N)]
    rank = [0] * N

    for u, v in connections:
        union(parent, rank, u - 1, v - 1)

    roots = len({find(parent, i) for i in range(N)})

    # Add at least (roots - 1) links
    return max(roots - 1, 0)

def process_test_cases(test_cases):
    results = []
    for N, M, edges in test_cases:
        results.append(min_additional_links(N, edges))
    return results"]

