["from typing import List, Tuple

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1] * size
        self.count = 0

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1
            self.count -= 1

    def add(self, x):
        if self.parent[x] == x:
            self.count += 1

def count_islands(n: int, m: int, positions: List[Tuple[int, int]]) -> List[int]:
    uf = UnionFind(n * m)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    grid = [[0] * m for _ in range(n)]
    result = []

    for row, col in positions:
        if grid[row][col] == 1:
            result.append(uf.count)
            continue

        grid[row][col] = 1
        index = row * m + col
        uf.add(index)

        for dr, dc in directions:
            r, c = row + dr, col + dc
            if 0 <= r < n and 0 <= c < m and grid[r][c] == 1:
                neighbor_index = r * m + c
                uf.union(index, neighbor_index)

        result.append(uf.count)

    return result"]

["def combination_sum(nums, target):
    def backtrack(start, end, path, target):
        if target == 0:
            res.append(path)
            return
        if target < 0:
            return

        for i in range(start, end):
            if i > start and nums[i] == nums[i-1]:
                continue
            backtrack(i + 1, end, path + [nums[i]], target - nums[i])

    nums.sort()
    res = []
    backtrack(0, len(nums), [], target)
    return res"]

